/* === QUESTIONS - 5 THEMES === */
const DB = [
    // === DEVISE ET SYMBOLES (Questions 1-15) ===
    { id:"db-1-001", t:1, lvl:"B1", q: "Quelle est la devise de la République française ?", o: ["Travail, Famille, Patrie", "Liberté, Égalité, Fraternité", "Honneur et Patrie", "Unité et Indivisibilité"], c: 1, e: "La devise de la République française est Liberté, Égalité, Fraternité. Elle est inscrite dans l'article 2 de la Constitution et symbolise les valeurs fondamentales héritées de la Révolution française de 1789." },
    { id:"db-1-002", t:1, lvl:"B1", q: "Quel est l'hymne national de la France ?", o: ["Le Chant des Partisans", "La Marseillaise", "L'Internationale", "La Strasbourgeoise"], c: 1, e: "La Marseillaise est l'hymne national français depuis 1795. Composée par Rouget de Lisle en 1792 à Strasbourg, elle a été adoptée comme chant de guerre de l'Armée du Rhin avant de devenir l'hymne officiel de la République." },
    { id:"db-1-003", t:1, lvl:"B1", q: "Quelles sont les trois couleurs du drapeau français, dans l'ordre ?", o: ["Rouge, Blanc, Bleu", "Bleu, Blanc, Rouge", "Blanc, Bleu, Rouge", "Bleu, Rouge, Blanc"], c: 1, e: "Le drapeau tricolore français est Bleu, Blanc, Rouge. Le bleu et le rouge représentent les couleurs de Paris, tandis que le blanc symbolisait historiquement la monarchie. Ce drapeau date de la Révolution française." },
    { id:"db-1-004", t:1, lvl:"B1", q: "Qui est Marianne dans la République française ?", o: ["La première présidente de France", "Le symbole féminin de la République", "L'épouse du Président", "Une héroïne de guerre"], c: 1, e: "Marianne est la représentation symbolique de la République française. Son buste est présent dans toutes les mairies de France. Elle incarne les valeurs républicaines de Liberté, Égalité et Fraternité." },
    { id:"db-1-005", t:1, lvl:"B1", q: "Quel jour célèbre-t-on la fête nationale française ?", o: ["Le 1er mai", "Le 8 mai", "Le 14 juillet", "Le 11 novembre"], c: 2, e: "La fête nationale française est célébrée le 14 juillet. Cette date commémore à la fois la prise de la Bastille le 14 juillet 1789 et la Fête de la Fédération du 14 juillet 1790, symbole de l'unité nationale." },
    { id:"db-1-006", t:1, lvl:"B1", q: "Quelle est la langue officielle de la République française ?", o: ["Le français et l'anglais", "Le français uniquement", "Le français et les langues régionales", "Toutes les langues"], c: 1, e: "Le français est la seule langue officielle de la République française selon l'article 2 de la Constitution qui stipule : 'La langue de la République est le français'. Cette disposition garantit l'unité linguistique du pays." },
    { id:"db-1-007", t:1, lvl:"B2", q: "Quel animal symbolique, bien que non officiel, est souvent associé à la vigilance et au courage français ?", o: ["L'aigle", "Le coq gaulois", "Le lion", "Le renard"], c: 1, e: "Le coq gaulois est un symbole historique et officieux de la France, représentant la vigilance et le courage. Bien qu'il ne figure pas dans la Constitution, il apparaît sur de nombreux monuments et équipements sportifs nationaux." },
    { id:"db-1-008", t:1, lvl:"B2", q: "Que signifie le principe constitutionnel selon lequel 'la République est indivisible' ?", o: ["Le territoire ne peut pas être vendu", "La loi s'applique de la même façon partout en France", "Les régions ne peuvent pas être autonomes", "Le gouvernement ne peut pas être dissous"], c: 1, e: "L'indivisibilité de la République, inscrite à l'article 1er de la Constitution, signifie que la loi s'applique de manière uniforme sur tout le territoire français. Ce principe garantit l'égalité de tous les citoyens devant la loi, quelle que soit leur région." },
    { id:"db-1-009", t:1, lvl:"B1", q: "Selon la Constitution, à qui appartient la souveraineté nationale ?", o: ["Au Président de la République", "Au Gouvernement", "Au peuple", "Au Parlement"], c: 2, e: "L'article 3 de la Constitution affirme que 'La souveraineté nationale appartient au peuple qui l'exerce par ses représentants et par la voie du référendum'. Cela signifie que le pouvoir politique émane des citoyens." },
    { id:"db-1-010", t:1, lvl:"B1", q: "Qu'est-ce qu'une République ?", o: ["Un pays dirigé par un roi", "Un régime où les dirigeants élus gouvernent au nom du peuple", "Un pays sans gouvernement", "Un système militaire"], c: 1, e: "Une République est un régime politique dans lequel les dirigeants sont élus et gouvernent au nom du peuple. Elle s'oppose à la monarchie où le pouvoir est héréditaire. En France, la République est fondée sur des lois que tous doivent respecter." },
    { id:"db-1-011", t:1, lvl:"B2", q: "Quel principe fondamental garantit que les libertés individuelles sont protégées par des règles que même l'État doit respecter ?", o: ["La démocratie", "L'État de droit", "La laïcité", "La souveraineté"], c: 1, e: "L'État de droit est un système dans lequel la loi s'applique à tous, y compris aux autorités publiques. Ce principe garantit que les droits et libertés de chacun sont protégés et que personne n'est au-dessus des lois." },
    { id:"db-1-012", t:1, lvl:"B1", q: "Quelle révolution historique a établi les principes de Liberté, Égalité et Fraternité ?", o: ["La Révolution industrielle", "La Révolution française de 1789", "La Révolution russe", "Mai 68"], c: 1, e: "La Révolution française de 1789 a établi les principes de Liberté, Égalité et Fraternité qui sont devenus la devise de la République. Cette révolution a marqué la fin de la monarchie absolue et le début de l'ère républicaine." },
    { id:"db-1-013", t:1, lvl:"B2", q: "Dans le contexte républicain français, que signifie concrètement le principe de 'Liberté' ?", o: ["Faire tout ce qu'on veut sans limite", "Respecter les autres dans leur intégrité et leur diversité", "Ne payer aucun impôt", "Refuser toute autorité"], c: 1, e: "La Liberté républicaine signifie respecter les autres dans leur intégrité et leur diversité. Elle implique aussi le respect de la diversité des croyances et des convictions. Les libertés individuelles sont garanties mais encadrées par le respect d'autrui et des lois." },
    { id:"db-1-014", t:1, lvl:"B1", q: "Parmi ces libertés, laquelle est garantie par la République française ?", o: ["La liberté de ne pas payer d'impôts", "La liberté d'opinion et d'expression", "La liberté de ne pas respecter les lois", "La liberté de discriminer"], c: 1, e: "La liberté d'opinion et d'expression est une liberté fondamentale garantie en France. Elle permet à chacun de penser et de s'exprimer librement, dans le respect des lois qui interdisent notamment les propos haineux ou diffamatoires." },
    { id:"db-1-015", t:1, lvl:"B2", q: "La polygamie, c'est-à-dire avoir plusieurs épouses ou époux simultanément, est-elle autorisée en France ?", o: ["Oui, si c'est une pratique religieuse", "Non, elle est strictement interdite", "Oui, avec l'accord de tous", "Oui, dans certaines régions"], c: 1, e: "La polygamie est strictement interdite en France, quelle que soit la justification invoquée. Cette interdiction découle du principe d'égalité entre les femmes et les hommes. Pratiquer la polygamie constitue un délit pénal." },

    // === ÉGALITÉ ET FRATERNITÉ (Questions 16-25) ===
    { id:"db-1-016", t:1, lvl:"B1", q: "Que signifie le principe d'Égalité dans la devise républicaine ?", o: ["Tout le monde doit gagner le même salaire", "Tous les citoyens ont les mêmes droits et devoirs", "Tout le monde doit avoir la même religion", "Les femmes et les hommes sont séparés"], c: 1, e: "Le principe d'Égalité signifie que tous les citoyens ont les mêmes droits et les mêmes devoirs, quelle que soit leur origine, leur religion, leur sexe ou leurs opinions. La loi garantit l'égalité de tous devant la justice et les institutions." },
    { id:"db-1-017", t:1, lvl:"B1", q: "En France, les hommes et les femmes ont-ils les mêmes droits ?", o: ["Non, les droits sont différents", "Oui, l'égalité est garantie par la loi", "Non, sauf dans certaines régions", "Cela dépend de la religion"], c: 1, e: "Oui, en France, les hommes et les femmes ont strictement les mêmes droits. L'égalité entre les femmes et les hommes est un principe constitutionnel. Toute discrimination fondée sur le sexe est interdite et punie par la loi." },
    { id:"db-1-018", t:1, lvl:"B2", q: "Un employeur peut-il légalement refuser d'embaucher une personne en raison de ses origines, de sa religion ou de son orientation sexuelle ?", o: ["Oui, c'est son droit en tant qu'employeur", "Non, c'est une discrimination interdite par la loi", "Oui, s'il le précise dans l'annonce", "Cela dépend du secteur d'activité"], c: 1, e: "Non, un employeur ne peut pas refuser d'embaucher quelqu'un en raison de ses origines, de sa religion, de son sexe, de son handicap ou de son orientation sexuelle. Toute discrimination à l'embauche est un délit puni par la loi française." },
    { id:"db-1-019", t:1, lvl:"B1", q: "Que signifie le principe de Fraternité ?", o: ["Avoir des frères et sœurs", "La solidarité entre les citoyens", "Vivre en famille uniquement", "Aider seulement sa propre communauté"], c: 1, e: "La Fraternité représente la solidarité entre tous les citoyens français. Elle se traduit par l'entraide collective, le financement des services publics par les impôts, et le soutien aux personnes en difficulté à travers la Sécurité sociale." },
    { id:"db-1-020", t:1, lvl:"B2", q: "Comment le principe de fraternité se manifeste-t-il concrètement dans la société française ?", o: ["Par des fêtes nationales uniquement", "Par la solidarité collective via la Sécurité sociale et les impôts", "Par l'obligation d'appartenir à une association", "Par des dons obligatoires aux églises"], c: 1, e: "Le principe de fraternité se manifeste par la solidarité collective : la Nation assure une protection aux citoyens via la Sécurité sociale, les allocations et les services publics. Payer ses impôts est un acte solidaire qui finance ces services pour tous." },
    { id:"db-1-021", t:1, lvl:"B1", q: "Qu'est-ce que la solidarité intergénérationnelle ?", o: ["Vivre avec ses grands-parents", "Le soutien mutuel entre différentes générations, comme les retraites", "Travailler dans la même entreprise familiale", "Hériter de ses parents"], c: 1, e: "La solidarité intergénérationnelle signifie que les générations se soutiennent mutuellement. Par exemple, les actifs qui travaillent aujourd'hui financent les retraites des personnes âgées par leurs cotisations sociales. C'est un principe fondamental de la fraternité républicaine." },
    { id:"db-1-022", t:1, lvl:"B2", q: "La fraternité républicaine est-elle basée sur l'appartenance ethnique ou religieuse ?", o: ["Oui, uniquement pour les Français de souche", "Non, c'est une fraternité civique ouverte à tous les citoyens", "Oui, uniquement pour les chrétiens", "Oui, selon les régions"], c: 1, e: "Non, la fraternité républicaine est une fraternité civique, et non ethnique ou religieuse. Elle repose sur la volonté de vivre ensemble en tant que citoyens, quelle que soit l'origine ou la religion. C'est un lien politique, pas communautaire." },
    { id:"db-1-023", t:1, lvl:"B1", q: "Quelle institution incarne la solidarité nationale en matière de santé ?", o: ["Les hôpitaux privés uniquement", "La Sécurité sociale", "Les pharmacies", "Les associations caritatives"], c: 1, e: "La Sécurité sociale incarne la solidarité nationale en matière de santé. Créée en 1945, elle est financée par les cotisations des travailleurs et permet de rembourser les soins médicaux pour tous, selon le principe de fraternité." },
    { id:"db-1-024", t:1, lvl:"B2", q: "Selon le principe constitutionnel, comment la Nation assure-t-elle la protection des citoyens ?", o: ["Par la charité privée uniquement", "Par une protection collective garantissant l'égalité en droit et la solidarité", "Par des dons volontaires", "Par l'aide internationale"], c: 1, e: "Selon la Constitution, la Nation assure aux individus libres et égaux en droit une protection collective. Cette solidarité se manifeste par les services publics, la Sécurité sociale, et les aides sociales financées par les impôts et cotisations." },
    { id:"db-1-025", t:1, lvl:"B1", q: "Pourquoi dit-on que payer ses impôts est un acte de fraternité ?", o: ["C'est une punition", "Cela permet de financer les services publics pour tous", "C'est réservé aux riches", "C'est facultatif"], c: 1, e: "Payer ses impôts est un acte de fraternité car cela permet de financer les services publics dont tous bénéficient : écoles, hôpitaux, routes, police, etc. C'est une contribution solidaire selon les moyens de chacun pour le bien commun." },

    // === LAÏCITÉ - PRINCIPES FONDAMENTAUX (Questions 26-35) ===
    { id:"db-1-026", t:1, lvl:"B1", q: "Qu'est-ce que la laïcité ?", o: ["L'interdiction de toutes les religions", "La neutralité de l'État face aux religions", "L'obligation d'être catholique", "La promotion de l'athéisme"], c: 1, e: "La laïcité est le principe de neutralité de l'État face aux religions. Elle garantit la liberté de conscience et sépare les affaires religieuses des affaires publiques. L'État ne privilégie ni ne combat aucune religion." },
    { id:"db-1-027", t:1, lvl:"B1", q: "En quelle année a été votée la loi de séparation des Églises et de l'État ?", o: ["1789", "1848", "1905", "1958"], c: 2, e: "La loi de séparation des Églises et de l'État a été votée en 1905. Cette loi fondamentale organise la laïcité en France en séparant clairement le pouvoir politique du pouvoir religieux, garantissant ainsi la liberté de conscience." },
    { id:"db-1-028", t:1, lvl:"B2", q: "Que garantit le principe de liberté de conscience inscrit dans la laïcité française ?", o: ["Le droit de croire uniquement à une religion reconnue", "Le droit de croire, de ne pas croire, de changer de religion ou de ne plus croire", "L'obligation de déclarer sa religion à l'État", "Le droit de critiquer uniquement certaines religions"], c: 1, e: "La liberté de conscience garantit le droit de croire, de ne pas croire, de changer de religion (droit à la conversion) et de ne plus croire (droit à l'apostasie). Elle inclut également le droit au blasphème, limité par le respect de l'ordre public." },
    { id:"db-1-029", t:1, lvl:"B1", q: "En France, est-on obligé d'avoir une religion ?", o: ["Oui, le catholicisme", "Non, la liberté de conscience est totale", "Oui, sauf autorisation spéciale", "Oui, une des trois religions monothéistes"], c: 1, e: "Non, personne n'est obligé d'avoir une religion en France. Le principe de laïcité garantit la liberté de conscience : chacun est libre de croire, de ne pas croire, ou de changer de religion à tout moment." },
    { id:"db-1-030", t:1, lvl:"B2", q: "Quel est le rôle de l'État français concernant les religions ?", o: ["Imposer une religion officielle", "Protéger la liberté religieuse tout en restant neutre", "Interdire toutes les religions", "Financer uniquement la religion catholique"], c: 1, e: "L'État français protège la liberté religieuse de tous tout en restant strictement neutre. Il garantit le libre exercice des cultes, protège les lieux de culte, lutte contre les actes antireligieux, mais ne finance ni ne privilégie aucune religion." },
    { id:"db-1-031", t:1, lvl:"B1", q: "L'État peut-il financer la construction de mosquées, d'églises ou de synagogues ?", o: ["Oui, systématiquement", "Non, en principe, en raison de la séparation des Églises et de l'État", "Oui, uniquement les églises catholiques", "Oui, sur demande du Président"], c: 1, e: "Non, en principe, l'État ne peut pas financer directement la construction de lieux de culte en raison de la loi de séparation de 1905. Cependant, il peut financer la restauration de certains édifices historiques ou des équipements culturels annexes." },
    { id:"db-1-032", t:1, lvl:"B2", q: "Qu'est-ce que le prosélytisme abusif et est-il autorisé en France ?", o: ["C'est pratiquer sa religion, c'est autorisé", "C'est exercer une pression forte pour convertir quelqu'un, c'est interdit", "C'est aller à l'église, c'est autorisé", "C'est prier en public, c'est interdit"], c: 1, e: "Le prosélytisme abusif consiste à exercer une pression forte, agressive ou manipulatrice pour forcer quelqu'un à adhérer à une religion. Cette pratique est interdite en France car elle porte atteinte à la liberté de conscience d'autrui." },
    { id:"db-1-033", t:1, lvl:"B1", q: "La laïcité interdit-elle les religions en France ?", o: ["Oui, toutes les religions sont interdites", "Non, elle garantit la liberté de pratiquer sa religion", "Oui, sauf le christianisme", "Seulement dans les grandes villes"], c: 1, e: "Non, la laïcité ne s'oppose pas aux religions. Au contraire, elle garantit la liberté de pratiquer sa religion et protège toutes les croyances. Elle organise simplement la séparation entre l'État et les institutions religieuses." },
    { id:"db-1-034", t:1, lvl:"B2", q: "Dans quelles circonstances l'État peut-il limiter l'exercice de la liberté religieuse en public ?", o: ["Jamais, la liberté est absolue", "Pour préserver l'ordre public et le respect des règles communes", "Uniquement pendant les élections", "Selon les préférences du maire"], c: 1, e: "L'État peut limiter l'exercice de la liberté religieuse en public uniquement pour préserver l'ordre public. La jurisprudence établit qu'il est interdit de se prévaloir de ses croyances pour s'affranchir des règles communes régissant les relations avec les collectivités publiques." },
    { id:"db-1-035", t:1, lvl:"B1", q: "Qui protège les lieux de culte en France ?", o: ["Les communautés religieuses uniquement", "L'État, qui garantit la sécurité des lieux de culte", "Personne, c'est interdit", "Les associations privées uniquement"], c: 1, e: "C'est l'État qui protège et sécurise les lieux de culte en France. Il lutte contre les actes antireligieux (dégradations, profanations) tout en restant neutre. Cette protection fait partie du principe de laïcité qui garantit le libre exercice des cultes." },

    // === LAÏCITÉ - APPLICATIONS PRATIQUES (Questions 36-50) ===
    { id:"db-1-036", t:1, lvl:"B1", q: "Les usagers des services publics peuvent-ils exprimer leurs convictions religieuses ?", o: ["Non, jamais", "Oui, dans le respect de l'ordre public et sans prosélytisme", "Oui, sans aucune limite", "Seulement à l'hôpital"], c: 1, e: "Oui, les usagers des services publics peuvent exprimer leurs convictions religieuses dans la limite du respect de l'ordre public. Ils doivent s'abstenir de toute forme de prosélytisme et ne peuvent pas se prévaloir de leurs croyances pour refuser les règles communes." },
    { id:"db-1-037", t:1, lvl:"B2", q: "Un usager d'un service public peut-il refuser d'être pris en charge par une personne du sexe opposé pour des raisons religieuses ?", o: ["Oui, c'est un droit absolu", "Non, on ne peut pas se prévaloir de ses croyances pour s'affranchir des règles communes", "Oui, dans tous les cas", "Oui, si c'est écrit dans le règlement"], c: 1, e: "Non, un usager ne peut pas exiger d'être pris en charge par une personne d'un sexe particulier pour des raisons religieuses. Le principe de laïcité interdit de se prévaloir de ses croyances pour s'affranchir des règles communes du service public." },
    { id:"db-1-038", t:1, lvl:"B1", q: "Les agents publics (fonctionnaires) peuvent-ils porter des signes religieux visibles au travail ?", o: ["Oui, librement", "Non, ils sont soumis au principe de stricte neutralité", "Oui, s'ils sont discrets", "Seulement en dehors du bureau"], c: 1, e: "Non, les agents publics (fonctionnaires, employés de l'État) ne peuvent pas porter de signes religieux visibles pendant leur service. Ils sont soumis au principe de stricte neutralité pour garantir l'égalité de traitement de tous les usagers." },
    { id:"db-1-039", t:1, lvl:"B2", q: "Dans le secteur privé, un employeur peut-il restreindre le port de signes religieux par ses salariés ?", o: ["Non, jamais, c'est discriminatoire", "Oui, pour des raisons d'hygiène, de sécurité ou si cela empêche le bon fonctionnement de l'entreprise", "Oui, toujours et sans justification", "Non, sauf accord écrit du salarié"], c: 1, e: "Dans le secteur privé, un employeur peut restreindre le port de signes religieux uniquement pour des impératifs justifiés : hygiène, sécurité, ou si l'exercice de cette liberté empêche réellement le bon déroulement de l'activité de l'entreprise. Il doit le justifier légalement." },
    { id:"db-1-040", t:1, lvl:"B1", q: "Les élèves des écoles publiques peuvent-ils porter des signes religieux ostensibles (très visibles) ?", o: ["Oui, librement", "Non, c'est interdit par la loi de 2004", "Oui, avec autorisation du directeur", "Seulement au lycée"], c: 1, e: "Non, la loi du 15 mars 2004 interdit aux élèves de porter des signes ou tenues manifestant ostensiblement (de manière très visible) une appartenance religieuse dans les écoles, collèges et lycées publics." },
    { id:"db-1-041", t:1, lvl:"B2", q: "Pourquoi les signes religieux ostensibles sont-ils interdits à l'école publique ?", o: ["Pour punir les religions", "Pour protéger la liberté de conscience des élèves mineurs et la neutralité de l'école", "Pour interdire toute religion", "Par tradition catholique"], c: 1, e: "Les signes religieux ostensibles sont interdits à l'école publique pour protéger la liberté de conscience de chaque enfant et préserver le bon fonctionnement de l'institution scolaire. Cela évite les pressions entre élèves et garantit la neutralité de l'enseignement." },
    { id:"db-1-042", t:1, lvl:"B1", q: "Un élève peut-il refuser certains enseignements scolaires pour des raisons religieuses ?", o: ["Oui, si ses parents le demandent", "Non, tous les enseignements sont obligatoires", "Oui, pour les cours de biologie uniquement", "Oui, pendant le ramadan"], c: 1, e: "Non, un élève ne peut pas refuser certains enseignements pour des raisons religieuses. Tous les programmes scolaires sont obligatoires. Il est interdit de contester les enseignements au nom de ses croyances, comme le précise la Charte de la laïcité à l'école." },
    { id:"db-1-043", t:1, lvl:"B2", q: "Que signifie la neutralité laïque du service public pour les usagers ?", o: ["Qu'ils n'ont aucun droit", "Que tous les usagers sont traités de façon égale, quelle que soit leur religion", "Qu'ils doivent abandonner leur religion", "Qu'ils ne peuvent pas entrer dans les administrations"], c: 1, e: "La neutralité laïque signifie que tous les usagers du service public sont traités de façon strictement égale, quelles que soient leurs croyances. Le service public ne fait aucune distinction basée sur la religion et garantit l'égalité de tous." },
    { id:"db-1-044", t:1, lvl:"B1", q: "La laïcité garantit-elle le droit au blasphème en France ?", o: ["Non, le blasphème est interdit", "Oui, la liberté de conscience inclut le droit au blasphème", "Seulement pour certaines religions", "Seulement dans les journaux"], c: 1, e: "Oui, en France, la liberté de conscience inclut le droit au blasphème, c'est-à-dire le droit de critiquer ou de se moquer des religions. Ce droit s'exerce dans le respect des lois qui interdisent les appels à la haine ou à la violence." },
    { id:"db-1-045", t:1, lvl:"B2", q: "Un détenu en prison a-t-il le droit de pratiquer sa religion ?", o: ["Non, tous les droits sont suspendus", "Oui, l'État garantit la liberté religieuse même en prison", "Seulement s'il est innocent", "Seulement pour les religions chrétiennes"], c: 1, e: "Oui, même en prison, l'État garantit la liberté religieuse. Les détenus peuvent pratiquer leur culte, recevoir la visite d'un ministre du culte et accéder à des livres religieux. La laïcité s'applique aussi dans les lieux de privation de liberté." },
    { id:"db-1-046", t:1, lvl:"B1", q: "Un professeur d'école publique peut-il porter un voile, une kippa ou une croix visible en classe ?", o: ["Oui, librement", "Non, les enseignants sont soumis à la neutralité religieuse", "Oui, si c'est discret", "Cela dépend de la région"], c: 1, e: "Non, les enseignants des écoles publiques ne peuvent pas porter de signes religieux visibles en classe. En tant qu'agents publics, ils sont soumis au principe de stricte neutralité pour garantir la laïcité de l'enseignement et l'égalité de traitement des élèves." },
    { id:"db-1-047", t:1, lvl:"B2", q: "Une infirmière travaillant dans un hôpital public peut-elle refuser de soigner un patient de sexe opposé pour des raisons religieuses ?", o: ["Oui, c'est sa liberté de conscience", "Non, elle doit assurer la continuité du service public sans discrimination", "Oui, si elle prévient à l'avance", "Cela dépend de l'urgence"], c: 1, e: "Non, une infirmière dans un hôpital public ne peut pas refuser de soigner un patient pour des raisons religieuses. Les agents publics doivent garantir la continuité du service public et l'égalité de traitement de tous les usagers, quelles que soient leurs convictions personnelles." },
    { id:"db-1-048", t:1, lvl:"B1", q: "Dans une cantine scolaire publique, doit-on obligatoirement proposer des menus adaptés à chaque religion ?", o: ["Oui, c'est obligatoire", "Non, mais des alternatives peuvent être proposées par choix de la collectivité", "Oui, pour toutes les religions reconnues", "Oui, uniquement pendant le ramadan"], c: 1, e: "Non, il n'y a aucune obligation légale de proposer des menus confessionnels dans les cantines publiques. Cependant, par choix, certaines collectivités proposent des alternatives (menu végétarien, sans porc) pour des raisons pratiques, sans que cela soit une obligation liée à la laïcité." },
    { id:"db-1-049", t:1, lvl:"B2", q: "La laïcité empêche-t-elle l'État de reconnaître officiellement des jours fériés d'origine religieuse comme Noël ou Pâques ?", o: ["Oui, c'est contraire à la laïcité", "Non, ces jours font partie du patrimoine culturel et historique français", "Oui, ils devraient être supprimés", "Seulement les fêtes catholiques sont autorisées"], c: 1, e: "Non, la laïcité n'empêche pas la reconnaissance de jours fériés d'origine religieuse. Ces jours (Noël, Pâques, Toussaint, etc.) font partie du patrimoine culturel et historique de la France. Leur reconnaissance ne contredit pas la séparation des Églises et de l'État." },
    { id:"db-1-050", t:1, lvl:"B2", q: "Un maire peut-il installer une crèche de Noël dans la mairie pour les fêtes de fin d'année ?", o: ["Oui, sans aucune restriction", "Cela dépend : si c'est culturel et festif oui, si c'est cultuel non", "Non, c'est strictement interdit", "Oui, mais seulement dans les villages"], c: 1, e: "Cela dépend du contexte : si la crèche a un caractère culturel, festif ou traditionnel, elle peut être tolérée dans certains espaces publics. Si elle a un caractère cultuel (lieu de prière, prosélytisme), elle est interdite. La jurisprudence examine au cas par cas." },
    
    // === LIBERTÉS FONDAMENTALES (Questions 51-65) ===
    { id:"db-1-051", t:1, lvl:"B1", q: "A-t-on le droit de tout dire en France ?", o: ["Oui, absolument tout sans limite", "Non, la liberté d'expression a des limites légales", "Oui, sauf devant un juge", "Non, il faut une autorisation"], c: 1, e: "Non, on n'a pas le droit de tout dire. La liberté d'expression est un droit fondamental mais elle a des limites pour respecter les droits des autres : il est interdit de diffuser des injures, des propos diffamatoires, des provocations à la haine ou de faire l'apologie de crimes." },
    { id:"db-1-052", t:1, lvl:"B1", q: "Peut-on critiquer le gouvernement ou le Président en France ?", o: ["Non, c'est interdit", "Oui, c'est un droit fondamental en démocratie", "Seulement pendant les élections", "Seulement dans les journaux"], c: 1, e: "Oui, critiquer le gouvernement ou le Président est un droit fondamental en démocratie. La liberté d'expression permet de contester les décisions politiques, tant que cela reste dans le respect des lois (pas d'injures, de menaces ou de diffamation)." },
    { id:"db-1-053", t:1, lvl:"B2", q: "Qu'est-ce que la diffamation et est-elle autorisée en France ?", o: ["C'est critiquer quelqu'un, c'est autorisé", "C'est accuser faussement quelqu'un publiquement, c'est interdit et puni", "C'est donner son opinion, c'est autorisé", "C'est un droit de la presse"], c: 1, e: "La diffamation consiste à porter atteinte à l'honneur de quelqu'un en tenant publiquement des propos mensongers. C'est un délit puni par la loi française. La liberté d'expression ne protège pas les accusations fausses qui nuisent à la réputation d'autrui." },
    { id:"db-1-054", t:1, lvl:"B1", q: "Peut-on tenir des propos racistes en France ?", o: ["Oui, c'est la liberté d'expression", "Non, c'est un délit puni par la loi", "Oui, en privé uniquement", "Cela dépend de la région"], c: 1, e: "Non, tenir des propos racistes est un délit en France, même en invoquant la liberté d'expression. La provocation à la haine raciale, les injures et la discrimination fondées sur l'origine, l'ethnie ou la religion sont punies par la loi pénale." },
    { id:"db-1-055", t:1, lvl:"B2", q: "L'apologie du terrorisme ou des crimes contre l'humanité est-elle autorisée en France ?", o: ["Oui, c'est une opinion politique", "Non, c'est un crime sévèrement puni", "Oui, si c'est sur internet", "Seulement dans un contexte artistique"], c: 1, e: "Non, l'apologie (la justification ou la glorification) du terrorisme ou des crimes contre l'humanité est un crime sévèrement puni en France. Ces actes menacent la dignité humaine et l'ordre public, et ne sont pas couverts par la liberté d'expression." },
    { id:"db-1-056", t:1, lvl:"B1", q: "Qu'est-ce que la liberté de réunion ?", o: ["Le droit de rester seul", "Le droit de se rassembler pacifiquement", "Le droit d'organiser des fêtes", "Le droit de bloquer les routes"], c: 1, e: "La liberté de réunion est le droit de se rassembler pacifiquement avec d'autres personnes. En France, ce droit est garanti mais encadré : les manifestations sur la voie publique doivent généralement être déclarées préalablement aux autorités pour des raisons d'ordre public." },
    { id:"db-1-057", t:1, lvl:"B1", q: "Peut-on manifester librement en France ?", o: ["Oui, sans aucune condition", "Oui, mais en respectant l'ordre public et après déclaration", "Non, c'est interdit", "Seulement le dimanche"], c: 1, e: "Oui, on peut manifester en France, c'est un droit constitutionnel. Cependant, les manifestations sur la voie publique doivent généralement être déclarées à la préfecture à l'avance et se dérouler dans le respect de l'ordre public (pas de violences, de dégradations)." },
    { id:"db-1-058", t:1, lvl:"B2", q: "Qu'est-ce que la liberté d'association et comment s'exerce-t-elle en France ?", o: ["Le droit de vivre en communauté fermée", "Le droit de créer ou rejoindre une association sans autorisation préalable", "Le droit de manifester", "Le droit de créer un parti politique uniquement"], c: 1, e: "La liberté d'association, garantie par la loi de 1901, permet à toute personne de créer ou de rejoindre une association sans autorisation préalable de l'État. Il suffit de déclarer l'association en préfecture. C'est un pilier de la vie démocratique et de l'engagement citoyen." },
    { id:"db-1-059", t:1, lvl:"B1", q: "Peut-on choisir librement son métier en France ?", o: ["Non, l'État décide", "Oui, c'est la liberté du travail", "Seulement certains métiers", "Seulement avec un diplôme"], c: 1, e: "Oui, la liberté du travail permet à chacun de choisir librement son métier et son employeur. Cette liberté est garantie en France, sous réserve de remplir les conditions légales (diplômes, autorisations) pour certaines professions réglementées (médecin, avocat, etc.)." },
    { id:"db-1-060", t:1, lvl:"B1", q: "A-t-on le droit de circuler librement en France ?", o: ["Non, il faut des autorisations", "Oui, la liberté de circulation est garantie", "Seulement dans sa région", "Seulement avec un passeport"], c: 1, e: "Oui, la liberté de circulation est un droit fondamental en France. Tout citoyen peut se déplacer librement sur le territoire national sans autorisation préalable, sauf circonstances exceptionnelles (état d'urgence, confinement sanitaire)." },
    { id:"db-1-061", t:1, lvl:"B2", q: "Peut-on librement choisir de se marier, de divorcer, ou de rester célibataire en France ?", o: ["Non, la famille décide", "Oui, ce sont des libertés individuelles garanties", "Non, il faut l'accord des parents", "Seulement après 30 ans"], c: 1, e: "Oui, en France, chacun est libre de choisir de se marier, de divorcer ou de rester célibataire. Ces choix relèvent de la liberté individuelle. Le mariage forcé est strictement interdit et constitue un crime puni par la loi." },
    { id:"db-1-062", t:1, lvl:"B1", q: "Le mariage forcé est-il autorisé en France ?", o: ["Oui, dans certaines cultures", "Non, c'est un crime", "Oui, avec l'accord des familles", "Cela dépend de l'âge"], c: 1, e: "Non, le mariage forcé est strictement interdit en France et constitue un crime puni par la loi. Chaque personne doit consentir librement à son mariage. Forcer quelqu'un à se marier porte atteinte à sa liberté individuelle et à sa dignité." },
    { id:"db-1-063", t:1, lvl:"B2", q: "Les couples de même sexe peuvent-ils se marier en France ?", o: ["Non, c'est interdit", "Oui, depuis la loi de 2013", "Seulement dans certaines régions", "Oui, mais sans les mêmes droits"], c: 1, e: "Oui, les couples de même sexe peuvent se marier en France depuis la loi du 17 mai 2013 ouvrant le mariage aux couples de personnes de même sexe. Ils bénéficient des mêmes droits que les couples hétérosexuels, y compris l'adoption." },
    { id:"db-1-064", t:1, lvl:"B1", q: "Qu'est-ce que la liberté syndicale ?", o: ["Le droit d'être en grève tout le temps", "Le droit de créer ou d'adhérer à un syndicat pour défendre ses droits", "Le droit de ne pas travailler", "Le droit de manifester violemment"], c: 1, e: "La liberté syndicale est le droit de créer ou d'adhérer à un syndicat pour défendre collectivement les droits des travailleurs. Les syndicats négocient avec les employeurs sur les salaires, les conditions de travail, et peuvent organiser des grèves légales." },
    { id:"db-1-065", t:1, lvl:"B1", q: "Qu'est-ce que le droit de grève ?", o: ["Le droit de ne jamais travailler", "Le droit d'arrêter temporairement le travail pour revendiquer", "Le droit de détruire l'entreprise", "Le droit de licencier les patrons"], c: 1, e: "Le droit de grève est le droit pour les salariés d'arrêter temporairement le travail pour défendre leurs revendications professionnelles (salaires, conditions de travail). Ce droit est constitutionnel en France mais doit s'exercer dans le respect des lois." },

// === ÉGALITÉ FEMMES-HOMMES ET LUTTE CONTRE LES DISCRIMINATIONS (Questions 66-80) ===
    { id:"db-1-066", t:1, lvl:"B1", q: "En France, les femmes et les hommes ont-ils le droit au même salaire pour le même travail ?", o: ["Non, les hommes gagnent toujours plus", "Oui, l'égalité salariale est un principe légal", "Non, cela dépend des entreprises", "Oui, seulement dans la fonction publique"], c: 1, e: "Oui, l'égalité salariale entre les femmes et les hommes est un principe légal en France. À travail égal, salaire égal. Les écarts de salaire injustifiés entre femmes et hommes sont interdits et peuvent être sanctionnés par la justice." },
    { id:"db-1-067", t:1, lvl:"B2", q: "Une femme enceinte peut-elle être licenciée en raison de sa grossesse ?", o: ["Oui, si l'employeur le souhaite", "Non, c'est strictement interdit et constitue une discrimination", "Oui, si elle est en période d'essai", "Cela dépend du type de contrat"], c: 1, e: "Non, licencier une femme en raison de sa grossesse est strictement interdit en France. C'est une discrimination fondée sur le sexe, sévèrement punie par la loi. Les femmes enceintes bénéficient d'une protection particulière contre le licenciement." },
    { id:"db-1-068", t:1, lvl:"B1", q: "Qu'est-ce qu'une discrimination ?", o: ["Une différence naturelle", "Une différence de traitement injuste fondée sur un critère interdit par la loi", "Une préférence personnelle", "Un choix libre"], c: 1, e: "Une discrimination est une différence de traitement injuste et illégale fondée sur un critère interdit par la loi : origine, sexe, âge, handicap, religion, orientation sexuelle, etc. Discriminer quelqu'un dans l'emploi, le logement ou l'accès aux services est un délit." },
    { id:"db-1-069", t:1, lvl:"B2", q: "Un propriétaire peut-il refuser de louer son appartement à quelqu'un en raison de son origine ou de sa religion ?", o: ["Oui, c'est son bien", "Non, c'est une discrimination interdite et punissable", "Oui, s'il le justifie", "Cela dépend de la région"], c: 1, e: "Non, refuser de louer un logement à quelqu'un en raison de son origine, de sa religion, de son nom ou de toute autre caractéristique protégée est une discrimination interdite. C'est un délit puni par la loi française, avec amendes et peines de prison possibles." },
    { id:"db-1-070", t:1, lvl:"B1", q: "Peut-on refuser l'accès à un restaurant ou un magasin à quelqu'un en raison de sa couleur de peau ?", o: ["Oui, le commerçant est libre", "Non, c'est une discrimination grave et interdite", "Oui, si c'est écrit sur la porte", "Cela dépend du type d'établissement"], c: 1, e: "Non, refuser l'accès à un lieu public (restaurant, magasin, service) en raison de la couleur de peau, de l'origine ou de toute autre caractéristique est une discrimination grave, strictement interdite et punie par la loi française." },
    { id:"db-1-071", t:1, lvl:"B1", q: "Qu'est-ce que le racisme ?", o: ["Une opinion politique", "Une idéologie qui hiérarchise les êtres humains selon leur origine", "Une préférence culturelle", "Un choix personnel"], c: 1, e: "Le racisme est une idéologie qui hiérarchise les êtres humains en fonction de leur origine, de leur couleur de peau ou de leur ethnie. En France, le racisme est fermement condamné : les actes et propos racistes sont des délits punis par la loi." },
    { id:"db-1-072", t:1, lvl:"B2", q: "Qu'est-ce que l'antisémitisme et comment est-il combattu en France ?", o: ["Une opinion religieuse légitime", "La haine envers les personnes juives, combattue par des lois strictes", "Une critique politique", "Un débat philosophique"], c: 1, e: "L'antisémitisme est la haine, l'hostilité ou les préjugés envers les personnes juives. En France, l'antisémitisme est fermement combattu : les actes et propos antisémites sont des délits punis par la loi. La lutte contre l'antisémitisme est une priorité nationale." },
    { id:"db-1-073", t:1, lvl:"B1", q: "Qu'est-ce que l'homophobie ?", o: ["La peur des hommes", "Le rejet ou la haine envers les personnes homosexuelles", "Une opinion religieuse", "Un choix personnel"], c: 1, e: "L'homophobie désigne le rejet, la discrimination ou la haine envers les personnes homosexuelles, bisexuelles ou transgenres (LGBT). En France, l'homophobie est combattue par la loi : les insultes, violences et discriminations anti-LGBT sont punies." },
    { id:"db-1-074", t:1, lvl:"B2", q: "Peut-on tenir des propos homophobes en France en invoquant ses convictions religieuses ?", o: ["Oui, la liberté religieuse le permet", "Non, les convictions religieuses ne justifient pas la discrimination", "Oui, en privé uniquement", "Cela dépend de la religion"], c: 1, e: "Non, on ne peut pas tenir de propos homophobes même en invoquant ses convictions religieuses. La liberté de religion ne permet pas de discriminer ou d'insulter autrui. Les propos homophobes sont des délits punis par la loi française." },
    { id:"db-1-075", t:1, lvl:"B1", q: "Les personnes handicapées ont-elles les mêmes droits que les autres citoyens ?", o: ["Non, elles ont moins de droits", "Oui, l'égalité des droits est garantie", "Seulement dans certains domaines", "Cela dépend du handicap"], c: 1, e: "Oui, les personnes handicapées ont exactement les mêmes droits que tous les citoyens. La loi garantit l'égalité des droits et des chances, et impose des aménagements (accessibilité, adaptation des postes de travail) pour compenser les handicaps." },
    { id:"db-1-076", t:1, lvl:"B2", q: "Qu'est-ce que la discrimination positive et existe-t-elle en France ?", o: ["Discriminer les personnes riches", "Mesures temporaires pour corriger des inégalités historiques", "Interdire l'accès aux minorités", "Favoriser systématiquement certains groupes"], c: 1, e: "La discrimination positive désigne des mesures temporaires visant à corriger des inégalités historiques ou structurelles. En France, elle est encadrée et limitée : par exemple, les quotas de femmes dans certains conseils d'administration, ou les dispositifs d'accès à l'éducation en zones défavorisées." },
    { id:"db-1-077", t:1, lvl:"B1", q: "Peut-on insulter quelqu'un en raison de son handicap ?", o: ["Oui, si c'est une blague", "Non, c'est une discrimination punissable", "Oui, en privé", "Cela dépend de la situation"], c: 1, e: "Non, insulter quelqu'un en raison de son handicap est une forme de discrimination appelée 'handiphobie', punie par la loi française. Toute injure, violence ou discrimination fondée sur le handicap est un délit passible d'amendes et de prison." },
    { id:"db-1-078", t:1, lvl:"B1", q: "Les personnes âgées peuvent-elles être victimes de discrimination ?", o: ["Non, elles ont des privilèges", "Oui, la discrimination fondée sur l'âge existe et est interdite", "Non, l'âge n'est pas un critère", "Seulement à l'embauche"], c: 1, e: "Oui, les personnes âgées peuvent être victimes de discrimination fondée sur l'âge (âgisme). En France, refuser d'embaucher, de soigner ou de servir quelqu'un en raison de son âge est une discrimination interdite par la loi." },
    { id:"db-1-079", t:1, lvl:"B2", q: "Un employeur peut-il légalement fixer une limite d'âge maximale pour recruter ?", o: ["Oui, c'est courant", "Non, sauf si l'âge est une exigence professionnelle justifiée", "Oui, pour tous les postes", "Seulement dans le privé"], c: 1, e: "Non, un employeur ne peut pas fixer de limite d'âge arbitraire pour recruter. C'est une discrimination interdite. Exception : l'âge peut être une exigence professionnelle réelle et déterminante pour certains métiers spécifiques (pilote, pompier), mais cela doit être objectivement justifié." },
    { id:"db-1-080", t:1, lvl:"B1", q: "Que doit faire une personne victime de discrimination ?", o: ["Accepter, c'est normal", "Porter plainte auprès de la police ou saisir le Défenseur des droits", "Se venger", "Déménager"], c: 1, e: "Une personne victime de discrimination doit porter plainte auprès de la police ou de la gendarmerie, et peut saisir le Défenseur des droits, une autorité indépendante qui protège les droits des citoyens. Les discriminations sont des délits qui doivent être signalés et sanctionnés." },

    // === MISES EN SITUATION - PRINCIPES RÉPUBLICAINS (Questions 81-100) ===
    { id:"db-1-081", t:1, lvl:"B1", q: "Marc pense que les femmes ne devraient pas avoir le droit de vote. Peut-il exprimer publiquement cette opinion ?", o: ["Oui, c'est la liberté d'expression", "Non, cela contredit le principe d'égalité et peut constituer une incitation à la discrimination", "Oui, si c'est sur les réseaux sociaux", "Oui, tant qu'il ne force personne"], c: 1, e: "Non, même si la liberté d'expression existe, tenir publiquement des propos remettant en cause l'égalité entre les femmes et les hommes peut constituer une incitation à la discrimination sexiste. L'égalité femmes-hommes est un principe constitutionnel fondamental." },
    { id:"db-1-082", t:1, lvl:"B2", q: "Sophie, employée dans une mairie, porte un foulard islamique visible au travail. Son responsable peut-il lui demander de l'enlever ?", o: ["Non, c'est sa liberté religieuse", "Oui, les agents publics doivent respecter la neutralité religieuse", "Non, sauf si les usagers se plaignent", "Cela dépend de la mairie"], c: 1, e: "Oui, les agents publics (employés des administrations) sont soumis au principe de stricte neutralité religieuse. Ils ne peuvent pas porter de signes religieux visibles pendant leur service. Cela garantit l'égalité de traitement de tous les usagers du service public." },
    { id:"db-1-083", t:1, lvl:"B1", q: "Emma porte un voile dans la rue. La police peut-elle lui demander de l'enlever ?", o: ["Oui, c'est interdit partout", "Non, dans l'espace public on peut porter des signes religieux", "Oui, si c'est dans une grande ville", "Oui, pendant le ramadan"], c: 1, e: "Non, dans l'espace public (rue, parc, transports), chacun est libre de porter des signes religieux. La police ne peut pas demander à Emma d'enlever son voile. La laïcité n'interdit pas l'expression religieuse dans l'espace public." },
    { id:"db-1-084", t:1, lvl:"B2", q: "Un employé travaille dans un supermarché privé et refuse de servir des clients qui achètent de l'alcool pour des raisons religieuses. L'employeur peut-il le sanctionner ?", o: ["Non, c'est sa liberté religieuse", "Oui, il doit assurer son travail sans discrimination des clients", "Non, si c'est écrit dans son contrat", "Cela dépend du client"], c: 1, e: "Oui, l'employeur peut le sanctionner. Dans le secteur privé, un salarié doit exécuter son travail conformément à son contrat. Refuser de servir certains clients pour des raisons personnelles ou religieuses constitue un manquement professionnel et peut justifier une sanction." },
    { id:"db-1-085", t:1, lvl:"B1", q: "Léa, 16 ans, veut porter une grande croix visible au collège public. Le directeur peut-il lui demander de l'enlever ?", o: ["Non, c'est sa liberté", "Oui, les signes religieux ostensibles sont interdits à l'école publique", "Non, sauf si c'est en cours", "Seulement si ses parents acceptent"], c: 1, e: "Oui, la loi de 2004 interdit le port de signes religieux ostensibles (très visibles) dans les écoles, collèges et lycées publics. Une grande croix visible entre dans cette catégorie. Cette règle protège la laïcité de l'école et la liberté de conscience des élèves." },
    { id:"db-1-086", t:1, lvl:"B2", q: "Un parent refuse que sa fille de 14 ans aille à la piscine avec sa classe pour des raisons religieuses. L'école peut-elle exiger sa participation ?", o: ["Non, c'est le droit du père", "Oui, tous les enseignements sont obligatoires et on ne peut les contester pour des raisons religieuses", "Non, si c'est écrit", "Cela dépend de la piscine"], c: 1, e: "Oui, l'école peut exiger la participation de l'élève. Tous les enseignements, y compris l'éducation physique et sportive (piscine), sont obligatoires. Il est interdit de contester les enseignements scolaires au nom de convictions religieuses. C'est un principe de la laïcité à l'école." },
    { id:"db-1-087", t:1, lvl:"B1", q: "Un restaurant peut-il refuser de servir un client en raison de son origine ou de sa couleur de peau ?", o: ["Oui, le restaurateur choisit", "Non, c'est une discrimination raciste grave et interdite", "Oui, s'il est complet", "Cela dépend de la ville"], c: 1, e: "Non, refuser de servir un client en raison de sa couleur de peau est une discrimination raciste grave, strictement interdite et sévèrement punie par la loi française. Tout établissement ouvert au public doit servir tous les clients sans distinction d'origine." },
    { id:"db-1-088", t:1, lvl:"B2", q: "Julie et Marie, un couple lesbien, souhaitent adopter un enfant. Peuvent-elles le faire légalement en France ?", o: ["Non, c'est réservé aux couples hétérosexuels", "Oui, les couples de même sexe ont les mêmes droits d'adoption", "Non, sauf accord spécial", "Seulement dans certaines régions"], c: 1, e: "Oui, depuis la loi de 2013, les couples de même sexe mariés ont exactement les mêmes droits d'adoption que les couples hétérosexuels. Refuser une adoption uniquement en raison de l'orientation sexuelle des adoptants serait une discrimination illégale." },
    { id:"db-1-089", t:1, lvl:"B1", q: "Un voisin tient régulièrement des propos dégradants envers Mohamed en raison de ses origines. Que dit la loi ?", o: ["C'est autorisé au nom de la liberté d'expression", "C'est une injure à caractère raciste, punie par la loi", "C'est interdit uniquement sur le lieu de travail", "La loi n'intervient pas dans les conflits entre voisins"], c: 1, e: "Les injures fondées sur l'origine, l'ethnie, la race ou la religion sont des infractions pénales en France, passibles d'amendes et de peines de prison. La liberté d'expression ne protège pas les propos racistes, quel que soit le contexte (voisinage, travail, espace public, internet)." },
    { id:"db-1-090", t:1, lvl:"B2", q: "Un propriétaire de discothèque refuse systématiquement l'entrée à des personnes en raison de leur origine ou couleur de peau. Que risque-t-il ?", o: ["Rien, c'est son établissement", "Des poursuites pénales pour discrimination raciale", "Une simple amende", "Juste une mauvaise réputation"], c: 1, e: "Il risque des poursuites pénales pour discrimination raciale. Refuser l'accès à un établissement ouvert au public en raison de l'origine est un délit pénal puni par la loi : jusqu'à 3 ans de prison et 45 000 euros d'amende. La victime peut également obtenir des dommages et intérêts." },
    { id:"db-1-091", t:1, lvl:"B1", q: "Sarah, médecin dans un hôpital public, refuse de soigner un patient parce qu'il est homosexuel. Peut-elle faire cela ?", o: ["Oui, c'est sa liberté de conscience", "Non, c'est une discrimination interdite, elle doit assurer les soins", "Oui, si un autre médecin peut le faire", "Cela dépend de la pathologie"], c: 1, e: "Non, Sarah ne peut absolument pas refuser de soigner un patient en raison de son orientation sexuelle. C'est une discrimination grave, contraire au code de déontologie médicale et à la loi. Tout médecin doit soigner tous les patients sans discrimination." },
    { id:"db-1-092", t:1, lvl:"B2", q: "David, journaliste, publie un article accusant le maire de corruption sans aucune preuve. Que risque-t-il ?", o: ["Rien, c'est la liberté de la presse", "Des poursuites pour diffamation", "Un prix de journalisme", "Juste des excuses"], c: 1, e: "David risque des poursuites pour diffamation. La liberté de la presse ne protège pas les accusations mensongères qui portent atteinte à l'honneur. S'il ne peut pas prouver ses accusations, il peut être condamné à payer des dommages et intérêts et à publier un démenti." },
    { id:"db-1-093", t:1, lvl:"B1", q: "Rachid veut créer une association culturelle berbère dans sa ville. Doit-il demander l'autorisation au maire ?", o: ["Oui, obligatoirement", "Non, il suffit de déclarer l'association en préfecture", "Oui, et au préfet aussi", "Non, les associations sont interdites"], c: 1, e: "Non, Rachid n'a pas besoin de demander d'autorisation. En France, la liberté d'association permet de créer une association simplement en la déclarant à la préfecture. Aucune autorisation préalable du maire ou d'une autre autorité n'est nécessaire." },
    { id:"db-1-094", t:1, lvl:"B2", q: "Une femme enceinte postule pour un emploi. L'employeur peut-il lui poser des questions sur sa grossesse pendant l'entretien ?", o: ["Oui, pour organiser le travail", "Non, c'est interdit, ces questions sont discriminatoires", "Oui, si le poste est physique", "Cela dépend de l'entreprise"], c: 1, e: "Non, poser des questions sur la grossesse lors d'un entretien d'embauche est strictement interdit en France. C'est une discrimination fondée sur le sexe. L'employeur ne peut pas refuser d'embaucher ou défavoriser une candidate en raison de sa grossesse." },
    { id:"db-1-095", t:1, lvl:"B1", q: "Un commerçant peut-il refuser de servir un client parce qu'il porte des vêtements traditionnels africains ?", o: ["Oui, c'est son commerce", "Non, c'est une discrimination raciste interdite", "Oui, s'il a un dress code", "Cela dépend du quartier"], c: 1, e: "Non, refuser de servir un client en raison de ses vêtements traditionnels est une discrimination fondée sur l'origine, strictement interdite et punissable. Tout commerçant doit servir tous les clients sans distinction d'origine ou de culture." },
    { id:"db-1-096", t:1, lvl:"B2", q: "Pierre organise une manifestation contre une loi du gouvernement. Il bloque une autoroute pendant 3 heures. Que risque-t-il ?", o: ["Rien, c'est son droit de manifester", "Des poursuites pour entrave à la circulation", "Des félicitations", "Juste un avertissement"], c: 1, e: "Pierre risque des poursuites pour entrave à la circulation et trouble à l'ordre public. Le droit de manifester existe mais doit s'exercer dans le respect de l'ordre public. Bloquer une autoroute met en danger autrui et peut être puni par la loi." },
    { id:"db-1-097", t:1, lvl:"B1", q: "Nadia veut ouvrir un compte bancaire mais la banque refuse à cause de son nom à consonance arabe. Est-ce légal ?", o: ["Oui, la banque choisit ses clients", "Non, c'est une discrimination raciste interdite", "Oui, si c'est écrit dans le règlement", "Cela dépend de la banque"], c: 1, e: "Non, refuser d'ouvrir un compte bancaire en raison du nom ou de l'origine présumée est une discrimination raciste strictement interdite. Nadia peut porter plainte et saisir le Défenseur des droits. La banque risque des sanctions pénales." },
    { id:"db-1-098", t:1, lvl:"B2", q: "Un syndicat organise une grève dans une entreprise de transport public. L'employeur peut-il licencier les grévistes ?", o: ["Oui, ils n'ont pas travaillé", "Non, le droit de grève est protégé, c'est interdit", "Oui, si la grève dure plus d'un jour", "Cela dépend du contrat"], c: 1, e: "Non, licencier des salariés parce qu'ils font grève est strictement interdit en France. Le droit de grève est un droit constitutionnel protégé. Tout licenciement pour fait de grève est nul et peut donner lieu à réintégration et dommages et intérêts." },
    { id:"db-1-099", t:1, lvl:"B1", q: "Lucas tient sur Facebook des propos appelant à la violence contre les musulmans. Que risque-t-il ?", o: ["Rien, c'est sur internet", "Des poursuites pour provocation à la haine raciale", "Juste une suspension de compte", "Rien si c'est son opinion"], c: 1, e: "Lucas risque des poursuites pénales pour provocation à la haine raciale et incitation à la violence. Les propos haineux sur internet sont punis de la même façon que dans la vie réelle : jusqu'à 1 an de prison et 45 000 euros d'amende." },

    // === QUESTIONS COMPLÉMENTAIRES - MARSEILLAISE ET SYMBOLES (Questions 101-105) ===
    { id:"db-1-100", t:1, lvl:"B1", q: "Comment se termine le premier couplet de la Marseillaise : 'Allons enfants de la patrie, le jour de gloire est arrivé...' ?", o: ["'...marchons, marchons !'", "'...vive la France !'", "'...liberté chérie !'", "'...aux armes citoyens !'"], c: 0, e: "Le premier couplet de la Marseillaise se termine par 'Marchons, marchons ! Qu'un sang impur abreuve nos sillons'. Composée en 1792 par Rouget de Lisle, la Marseillaise est devenue l'hymne national français et symbolise la résistance et la liberté." },
    { id:"db-1-101", t:1, lvl:"B1", q: "Quel est le refrain de la Marseillaise ?", o: ["'Aux armes, citoyens ! Formez vos bataillons !'", "'Vive la France, vive la liberté !'", "'Liberté, égalité, fraternité !'", "'Allons enfants de la patrie !'"], c: 0, e: "Le refrain de la Marseillaise est 'Aux armes, citoyens ! Formez vos bataillons ! Marchons, marchons ! Qu'un sang impur abreuve nos sillons.' Ce chant révolutionnaire exprime l'appel à défendre la Nation et la liberté." },
    { id:"db-1-102", t:1, lvl:"B1", q: "Où peut-on voir les symboles officiels de la République française (Marianne, devise, drapeau) ?", o: ["Uniquement à Paris", "Sur les bâtiments publics : mairies, écoles, préfectures, tribunaux", "Seulement dans les musées", "Uniquement sur les billets de banque"], c: 1, e: "Les symboles de la République (Marianne, drapeau tricolore, devise 'Liberté, Égalité, Fraternité') sont visibles sur tous les bâtiments publics : mairies, écoles, préfectures, tribunaux, ambassades. On les trouve aussi sur les documents officiels et les sites internet gouvernementaux." },
    { id:"db-1-103", t:1, lvl:"B2", q: "Est-il interdit de brûler ou de détruire le drapeau français en public ?", o: ["Non, c'est une forme de liberté d'expression", "Oui, c'est un délit puni par la loi", "Seulement si c'est filmé", "Cela dépend du contexte"], c: 1, e: "Oui, détruire ou brûler le drapeau français de manière publique et dans des conditions de nature à troubler l'ordre public est un délit depuis 2010. Cette infraction peut être punie d'une amende de 1 500 euros. Le drapeau tricolore est un symbole protégé de la Nation." },
    { id:"db-1-104", t:1, lvl:"B1", q: "Où est inscrite la devise 'Liberté, Égalité, Fraternité' ?", o: ["Seulement dans la Constitution", "Sur les bâtiments publics, les pièces de monnaie et les documents officiels", "Uniquement sur les passeports", "Nulle part officiellement"], c: 1, e: "La devise 'Liberté, Égalité, Fraternité' est inscrite dans la Constitution (article 2) et figure sur les frontons des bâtiments publics (mairies, écoles, tribunaux), sur les pièces de monnaie en euros, et sur de nombreux documents officiels de la République." },

    // === QUESTIONS COMPLÉMENTAIRES - LAÏCITÉ ET NEUTRALITÉ (Questions 106-115) ===
    { id:"db-1-105", t:1, lvl:"B1", q: "À l'école publique, qui a le droit de porter des signes religieux visibles ?", o: ["Les élèves uniquement", "Les enseignants uniquement", "Personne dans l'enceinte de l'école", "Tout le monde librement"], c: 2, e: "À l'école publique, personne ne peut porter de signes religieux ostensibles : ni les élèves (loi de 2004), ni les enseignants et personnels (obligation de neutralité des agents publics). Cela garantit la neutralité de l'espace scolaire et la liberté de conscience de chacun." },
    { id:"db-1-106", t:1, lvl:"B2", q: "Que signifie la neutralité de l'État en matière religieuse ?", o: ["L'État interdit toutes les religions", "L'État ne privilégie, ne finance ni ne combat aucune religion", "L'État impose l'athéisme", "L'État favorise la religion majoritaire"], c: 1, e: "La neutralité de l'État signifie que l'État ne privilégie, ne subventionne ni ne combat aucune religion. Il garantit la liberté de conscience de tous et traite également les croyants de toutes les religions et les non-croyants. L'État reste impartial face aux convictions religieuses." },
    { id:"db-1-107", t:1, lvl:"B1", q: "Un usager d'un service public (mairie, préfecture) peut-il porter un signe religieux ?", o: ["Non, jamais", "Oui, les usagers ne sont pas soumis à la neutralité", "Seulement les signes discrets", "Cela dépend du service"], c: 1, e: "Oui, les usagers des services publics peuvent porter des signes religieux. La neutralité religieuse s'impose aux agents publics (fonctionnaires), pas aux usagers. Cependant, l'usager doit respecter l'ordre public et ne peut pas exiger un traitement particulier pour des raisons religieuses." },
    { id:"db-1-108", t:1, lvl:"B2", q: "Un fonctionnaire travaillant dans une préfecture peut-il afficher sa religion pendant son service ?", o: ["Oui, c'est sa liberté personnelle", "Non, il est soumis au principe de stricte neutralité", "Oui, s'il est discret", "Cela dépend de son chef"], c: 1, e: "Non, tout agent public (fonctionnaire, employé de l'État) est soumis au principe de stricte neutralité pendant son service. Il ne peut pas porter de signes religieux visibles ni exprimer ses convictions religieuses. Cela garantit l'égalité de traitement de tous les usagers." },
    { id:"db-1-109", t:1, lvl:"B1", q: "La laïcité impose-t-elle aux agents publics d'être neutres envers tous les usagers ?", o: ["Non, ils peuvent avoir des préférences", "Oui, ils doivent traiter tous les usagers de façon égale", "Seulement dans certains services", "Cela dépend de la religion de l'usager"], c: 1, e: "Oui, la laïcité impose aux agents publics d'être parfaitement neutres et de traiter tous les usagers de façon strictement égale, quelles que soient leurs convictions religieuses ou leur absence de religion. C'est une garantie d'égalité devant le service public." },
    { id:"db-1-110", t:1, lvl:"B2", q: "Que prévoit la Charte de la laïcité à l'école concernant les enseignements ?", o: ["Les élèves choisissent leurs cours", "Il est interdit de contester un enseignement au nom de ses convictions religieuses", "Les cours de religion sont obligatoires", "Les parents décident du programme"], c: 1, e: "La Charte de la laïcité à l'école précise qu'aucun élève ne peut invoquer une conviction religieuse ou politique pour contester le droit d'un enseignant à traiter une question au programme. Tous les enseignements sont obligatoires et ne peuvent être refusés pour des raisons religieuses." },
    { id:"db-1-111", t:1, lvl:"B1", q: "A-t-on le droit de changer de religion en France ?", o: ["Non, on garde celle de sa naissance", "Oui, la liberté de changer de religion est garantie", "Seulement avec l'accord de sa famille", "Seulement après 18 ans"], c: 1, e: "Oui, la liberté de changer de religion (droit à la conversion) est totalement garantie en France. La liberté de conscience permet à chacun de croire, de ne pas croire, de changer de religion ou d'abandonner toute religion à tout moment de sa vie." },
    { id:"db-1-112", t:1, lvl:"B1", q: "Que dit l'article 1er de la Constitution sur la République française ?", o: ["La France est une monarchie constitutionnelle", "La France est une République indivisible, laïque, démocratique et sociale", "La France est un État religieux", "La France est une fédération de régions"], c: 1, e: "L'article 1er de la Constitution affirme : 'La France est une République indivisible, laïque, démocratique et sociale.' Ces quatre principes fondamentaux définissent la nature de l'État français : unité du territoire, neutralité religieuse, souveraineté du peuple et protection sociale." },
    { id:"db-1-113", t:1, lvl:"B2", q: "La répudiation (le fait pour un homme de renvoyer unilatéralement son épouse) est-elle reconnue en France ?", o: ["Oui, si c'est une pratique religieuse", "Non, elle est contraire au principe d'égalité entre les époux", "Oui, avec l'accord du juge", "Cela dépend du pays d'origine"], c: 1, e: "Non, la répudiation n'est pas reconnue en France car elle est contraire au principe d'égalité entre les femmes et les hommes. En France, seul le divorce prononcé par un juge, avec des droits égaux pour les deux époux, permet de mettre fin à un mariage." },
    { id:"db-1-114", t:1, lvl:"B1", q: "Que représente la laïcité pour les citoyens ?", o: ["L'interdiction de pratiquer une religion", "La garantie de la liberté de conscience et de l'égalité de tous", "L'obligation d'être athée", "La supériorité d'une religion sur les autres"], c: 1, e: "La laïcité représente la garantie de la liberté de conscience pour tous : liberté de croire ou de ne pas croire, de pratiquer sa religion ou non, de changer de conviction. Elle assure aussi l'égalité de tous les citoyens, quelle que soit leur religion ou leur absence de religion." },

    // === QUESTIONS COMPLÉMENTAIRES - IMPÔTS ET PARTICIPATION CITOYENNE (Questions 116-120) ===
    { id:"db-1-115", t:1, lvl:"B1", q: "À quoi servent les impôts payés par les citoyens ?", o: ["À enrichir les politiciens", "À financer les services publics : écoles, hôpitaux, routes, police", "À rembourser les dettes personnelles", "À rien de concret"], c: 1, e: "Les impôts financent les services publics dont bénéficient tous les citoyens : écoles gratuites, hôpitaux publics, routes, transports, police, pompiers, justice, aides sociales. C'est un acte de solidarité nationale où chacun contribue selon ses moyens pour le bien commun." },
    { id:"db-1-116", t:1, lvl:"B2", q: "Comment un citoyen peut-il participer à la vie démocratique en dehors des élections ?", o: ["Il ne peut rien faire entre les élections", "En adhérant à une association, un syndicat, un parti, ou en participant à des consultations", "Uniquement en manifestant", "En écrivant au Président"], c: 1, e: "Un citoyen peut participer à la vie démocratique de nombreuses façons : adhérer à une association ou un parti politique, rejoindre un syndicat, participer à des consultations publiques, signer des pétitions, s'engager dans la vie locale (conseils de quartier), ou simplement s'informer et débattre." },
    { id:"db-1-117", t:1, lvl:"B1", q: "Qu'est-ce qu'une association en France ?", o: ["Une entreprise commerciale", "Un regroupement de personnes pour un projet commun, sans but lucratif", "Une administration publique", "Un syndicat obligatoire"], c: 1, e: "Une association est un regroupement de personnes qui s'unissent pour mener un projet commun (sportif, culturel, humanitaire, éducatif) sans chercher à faire du profit. La liberté d'association est garantie par la loi de 1901. Créer une association est simple et ne nécessite aucune autorisation." },
    { id:"db-1-118", t:1, lvl:"B2", q: "Quel est l'un des rôles des associations dans la société française ?", o: ["Remplacer l'État dans tous les domaines", "Créer du lien social, défendre des causes et compléter l'action publique", "Faire de la politique partisane", "Collecter des impôts"], c: 1, e: "Les associations jouent un rôle essentiel dans la société : elles créent du lien social, défendent des causes (environnement, droits humains), aident les personnes en difficulté, proposent des activités culturelles et sportives, et complètent l'action des services publics. Elles sont un pilier de la démocratie participative." },
    { id:"db-1-119", t:1, lvl:"B1", q: "Qu'est-ce que la liberté de circulation en France ?", o: ["Le droit de ne pas payer les transports", "Le droit de se déplacer librement sur tout le territoire national", "Le droit de conduire sans permis", "Le droit de voyager gratuitement à l'étranger"], c: 1, e: "La liberté de circulation permet à toute personne de se déplacer librement sur l'ensemble du territoire français, de choisir son lieu de résidence et de quitter le pays. C'est une liberté fondamentale qui ne peut être restreinte que dans des cas exceptionnels (état d'urgence, crise sanitaire)." },

    // === QUESTIONS COMPLÉMENTAIRES - COUVERTURE OFFICIELLE (Thème 1) ===
    { id:"db-1-120", t:1, lvl:"B1", q: "La Marseillaise est le nom donné à quel symbole de la République française ?", o: ["La devise nationale", "L'hymne national", "Le drapeau tricolore", "La figure de Marianne"], c: 1, e: "La Marseillaise est l'hymne national de la France. Composée par Rouget de Lisle en 1792, elle est devenue un symbole officiel de la République, inscrit à l'article 2 de la Constitution. Elle est jouée lors des cérémonies officielles et des événements sportifs internationaux." },
    { id:"db-1-121", t:1, lvl:"B1", q: "Sur quels documents ou objets du quotidien peut-on voir Marianne, figure symbolique de la République ?", o: ["Uniquement dans les musées", "Sur les timbres-poste, les pièces de monnaie et les documents officiels", "Seulement sur le drapeau français", "Sur les billets de banque étrangers"], c: 1, e: "Marianne, symbole de la République française, figure sur les timbres-poste, les pièces de monnaie en euros frappées en France et de nombreux documents officiels. Son buste est également présent dans toutes les mairies de France." },
    { id:"db-1-122", t:1, lvl:"B2", q: "Les symboles de la République (Marianne, drapeau, devise) sont visibles sur les sites internet officiels de l'État. Comment reconnaît-on un site gouvernemental ?", o: ["Il se termine par .com", "Il porte la mention 'République française' et le drapeau tricolore", "Il est uniquement en anglais", "Il n'a aucun signe distinctif"], c: 1, e: "Les sites internet officiels de l'État français portent les symboles de la République : le drapeau tricolore, la devise 'Liberté, Égalité, Fraternité' et la mention 'République française'. Les sites gouvernementaux utilisent le domaine .gouv.fr, ce qui permet de les identifier facilement." },
    { id:"db-1-123", t:1, lvl:"B1", q: "En France, qu'est-ce que la participation citoyenne ?", o: ["Uniquement le fait de voter aux élections", "L'engagement des citoyens dans la vie collective : voter, adhérer à une association, s'informer, participer à la vie locale", "L'obligation de rejoindre un parti politique", "Le service militaire obligatoire"], c: 1, e: "La participation citoyenne désigne toutes les façons dont un citoyen s'implique dans la vie collective : voter, adhérer à une association ou un syndicat, participer à des consultations publiques, s'engager dans la vie locale ou simplement s'informer et débattre. C'est un pilier de la démocratie." },
    { id:"db-1-124", t:1, lvl:"B2", q: "Que fait l'État français pour lutter contre les discriminations ?", o: ["Rien, c'est un problème individuel", "Il adopte des lois, punit les auteurs et a créé le Défenseur des droits", "Il interdit uniquement le racisme", "Il laisse les associations s'en charger seules"], c: 1, e: "L'État lutte activement contre les discriminations par plusieurs moyens : des lois qui interdisent et punissent toute discrimination (à l'embauche, au logement, dans les services), le Défenseur des droits qui peut être saisi gratuitement par toute victime, et des campagnes de sensibilisation. La lutte contre les discriminations est une priorité nationale." },
    { id:"db-1-125", t:1, lvl:"B2", q: "La Marseillaise commence par les mots 'Allons enfants de la patrie'. Comment se poursuit cette première phrase ?", o: ["'...marchons, marchons !'", "'...le jour de gloire est arrivé !'", "'...aux armes, citoyens !'", "'...formez vos bataillons !'"], c: 1, e: "La première phrase de la Marseillaise est : 'Allons enfants de la patrie, le jour de gloire est arrivé !' Le refrain, quant à lui, est : 'Aux armes, citoyens ! Formez vos bataillons ! Marchons, marchons !' Connaître ces paroles fait partie de la culture civique française." },

    // === CONSTITUTION ET Ve RÉPUBLIQUE (Questions 1-10) ===
    { id:"db-2-001", t:2, lvl:"B1", q: "Quelle est la Constitution actuelle de la France ?", o: ["La IVe République", "La Ve République", "La VIe République", "La Constitution de 1789"], c: 1, e: "La Constitution actuelle de la France est celle de la Ve République, adoptée en 1958. Elle a été instaurée par le général de Gaulle et définit l'organisation des pouvoirs publics français." },
    { id:"db-2-002", t:2, lvl:"B1", q: "En quelle année la Constitution de la Ve République a-t-elle été adoptée ?", o: ["1945", "1958", "1968", "1981"], c: 1, e: "La Constitution de la Ve République a été adoptée en 1958, après le retour au pouvoir du général de Gaulle. Elle remplace la Constitution de la IVe République et renforce considérablement les pouvoirs du Président." },
    { id:"db-2-003", t:2, lvl:"B1", q: "Qui a fondé la Ve République ?", o: ["François Mitterrand", "Charles de Gaulle", "Georges Pompidou", "Napoléon Bonaparte"], c: 1, e: "Le général Charles de Gaulle a fondé la Ve République en 1958. Héros de la Résistance pendant la Seconde Guerre mondiale, il a créé ce nouveau régime politique pour stabiliser la France après la crise de la décolonisation." },
    { id:"db-2-004", t:2, lvl:"B2", q: "Quel est le principe fondamental qui empêche la concentration du pouvoir en France ?", o: ["La solidarité", "La séparation des pouvoirs", "La laïcité", "La fraternité"], c: 1, e: "Le principe de séparation des pouvoirs empêche qu'une seule personne ou institution concentre tous les pouvoirs. Les pouvoirs législatif (Parlement), exécutif (Gouvernement) et l'autorité judiciaire (Justice) sont distincts et s'équilibrent mutuellement." },
    { id:"db-2-005", t:2, lvl:"B1", q: "Qu'est-ce que le pouvoir législatif ?", o: ["Le pouvoir de juger", "Le pouvoir de faire les lois", "Le pouvoir de gouverner", "Le pouvoir de la police"], c: 1, e: "Le pouvoir législatif est le pouvoir de voter et de faire les lois. En France, il est exercé par le Parlement, composé de l'Assemblée nationale et du Sénat. Les députés et sénateurs débattent et votent les lois." },
    { id:"db-2-006", t:2, lvl:"B1", q: "Qu'est-ce que le pouvoir exécutif ?", o: ["Le pouvoir de voter les lois", "Le pouvoir d'appliquer les lois et de gouverner", "Le pouvoir de juger", "Le pouvoir de manifester"], c: 1, e: "Le pouvoir exécutif est le pouvoir d'appliquer les lois et de diriger le pays au quotidien. En France, il est exercé par le Président de la République et le Gouvernement dirigé par le Premier ministre." },
    { id:"db-2-007", t:2, lvl:"B1", q: "Qu'est-ce que l'autorité judiciaire ?", o: ["Le pouvoir de voter les lois", "Le pouvoir de gouverner", "Le pouvoir de rendre la justice", "Le pouvoir de la police"], c: 2, e: "L'autorité judiciaire est le pouvoir de rendre la justice, c'est-à-dire de trancher les litiges et de sanctionner les infractions. Elle est exercée par les juges, qui sont indépendants du pouvoir politique." },
    { id:"db-2-008", t:2, lvl:"B2", q: "Pourquoi l'indépendance de la justice est-elle essentielle en démocratie ?", o: ["Pour gagner plus d'argent", "Pour garantir que tous soient égaux devant la loi, sans pression politique", "Pour créer plus d'emplois", "Pour éviter les procès"], c: 1, e: "L'indépendance de la justice garantit que tous les citoyens, y compris les responsables politiques, sont égaux devant la loi. Les juges doivent pouvoir décider librement, sans pression du gouvernement ou d'autres pouvoirs." },
    { id:"db-2-009", t:2, lvl:"B1", q: "Qu'est-ce qu'un État de droit ?", o: ["Un État sans lois", "Un État où la loi s'applique à tous, y compris aux gouvernants", "Un État militaire", "Un État religieux"], c: 1, e: "Un État de droit est un système politique où la loi s'applique à tous, y compris aux autorités publiques. Personne n'est au-dessus des lois. Cela garantit que les droits fondamentaux de chacun sont protégés." },
    { id:"db-2-010", t:2, lvl:"B2", q: "Que signifie le principe selon lequel 'le gouvernement est responsable devant le Parlement' ?", o: ["Le Parlement paie le gouvernement", "Le Parlement peut renverser le gouvernement par une motion de censure", "Le gouvernement commande le Parlement", "Le Parlement doit obéir au gouvernement"], c: 1, e: "Cela signifie que le Parlement, notamment l'Assemblée nationale, peut contrôler et sanctionner le Gouvernement. Si les députés votent une motion de censure, le Gouvernement doit démissionner. C'est un mécanisme d'équilibre des pouvoirs." },

    // === LE PRÉSIDENT DE LA RÉPUBLIQUE (Questions 11-20) ===
    { id:"db-2-011", t:2, lvl:"B1", q: "Pour combien d'années le Président de la République est-il élu ?", o: ["3 ans", "5 ans", "7 ans", "10 ans"], c: 1, e: "Le Président de la République est élu pour un mandat de 5 ans, appelé 'quinquennat'. Cette durée a été instaurée en 2000 pour harmoniser le mandat présidentiel avec celui des députés." },
    { id:"db-2-012", t:2, lvl:"B1", q: "Comment est élu le Président de la République ?", o: ["Par le Parlement", "Au suffrage universel direct par tous les citoyens", "Par les maires", "Par tirage au sort"], c: 1, e: "Le Président est élu au suffrage universel direct, c'est-à-dire directement par tous les citoyens français majeurs. Cette élection se fait en deux tours : si aucun candidat n'obtient la majorité absolue au premier tour, les deux candidats arrivés en tête s'affrontent au second." },
    { id:"db-2-013", t:2, lvl:"B1", q: "Où réside et travaille le Président de la République ?", o: ["À l'Hôtel Matignon", "Au Palais de l'Élysée", "Au Palais Bourbon", "À Versailles"], c: 1, e: "Le Président de la République réside et travaille au Palais de l'Élysée, situé à Paris. C'est le siège de la présidence depuis 1848." },
    { id:"db-2-014", t:2, lvl:"B1", q: "Qui nomme le Premier ministre ?", o: ["L'Assemblée nationale", "Le Président de la République", "Le Sénat", "Les citoyens par vote"], c: 1, e: "C'est le Président de la République qui nomme le Premier ministre. En général, il choisit une personnalité de la majorité parlementaire pour garantir que le Gouvernement puisse gouverner efficacement." },
    { id:"db-2-015", t:2, lvl:"B1", q: "Quel est le rôle du Président de la République ?", o: ["Voter les lois", "Diriger la politique étrangère et être chef des armées", "Rendre la justice", "Gérer les mairies"], c: 1, e: "Le Président de la République est le chef de l'État. Il dirige la politique étrangère, est le chef des armées, nomme le Premier ministre et peut dissoudre l'Assemblée nationale. Il veille au respect de la Constitution et assure la continuité de l'État." },
    { id:"db-2-016", t:2, lvl:"B2", q: "Que peut faire le Président si l'Assemblée nationale s'oppose systématiquement à son gouvernement ?", o: ["Rien, il doit accepter", "Dissoudre l'Assemblée nationale et organiser de nouvelles élections législatives", "Emprisonner les députés", "Démissionner obligatoirement"], c: 1, e: "Le Président peut dissoudre l'Assemblée nationale, c'est-à-dire provoquer de nouvelles élections législatives anticipées. C'est un pouvoir fort qui permet de sortir d'un blocage politique en redonnant la parole aux électeurs." },
    { id:"db-2-017", t:2, lvl:"B1", q: "Le Président de la République peut-il être réélu ?", o: ["Non, jamais", "Oui, sans limite", "Oui, une seule fois consécutivement", "Oui, mais après 10 ans de pause"], c: 2, e: "Oui, le Président peut être réélu une fois consécutivement, soit deux mandats de 5 ans maximum d'affilée (10 ans au total). Après cela, il ne peut pas se représenter immédiatement." },
    { id:"db-2-018", t:2, lvl:"B2", q: "Le Président de la République est-il responsable devant le Parlement ?", o: ["Oui, il peut être renversé par motion de censure", "Non, il n'est responsable que devant les électeurs", "Oui, devant le Sénat uniquement", "Oui, devant les juges"], c: 1, e: "Non, le Président n'est pas responsable politiquement devant le Parlement (contrairement au Gouvernement). Il est élu directement par le peuple et ne peut être contraint à la démission par les députés. Seule une procédure de destitution exceptionnelle existe." },
    { id:"db-2-019", t:2, lvl:"B1", q: "Qui est le chef des armées françaises ?", o: ["Le Ministre de la Défense", "Le Président de la République", "Le général en chef", "Le Premier ministre"], c: 1, e: "Le Président de la République est le chef des armées françaises. Il prend les décisions stratégiques en matière de défense nationale et peut engager les forces armées. C'est une prérogative importante de sa fonction." },
    { id:"db-2-020", t:2, lvl:"B1", q: "Le Président peut-il proposer un référendum aux citoyens ?", o: ["Non, jamais", "Oui, sur certains sujets après consultation", "Oui, sur tous les sujets librement", "Seulement en temps de guerre"], c: 1, e: "Oui, le Président peut organiser un référendum, c'est-à-dire soumettre directement une question aux citoyens qui votent par oui ou non. Cela permet de consulter le peuple sur des réformes importantes (Constitution, traités, organisation des pouvoirs)." },

    // === LE GOUVERNEMENT (Questions 21-28) ===
    { id:"db-2-021", t:2, lvl:"B1", q: "Qui dirige le Gouvernement au quotidien ?", o: ["Le Président de la République", "Le Premier ministre", "Le Ministre de l'Intérieur", "Le Président de l'Assemblée nationale"], c: 1, e: "C'est le Premier ministre qui dirige le Gouvernement au quotidien. Il coordonne l'action des ministres, applique la politique décidée et est responsable devant l'Assemblée nationale." },
    { id:"db-2-022", t:2, lvl:"B1", q: "Où se trouve le bureau du Premier ministre ?", o: ["Au Palais de l'Élysée", "À l'Hôtel Matignon", "Au Palais Bourbon", "Au Palais du Luxembourg"], c: 1, e: "Le Premier ministre travaille à l'Hôtel Matignon, situé à Paris. C'est le siège traditionnel des services du Premier ministre depuis 1935." },
    { id:"db-2-023", t:2, lvl:"B1", q: "Qui compose le Gouvernement avec le Premier ministre ?", o: ["Les députés", "Les ministres", "Les sénateurs", "Les préfets"], c: 1, e: "Le Gouvernement est composé du Premier ministre et des ministres qu'il dirige. Chaque ministre est responsable d'un domaine précis : Éducation, Santé, Intérieur, Justice, Économie, etc." },
    { id:"db-2-024", t:2, lvl:"B2", q: "Que se passe-t-il si l'Assemblée nationale vote une motion de censure contre le Gouvernement ?", o: ["Rien, c'est symbolique", "Le Gouvernement doit démissionner", "Le Premier ministre va en prison", "L'Assemblée est dissoute"], c: 1, e: "Si l'Assemblée nationale vote une motion de censure (à la majorité absolue), le Gouvernement doit démissionner. C'est le principal moyen pour les députés de sanctionner un Gouvernement dont ils désapprouvent la politique." },
    { id:"db-2-025", t:2, lvl:"B1", q: "Quel est le rôle principal du Gouvernement ?", o: ["Voter les lois", "Déterminer et conduire la politique de la Nation", "Rendre la justice", "Élire le Président"], c: 1, e: "Le rôle principal du Gouvernement est de déterminer et de conduire la politique de la Nation. Il propose des projets de loi, applique les lois votées, gère l'administration et les services publics au quotidien." },
    { id:"db-2-026", t:2, lvl:"B1", q: "Le Premier ministre peut-il rester en fonction si le Président change ?", o: ["Oui, automatiquement", "Non, il démissionne généralement et un nouveau Premier ministre est nommé", "Oui, obligatoirement pendant 5 ans", "Cela dépend du Parlement"], c: 1, e: "Non, traditionnellement le Premier ministre présente sa démission lorsqu'un nouveau Président est élu. Le nouveau Président nomme alors un nouveau Premier ministre de son choix, souvent en fonction de la majorité parlementaire." },
    { id:"db-2-027", t:2, lvl:"B2", q: "Qui peut proposer des projets de loi au Parlement ?", o: ["Seulement les députés", "Le Gouvernement et les parlementaires", "Seulement le Président", "Seulement les citoyens"], c: 1, e: "Les projets de loi peuvent être proposés par le Gouvernement (on parle alors de 'projets de loi') ou par les parlementaires eux-mêmes (on parle de 'propositions de loi'). En pratique, la majorité des lois votées proviennent du Gouvernement." },
    { id:"db-2-028", t:2, lvl:"B1", q: "Les ministres peuvent-ils être poursuivis en justice pour leurs actes ?", o: ["Non, ils sont intouchables", "Oui, devant une juridiction spéciale pour les actes commis dans leurs fonctions", "Non, jamais", "Seulement après leur départ"], c: 1, e: "Oui, les ministres peuvent être poursuivis devant la Cour de justice de la République pour les crimes et délits commis dans l'exercice de leurs fonctions. Pour les actes personnels, ils sont jugés comme tout citoyen par les tribunaux ordinaires." },

    // === LE PARLEMENT (Questions 29-42) ===
    { id:"db-2-029", t:2, lvl:"B1", q: "De quoi est composé le Parlement français ?", o: ["L'Assemblée nationale uniquement", "L'Assemblée nationale et le Sénat", "Le Sénat uniquement", "L'Élysée et Matignon"], c: 1, e: "Le Parlement français est composé de deux chambres : l'Assemblée nationale (chambre basse) et le Sénat (chambre haute). Les deux participent au vote des lois, mais l'Assemblée nationale a le dernier mot en cas de désaccord." },
    { id:"db-2-030", t:2, lvl:"B1", q: "Quel est le rôle principal du Parlement ?", o: ["Gouverner le pays", "Voter les lois et contrôler le Gouvernement", "Rendre la justice", "Nommer le Président"], c: 1, e: "Le rôle principal du Parlement est de voter les lois et de contrôler l'action du Gouvernement. Les parlementaires débattent, amendent et adoptent les textes législatifs. Ils peuvent aussi interroger les ministres et voter la censure du Gouvernement." },
    { id:"db-2-031", t:2, lvl:"B1", q: "Où siègent les députés de l'Assemblée nationale ?", o: ["Au Palais de l'Élysée", "Au Palais Bourbon", "Au Palais du Luxembourg", "À Matignon"], c: 1, e: "Les députés siègent au Palais Bourbon, situé à Paris près de la Seine. C'est le siège de l'Assemblée nationale depuis 1798." },
    { id:"db-2-032", t:2, lvl:"B1", q: "Pour combien de temps les députés sont-ils élus ?", o: ["3 ans", "5 ans", "7 ans", "10 ans"], c: 1, e: "Les députés de l'Assemblée nationale sont élus pour un mandat de 5 ans lors des élections législatives. Ce mandat peut être écourté si le Président dissout l'Assemblée." },
    { id:"db-2-033", t:2, lvl:"B1", q: "Comment les députés sont-ils élus ?", o: ["Par les sénateurs", "Au suffrage universel direct par les citoyens", "Par le Président", "Par tirage au sort"], c: 1, e: "Les députés sont élus au suffrage universel direct lors des élections législatives. Chaque député représente une circonscription. L'élection se fait en deux tours : pour être élu au premier tour, il faut obtenir la majorité absolue." },
    { id:"db-2-034", t:2, lvl:"B1", q: "Où siègent les sénateurs ?", o: ["Au Palais Bourbon", "Au Palais du Luxembourg", "À l'Élysée", "À Matignon"], c: 1, e: "Les sénateurs siègent au Palais du Luxembourg, situé à Paris dans le 6e arrondissement. C'est le siège du Sénat depuis 1799." },
    { id:"db-2-035", t:2, lvl:"B1", q: "Pour combien de temps les sénateurs sont-ils élus ?", o: ["3 ans", "5 ans", "6 ans", "9 ans"], c: 2, e: "Les sénateurs sont élus pour un mandat de 6 ans. Le Sénat est renouvelé par moitié tous les 3 ans, ce qui assure une continuité et une stabilité institutionnelle." },
    { id:"db-2-036", t:2, lvl:"B2", q: "Comment les sénateurs sont-ils élus ?", o: ["Au suffrage universel direct", "Au suffrage universel indirect par des grands électeurs (élus locaux)", "Par le Président", "Par l'Assemblée nationale"], c: 1, e: "Les sénateurs sont élus au suffrage universel indirect par des 'grands électeurs', principalement des élus locaux (maires, conseillers municipaux, départementaux, régionaux). Ce système donne une représentation des territoires et des collectivités locales." },
    { id:"db-2-037", t:2, lvl:"B1", q: "Combien y a-t-il de députés à l'Assemblée nationale ?", o: ["100", "350", "577", "1000"], c: 2, e: "L'Assemblée nationale compte 577 députés. Chacun représente une circonscription électorale. Leur nombre a été fixé en tenant compte de la population et de la représentation territoriale." },
    { id:"db-2-038", t:2, lvl:"B2", q: "En cas de désaccord entre l'Assemblée nationale et le Sénat sur un projet de loi, qui a le dernier mot ?", o: ["Le Sénat", "L'Assemblée nationale", "Le Président", "Le Conseil constitutionnel"], c: 1, e: "En cas de désaccord persistant entre les deux chambres, c'est l'Assemblée nationale qui a le dernier mot. Le Gouvernement peut demander à l'Assemblée de statuer définitivement sur le texte, après des tentatives de conciliation." },
    { id:"db-2-039", t:2, lvl:"B1", q: "Les parlementaires peuvent-ils interroger les ministres sur leur action ?", o: ["Non, jamais", "Oui, lors des séances de questions au Gouvernement", "Seulement par écrit", "Seulement une fois par an"], c: 1, e: "Oui, les parlementaires peuvent interroger les ministres, notamment lors des séances hebdomadaires de questions au Gouvernement. C'est un moyen important de contrôle et de débat démocratique. Ces séances sont publiques et souvent diffusées." },
    { id:"db-2-040", t:2, lvl:"B1", q: "Un député peut-il cumuler son mandat avec celui de maire ?", o: ["Oui, sans limite", "Non, depuis 2017 le cumul des mandats est limité", "Oui, s'il le souhaite", "Seulement dans les petites villes"], c: 1, e: "Non, depuis la loi de 2014 appliquée en 2017, les parlementaires (députés et sénateurs) ne peuvent plus cumuler leur mandat avec celui de maire, président de région ou de département. Cette mesure vise à améliorer l'efficacité et la disponibilité des élus." },
    { id:"db-2-041", t:2, lvl:"B2", q: "Qu'est-ce qu'une commission parlementaire ?", o: ["Un tribunal", "Un groupe de travail de parlementaires spécialisé sur un domaine", "Un parti politique", "Un syndicat"], c: 1, e: "Une commission parlementaire est un groupe de députés ou de sénateurs spécialisé dans un domaine (finances, affaires sociales, défense, etc.). Les commissions examinent les projets de loi en détail avant leur vote en séance plénière et peuvent mener des enquêtes." },
    { id:"db-2-042", t:2, lvl:"B1", q: "Que signifie voter une loi 'en dernière lecture' ?", o: ["La première fois", "Le vote final et définitif après les débats", "Un vote secret", "Un vote invalide"], c: 1, e: "Voter une loi 'en dernière lecture' signifie que c'est le vote final et définitif, après tous les débats et navettes entre l'Assemblée et le Sénat. Une fois votée en dernière lecture, la loi est promulguée par le Président et entre en vigueur." },

    // === JUSTICE ET INSTITUTIONS (Questions 43-52) ===
    { id:"db-2-043", t:2, lvl:"B1", q: "Qui rend la justice en France ?", o: ["Le Président", "Les juges", "Le Gouvernement", "Les députés"], c: 1, e: "La justice est rendue par les juges, qui sont indépendants du pouvoir politique. Ils appliquent la loi et tranchent les litiges entre particuliers (justice civile) ou sanctionnent les infractions pénales (justice pénale)." },
    { id:"db-2-044", t:2, lvl:"B1", q: "Au nom de qui la justice est-elle rendue en France ?", o: ["Au nom du Président", "Au nom du peuple français", "Au nom du Gouvernement", "Au nom des juges"], c: 1, e: "La justice est rendue 'Au nom du peuple français'. Cette formule figure sur tous les jugements et rappelle que les juges exercent leur pouvoir au nom de la Nation entière, et non en leur nom propre." },
    { id:"db-2-045", t:2, lvl:"B2", q: "Qu'est-ce que le Conseil constitutionnel ?", o: ["Un tribunal ordinaire", "Une institution qui vérifie la conformité des lois à la Constitution", "Le conseil des ministres", "Un parti politique"], c: 1, e: "Le Conseil constitutionnel est une institution qui vérifie que les lois votées respectent la Constitution. Il peut être saisi avant la promulgation d'une loi ou par un citoyen (QPC) si une loi appliquée porte atteinte à ses droits constitutionnels." },
    { id:"db-2-046", t:2, lvl:"B1", q: "Qu'est-ce que le Défenseur des droits ?", o: ["Un avocat gratuit", "Une autorité indépendante qui protège les droits des citoyens face à l'administration", "Un juge", "Un ministre"], c: 1, e: "Le Défenseur des droits est une autorité indépendante qui protège les droits et libertés des citoyens. Il peut être saisi gratuitement par toute personne qui estime que ses droits n'ont pas été respectés par une administration ou un service public." },
    { id:"db-2-047", t:2, lvl:"B1", q: "Les juges sont-ils indépendants du pouvoir politique ?", o: ["Non, ils obéissent au Gouvernement", "Oui, leur indépendance est garantie", "Non, le Président les nomme et les révoque", "Seulement certains juges"], c: 1, e: "Oui, l'indépendance des juges est un principe constitutionnel fondamental. Les juges ne reçoivent aucune instruction du Gouvernement ou du Parlement. Cela garantit qu'ils rendent leurs décisions uniquement selon la loi." },
    { id:"db-2-048", t:2, lvl:"B2", q: "Qu'est-ce que la présomption d'innocence ?", o: ["Un juge est toujours innocent", "Toute personne est présumée innocente tant qu'elle n'a pas été jugée coupable", "Les criminels sont toujours innocents", "Il faut prouver son innocence"], c: 1, e: "La présomption d'innocence signifie que toute personne accusée est considérée comme innocente jusqu'à ce qu'un tribunal la déclare coupable. C'est la justice qui doit prouver la culpabilité, et non l'accusé qui doit prouver son innocence." },
    { id:"db-2-049", t:2, lvl:"B1", q: "Peut-on faire appel d'une décision de justice ?", o: ["Non, jamais", "Oui, devant une juridiction supérieure", "Seulement si on est riche", "Seulement une fois dans sa vie"], c: 1, e: "Oui, dans la plupart des cas, on peut faire appel d'un jugement devant une juridiction supérieure (cour d'appel). Cela permet de faire réexaminer l'affaire par d'autres juges. C'est un droit fondamental qui garantit une justice équitable." },
    { id:"db-2-050", t:2, lvl:"B1", q: "Qu'est-ce qu'une infraction pénale ?", o: ["Une erreur administrative", "Un comportement interdit et puni par la loi pénale", "Une amende routière", "Un désaccord entre voisins"], c: 1, e: "Une infraction pénale est un comportement interdit par la loi pénale et puni par des sanctions (amende, prison, travail d'intérêt général). Il existe trois catégories : les contraventions (les moins graves), les délits, et les crimes (les plus graves)." },
    { id:"db-2-051", t:2, lvl:"B2", q: "Qu'est-ce qu'une contravention, un délit et un crime ?", o: ["Trois mots pour la même chose", "Trois catégories d'infractions, du moins grave au plus grave", "Des types d'impôts", "Des décisions de justice"], c: 1, e: "Ce sont trois catégories d'infractions pénales par ordre de gravité : les contraventions (ex: stationnement interdit), les délits (ex: vol, discrimination, conduite en état d'ivresse), et les crimes (ex: meurtre, viol, terrorisme). Chacune a des sanctions et des juridictions différentes." },
    { id:"db-2-052", t:2, lvl:"B1", q: "Qui peut porter plainte en France ?", o: ["Seulement les Français", "Toute personne victime d'une infraction", "Seulement les hommes", "Seulement les adultes"], c: 1, e: "Toute personne victime d'une infraction, quelle que soit sa nationalité, peut porter plainte auprès de la police, de la gendarmerie ou directement auprès du procureur de la République. C'est un droit fondamental pour faire valoir ses droits." },

    // === ORGANISATION TERRITORIALE ET ÉLECTIONS (Questions 53-60) ===
    { id:"db-2-053", t:2, lvl:"B1", q: "Combien y a-t-il de niveaux de collectivités locales en France ?", o: ["1 : la région", "3 : commune, département, région", "2 : ville et région", "5 niveaux"], c: 1, e: "Il existe trois niveaux de collectivités territoriales en France : la commune (niveau local), le département (niveau intermédiaire), et la région (niveau supérieur). Chacune a des compétences propres définies par la loi." },
    { id:"db-2-054", t:2, lvl:"B1", q: "Qui dirige une commune ?", o: ["Le préfet", "Le maire et le conseil municipal", "Le député", "Le Président"], c: 1, e: "Une commune est dirigée par le maire, élu par le conseil municipal, lui-même élu par les citoyens lors des élections municipales. Le maire représente la commune et exécute les décisions du conseil municipal." },
    { id:"db-2-055", t:2, lvl:"B1", q: "Qui représente l'État dans le département ?", o: ["Le maire", "Le préfet", "Le député", "Le​​​​​​​​​​​​​​​​ conseiller départemental"], c: 1, e: "Le préfet représente l'État dans le département. Il est nommé par le Président de la République. Le préfet fait appliquer les lois, coordonne les services de l'État et veille à l'ordre public." }, 
    { id:"db-2-056", t:2, lvl:"B1", q: "Pour combien d'années les maires sont-ils élus ?", o: ["3 ans", "5 ans", "6 ans", "10 ans"], c: 2, e: "Les maires sont élus pour un mandat de 6 ans. Plus précisément, les conseillers municipaux sont élus pour 6 ans, et c'est le conseil municipal qui élit ensuite le maire parmi ses membres." }, 
    { id:"db-2-057", t:2, lvl:"B1", q: "Quelles sont les principales compétences de la commune ?", o: ["L'armée", "Les écoles maternelles et primaires, l'état civil, la voirie locale", "Les lycées", "La police nationale"], c: 1, e: "Les communes gèrent notamment les écoles maternelles et primaires, l'état civil (naissances, mariages, décès), la voirie communale, les activités sportives et culturelles locales. Le maire est aussi responsable de la police municipale." }, 
    { id:"db-2-058", t:2, lvl:"B1", q: "Quelles sont les principales compétences des départements ?", o: ["Les écoles primaires", "Les collèges, l'aide sociale, les routes départementales", "Les universités", "La défense nationale"], c: 1, e: "Les départements gèrent principalement les collèges (construction et entretien), l'aide sociale (RSA, protection de l'enfance, aide aux personnes âgées), les routes départementales et les services de secours (pompiers)." }, 
    { id:"db-2-059", t:2, lvl:"B2", q: "Quelles sont les principales compétences des régions ?", o: ["Les mairies", "Les lycées, la formation professionnelle, les transports régionaux", "Les collèges", "La justice"], c: 1, e: "Les régions gèrent principalement les lycées (construction et entretien), la formation professionnelle, les transports régionaux (TER, cars), et le développement économique. Elles jouent un rôle important dans l'aménagement du territoire." }, 
    { id:"db-2-060", t:2, lvl:"B1", q: "Combien y a-t-il de régions en France métropolitaine ?", o: ["22", "13", "18", "27"], c: 1, e: "Il y a 13 régions en France métropolitaine depuis la réforme territoriale de 2016. À cela s'ajoutent 5 régions d'outre-mer (Guadeloupe, Martinique, Guyane, La Réunion, Mayotte)." },

    // === QUESTIONS COMPLÉMENTAIRES - ÉTAT DE DROIT ET CONSTITUTION (Questions 61-68) ===
    { id:"db-2-061", t:2, lvl:"B1", q: "Que garantit l'État de droit aux citoyens ?", o: ["Le droit de faire ce qu'on veut", "Que personne, même les gouvernants, n'est au-dessus des lois", "Que l'État a toujours raison", "Que les riches ont plus de droits"], c: 1, e: "L'État de droit garantit que la loi s'applique à tous de manière égale, y compris aux dirigeants et aux autorités publiques. Personne n'est au-dessus des lois, et chacun peut faire valoir ses droits devant la justice si ses libertés sont violées." },
    { id:"db-2-062", t:2, lvl:"B2", q: "Un président de la République peut-il être poursuivi en justice pour un crime ?", o: ["Non, il est intouchable", "Oui, il peut être jugé par la Haute Cour après la fin de son mandat", "Non, jamais de sa vie", "Oui, immédiatement comme tout citoyen"], c: 1, e: "Pendant son mandat, le Président bénéficie d'une immunité temporaire. Mais pour les actes les plus graves (haute trahison), il peut être destitué par la Haute Cour (Parlement réuni). Après son mandat, il peut être jugé comme tout citoyen pour les infractions commises." },
    { id:"db-2-063", t:2, lvl:"B1", q: "La loi est l'expression de quoi selon la Déclaration de 1789 ?", o: ["De la volonté du roi", "De la volonté générale du peuple", "De la volonté du Président", "De la volonté des juges"], c: 1, e: "Selon l'article 6 de la Déclaration des Droits de l'Homme de 1789, 'La loi est l'expression de la volonté générale'. Cela signifie que les lois sont faites au nom du peuple et doivent refléter l'intérêt commun de tous les citoyens." },
    { id:"db-2-064", t:2, lvl:"B2", q: "Pourquoi est-il important de séparer les trois pouvoirs dans une démocratie ?", o: ["Pour créer plus d'emplois publics", "Pour éviter qu'une seule personne concentre tous les pouvoirs et abuse de son autorité", "Pour ralentir les décisions", "Pour compliquer le système"], c: 1, e: "La séparation des pouvoirs (législatif, exécutif, judiciaire) est essentielle pour éviter la dictature. Si une seule personne ou institution concentre tous les pouvoirs, elle peut en abuser. Chaque pouvoir contrôle les autres, ce qui protège les libertés des citoyens." },
    { id:"db-2-065", t:2, lvl:"B1", q: "À la fin de son mandat, le Président peut-il décider de rester au pouvoir ?", o: ["Oui, s'il le souhaite", "Non, il doit organiser de nouvelles élections", "Oui, avec l'accord du Premier ministre", "Oui, s'il est populaire"], c: 1, e: "Non, le Président ne peut pas prolonger son mandat de sa propre initiative. À la fin de son mandat de 5 ans, de nouvelles élections présidentielles doivent obligatoirement être organisées. C'est un principe fondamental de la démocratie : l'alternance au pouvoir." },
    { id:"db-2-066", t:2, lvl:"B1", q: "Qu'est-ce que l'Hôtel Matignon ?", o: ["Un hôtel de luxe à Paris", "La résidence officielle et le lieu de travail du Premier ministre", "Le siège du Parlement", "La résidence du Président"], c: 1, e: "L'Hôtel Matignon, situé à Paris, est la résidence officielle et le lieu de travail du Premier ministre français. C'est là que se tiennent les réunions gouvernementales et que le Premier ministre coordonne l'action du gouvernement." },
    { id:"db-2-067", t:2, lvl:"B2", q: "Quel est le rôle principal du Président de la République ?", o: ["Voter les lois", "Garantir le fonctionnement des institutions, l'indépendance nationale et représenter la France", "Diriger les entreprises", "Rendre la justice"], c: 1, e: "Le Président de la République est le chef de l'État. Il garantit le fonctionnement régulier des institutions, veille au respect de la Constitution, assure l'indépendance nationale et l'intégrité du territoire. Il représente la France à l'étranger et est le chef des armées." },
    { id:"db-2-068", t:2, lvl:"B1", q: "Quel est le rôle principal du Premier ministre ?", o: ["Voter les lois", "Diriger l'action du gouvernement et assurer l'exécution des lois", "Juger les criminels", "Élire le Président"], c: 1, e: "Le Premier ministre dirige l'action du gouvernement, coordonne le travail des ministres et assure l'exécution des lois. Il est responsable devant l'Assemblée nationale et peut être renversé par une motion de censure." },

    // === QUESTIONS COMPLÉMENTAIRES - COLLECTIVITÉS ET ADMINISTRATION (Questions 69-76) ===
    { id:"db-2-069", t:2, lvl:"B1", q: "Qui est le chef du gouvernement en France ?", o: ["Le Président de la République", "Le Premier ministre", "Le Président de l'Assemblée nationale", "Le maire de Paris"], c: 1, e: "Le chef du gouvernement en France est le Premier ministre. Il est nommé par le Président de la République et dirige l'action des ministres. Le Président est le chef de l'État, mais c'est le Premier ministre qui dirige le gouvernement au quotidien." },
    { id:"db-2-070", t:2, lvl:"B1", q: "Quelle est l'organisation administrative de la France ?", o: ["Un seul niveau : l'État central", "Trois niveaux de collectivités : communes, départements, régions", "Uniquement des régions autonomes", "Des provinces indépendantes"], c: 1, e: "La France est organisée en collectivités territoriales à trois niveaux : les communes (36 000 environ), les départements (101) et les régions (18). Chaque niveau a des compétences propres et des élus. L'État central coordonne l'ensemble." },
    { id:"db-2-071", t:2, lvl:"B2", q: "Combien y a-t-il environ de communes en France ?", o: ["1 000", "10 000", "36 000", "100 000"], c: 2, e: "La France compte environ 36 000 communes, ce qui en fait le pays d'Europe avec le plus grand nombre de communes. Chaque commune est dirigée par un maire et un conseil municipal élus pour 6 ans." },
    { id:"db-2-072", t:2, lvl:"B1", q: "Quel est le rôle principal des communes ?", o: ["Gérer les lycées", "Gérer les services de proximité : écoles primaires, état civil, voirie locale", "Collecter les impôts nationaux", "Diriger l'armée"], c: 1, e: "Les communes gèrent les services de proximité pour leurs habitants : écoles maternelles et primaires, état civil (naissances, mariages, décès), voirie et éclairage, eau et assainissement, activités culturelles et sportives locales." },
    { id:"db-2-073", t:2, lvl:"B2", q: "Quel est le rôle principal des départements ?", o: ["Gérer les écoles primaires", "Gérer l'action sociale, les collèges et les routes départementales", "Voter les lois nationales", "Gérer les universités"], c: 1, e: "Les départements ont trois missions principales : l'action sociale (aide aux personnes âgées, handicapées, enfance en danger, RSA), la gestion des collèges, et l'entretien des routes départementales. Ils sont dirigés par un conseil départemental élu." },
    { id:"db-2-074", t:2, lvl:"B1", q: "Quelle est la durée du mandat du maire et du conseil municipal ?", o: ["4 ans", "5 ans", "6 ans", "7 ans"], c: 2, e: "Le maire et les conseillers municipaux sont élus pour un mandat de 6 ans lors des élections municipales. Le conseil municipal élit ensuite le maire parmi ses membres. Ce mandat peut être renouvelé sans limite." },
    { id:"db-2-075", t:2, lvl:"B2", q: "Une personne peut-elle voter à la place d'une autre ?", o: ["Oui, librement", "Oui, uniquement avec une procuration officielle", "Non, jamais", "Oui, si c'est un membre de sa famille"], c: 1, e: "Oui, mais uniquement avec une procuration officielle établie au commissariat, à la gendarmerie ou au tribunal. La personne qui vote à votre place (le mandataire) doit être inscrite dans la même commune. Chaque électeur ne peut détenir qu'une seule procuration établie en France." },
    { id:"db-2-076", t:2, lvl:"B1", q: "Le vote est-il obligatoire en France ?", o: ["Oui, sous peine d'amende", "Non, c'est un droit mais pas une obligation légale", "Oui, pour les élections présidentielles", "Oui, après 21 ans"], c: 1, e: "Non, le vote n'est pas obligatoire en France. C'est un droit fondamental et un devoir civique moral, mais aucune sanction légale n'est prévue si un citoyen ne vote pas. Cependant, voter est essentiel pour faire vivre la démocratie." },

    // === QUESTIONS COMPLÉMENTAIRES - UNION EUROPÉENNE (Questions 77-90) ===
    { id:"db-2-077", t:2, lvl:"B1", q: "Depuis quand l'euro est-il utilisé en France ?", o: ["1992", "1999 (monnaie scripturale) et 2002 (pièces et billets)", "2010", "1989"], c: 1, e: "L'euro a été introduit en France en 1999 pour les transactions bancaires et financières, puis les pièces et billets sont arrivés le 1er janvier 2002, remplaçant le franc français. L'euro est la monnaie commune de 20 pays de la zone euro." },
    { id:"db-2-078", t:2, lvl:"B1", q: "Quel État a quitté l'Union européenne en 2020 ?", o: ["La Suisse", "Le Royaume-Uni", "La Norvège", "L'Islande"], c: 1, e: "Le Royaume-Uni a quitté l'Union européenne le 31 janvier 2020, suite au référendum de 2016 sur le Brexit. C'est le premier État membre à avoir quitté l'UE. La Suisse, la Norvège et l'Islande n'ont jamais fait partie de l'Union européenne." },
    { id:"db-2-079", t:2, lvl:"B1", q: "Quelle est la devise de l'Union européenne ?", o: ["Liberté, Égalité, Fraternité", "Unie dans la diversité", "L'Europe pour tous", "Paix et prospérité"], c: 1, e: "La devise de l'Union européenne est 'Unie dans la diversité'. Elle symbolise l'idée que les Européens s'unissent pour œuvrer ensemble à la paix et à la prospérité, tout en s'enrichissant de leurs différentes cultures, traditions et langues." },
    { id:"db-2-080", t:2, lvl:"B1", q: "Quel est l'hymne de l'Union européenne ?", o: ["La Marseillaise", "L'Ode à la joie de Beethoven", "God Save the Queen", "L'Hymne à l'amour"], c: 1, e: "L'hymne européen est l'Ode à la joie, tirée de la 9e symphonie de Ludwig van Beethoven. Adopté en 1985, il symbolise les idéaux de liberté, de paix et de solidarité qui fondent l'Union européenne. Il n'a pas de paroles officielles." },
    { id:"db-2-081", t:2, lvl:"B1", q: "De quelle couleur est le drapeau européen ?", o: ["Rouge et blanc", "Bleu avec des étoiles jaunes", "Vert et blanc", "Tricolore"], c: 1, e: "Le drapeau européen est bleu avec douze étoiles jaunes disposées en cercle. Le bleu représente le ciel occidental et les étoiles symbolisent les peuples d'Europe. Le nombre 12 représente la perfection et l'unité, pas le nombre de pays membres." },
    { id:"db-2-082", t:2, lvl:"B2", q: "En quelle année le traité de Maastricht a-t-il été signé ?", o: ["1957", "1985", "1992", "2007"], c: 2, e: "Le traité de Maastricht a été signé en 1992. Il a fondé l'Union européenne telle qu'on la connaît aujourd'hui, créant la citoyenneté européenne et préparant l'introduction de l'euro. C'est un traité fondateur de la construction européenne moderne." },
    { id:"db-2-083", t:2, lvl:"B1", q: "Où siège le Parlement européen ?", o: ["Uniquement à Bruxelles", "À Strasbourg (sessions plénières) et Bruxelles (commissions)", "À Paris", "À Berlin"], c: 1, e: "Le Parlement européen siège à Strasbourg pour les sessions plénières mensuelles et à Bruxelles pour les réunions des commissions parlementaires. Le secrétariat est à Luxembourg. Strasbourg est le siège officiel, symbole de la réconciliation franco-allemande." },
    { id:"db-2-084", t:2, lvl:"B2", q: "Où siège la Commission européenne ?", o: ["À Strasbourg", "À Bruxelles", "À Paris", "À Luxembourg"], c: 1, e: "La Commission européenne, qui est l'organe exécutif de l'UE, siège à Bruxelles en Belgique. Elle propose les lois européennes, veille à leur application et gère le budget de l'Union. Elle est composée d'un commissaire par État membre." },
    { id:"db-2-085", t:2, lvl:"B2", q: "Quel traité a marqué le début de la construction européenne en 1951 ?", o: ["Le traité de Maastricht", "Le traité de Paris créant la CECA", "Le traité de Rome", "Le traité de Lisbonne"], c: 1, e: "Le traité de Paris de 1951 a créé la CECA (Communauté Européenne du Charbon et de l'Acier), première étape de la construction européenne. Six pays fondateurs (France, Allemagne, Italie, Belgique, Pays-Bas, Luxembourg) ont mis en commun leurs ressources en charbon et acier pour garantir la paix." },
    { id:"db-2-086", t:2, lvl:"B1", q: "Quel pays est un pays fondateur de l'Union européenne ?", o: ["Le Royaume-Uni", "La France", "L'Espagne", "La Pologne"], c: 1, e: "La France est l'un des six pays fondateurs de la construction européenne avec l'Allemagne, l'Italie, la Belgique, les Pays-Bas et le Luxembourg. Ces six pays ont signé le traité de Paris (1951) puis les traités de Rome (1957). Le Royaume-Uni n'a rejoint qu'en 1973." },
    { id:"db-2-087", t:2, lvl:"B1", q: "Quel pays n'est pas membre de l'Union européenne ?", o: ["L'Allemagne", "La Suisse", "L'Italie", "La Belgique"], c: 1, e: "La Suisse n'est pas membre de l'Union européenne. Elle a refusé d'y adhérer par référendum. La Norvège, l'Islande et le Liechtenstein ne sont pas non plus membres de l'UE. En revanche, l'Allemagne, l'Italie et la Belgique sont des pays fondateurs." },
    { id:"db-2-088", t:2, lvl:"B2", q: "Quel traité concerne la construction de l'Union européenne actuelle ?", o: ["Le traité de Versailles", "Le traité de Maastricht (1992) et le traité de Lisbonne (2007)", "Le traité de Paris de 1815", "Le traité de Westphalie"], c: 1, e: "L'Union européenne actuelle repose sur plusieurs traités. Le traité de Maastricht (1992) a créé l'UE et la citoyenneté européenne. Le traité de Lisbonne (2007) a modernisé les institutions et renforcé le rôle du Parlement européen." },
    { id:"db-2-089", t:2, lvl:"B1", q: "Qui élit les députés européens ?", o: ["Les gouvernements nationaux", "Les citoyens européens au suffrage universel direct", "Le Parlement français", "La Commission européenne"], c: 1, e: "Les députés européens sont élus directement par les citoyens de chaque pays membre au suffrage universel direct. Les élections européennes ont lieu tous les 5 ans. Tout citoyen européen majeur peut voter pour élire ses représentants au Parlement européen." },
    { id:"db-2-090", t:2, lvl:"B1", q: "Quand célèbre-t-on la Journée de l'Europe ?", o: ["Le 14 juillet", "Le 9 mai", "Le 1er janvier", "Le 8 mai"], c: 1, e: "La Journée de l'Europe est célébrée le 9 mai. Cette date commémore la déclaration de Robert Schuman du 9 mai 1950, considérée comme l'acte fondateur de la construction européenne. C'est l'occasion de célébrer la paix et l'unité en Europe." },

    // === QUESTIONS COMPLÉMENTAIRES - COUVERTURE OFFICIELLE (Thème 2) ===
    { id:"db-2-091", t:2, lvl:"B1", q: "Dans quel type de régime politique les dirigeants sont-ils élus par les citoyens ?", o: ["Une monarchie absolue", "Une démocratie", "Une dictature", "Une théocratie"], c: 1, e: "Dans une démocratie, les dirigeants sont élus par les citoyens au moyen d'élections libres. La France est une démocratie représentative : les citoyens élisent des représentants (Président, députés, sénateurs, maires) qui prennent les décisions en leur nom." },
    { id:"db-2-092", t:2, lvl:"B1", q: "En France, qui doit respecter la loi ?", o: ["Uniquement les citoyens français", "Tout le monde : citoyens, étrangers, dirigeants, entreprises", "Seulement les personnes majeures", "Uniquement les fonctionnaires"], c: 1, e: "En France, tout le monde doit respecter la loi, sans exception : les citoyens français, les étrangers vivant en France, les dirigeants politiques, les entreprises et les administrations. C'est le principe d'égalité devant la loi, inscrit dans la Constitution." },
    { id:"db-2-093", t:2, lvl:"B1", q: "Comment appelle-t-on le pouvoir de faire les lois et celui de les appliquer ?", o: ["Le pouvoir royal et le pouvoir religieux", "Le pouvoir législatif (faire les lois) et le pouvoir exécutif (les appliquer)", "Le pouvoir local et le pouvoir national", "Le pouvoir civil et le pouvoir militaire"], c: 1, e: "Le pouvoir législatif est le pouvoir de voter les lois : il appartient au Parlement (Assemblée nationale et Sénat). Le pouvoir exécutif est le pouvoir d'appliquer les lois : il appartient au Président de la République et au Gouvernement. Leur séparation est un fondement de la démocratie." },
    { id:"db-2-094", t:2, lvl:"B1", q: "Qui est élu lors des élections présidentielles en France ?", o: ["Le Premier ministre", "Le Président de la République", "Les députés", "Les maires"], c: 1, e: "Lors des élections présidentielles, les citoyens français élisent le Président de la République au suffrage universel direct. Le scrutin a lieu tous les 5 ans, en deux tours. Le Président est le chef de l'État et des armées." },
    { id:"db-2-095", t:2, lvl:"B1", q: "Qui est élu lors des élections législatives ?", o: ["Le Président de la République", "Les sénateurs", "Les députés de l'Assemblée nationale", "Les maires"], c: 1, e: "Lors des élections législatives, les citoyens élisent les 577 députés de l'Assemblée nationale au suffrage universel direct. Les députés votent les lois et contrôlent l'action du Gouvernement. Les élections législatives ont lieu tous les 5 ans." },
    { id:"db-2-096", t:2, lvl:"B1", q: "Qui est élu lors des élections municipales ?", o: ["Les députés", "Le préfet", "Le conseil municipal et le maire", "Le président du département"], c: 1, e: "Lors des élections municipales, les citoyens élisent les conseillers municipaux de leur commune. Le conseil municipal élit ensuite le maire parmi ses membres. Le mandat dure 6 ans. Les citoyens européens résidant en France peuvent aussi voter aux élections municipales." },
    { id:"db-2-097", t:2, lvl:"B1", q: "Par qui l'auteur d'un délit ou d'un crime est-il jugé et sanctionné ?", o: ["Par le Président de la République", "Par un juge (la justice)", "Par la police", "Par le maire de la commune"], c: 1, e: "En France, seul un juge peut déclarer une personne coupable et prononcer une sanction. C'est le pouvoir judiciaire, indépendant du pouvoir politique. La police enquête et arrête les suspects, mais c'est la justice qui juge. Toute personne est présumée innocente jusqu'à sa condamnation." },
    { id:"db-2-098", t:2, lvl:"B1", q: "Que peut-on dire des partis politiques en France ?", o: ["Ils sont interdits par la Constitution", "Il n'en existe que deux", "Ils sont libres de se créer et de fonctionner, et ils participent à la vie démocratique", "Ils sont contrôlés par le Président"], c: 2, e: "La Constitution garantit la liberté de création et de fonctionnement des partis politiques. Ils concourent à l'expression du suffrage et participent à la vie démocratique. Il existe de nombreux partis en France, représentant des opinions variées, de la gauche à la droite." },
    { id:"db-2-099", t:2, lvl:"B1", q: "De combien d'étoiles est composé le drapeau de l'Union européenne ?", o: ["27 étoiles, une par pays membre", "12 étoiles dorées disposées en cercle", "50 étoiles blanches", "6 étoiles, une par pays fondateur"], c: 1, e: "Le drapeau européen comporte 12 étoiles dorées disposées en cercle sur fond bleu. Le nombre 12 ne représente pas le nombre de pays membres : il symbolise la perfection, la plénitude et l'unité. Ce drapeau est utilisé depuis 1985." },
    { id:"db-2-100", t:2, lvl:"B2", q: "Quel est l'âge minimum pour se présenter aux élections municipales en France ?", o: ["16 ans", "18 ans", "21 ans", "25 ans"], c: 1, e: "Pour se présenter aux élections municipales, il faut avoir au minimum 18 ans. Depuis 2000, tout citoyen majeur inscrit sur les listes électorales peut être candidat. Pour les élections présidentielles, l'âge minimum est également de 18 ans depuis la réforme de 2024." },
    
    // === DROITS FONDAMENTAUX ET TEXTES (Questions 1-12) ===
    { id:"db-3-001", t:3, lvl:"B1", q: "À quel âge a-t-on le droit de voter en France ?", o: ["16 ans", "18 ans", "21 ans", "25 ans"], c: 1, e: "On a le droit de voter à partir de 18 ans en France. C'est l'âge de la majorité légale et politique. Pour voter, il faut aussi être inscrit sur les listes électorales et ne pas avoir été privé de ses droits civiques par une décision de justice." },
    { id:"db-3-002", t:3, lvl:"B1", q: "Le vote est-il obligatoire en France ?", o: ["Oui, sous peine d'amende", "Non, c'est un droit mais pas une obligation légale", "Oui, sauf pour les personnes âgées", "Oui, uniquement pour les élections présidentielles"], c: 1, e: "Non, le vote n'est pas obligatoire en France. C'est un droit fondamental et un devoir civique moral, mais aucune sanction n'est prévue si un citoyen ne vote pas. Cependant, voter est un acte citoyen important pour la démocratie." },
    { id:"db-3-003", t:3, lvl:"B2", q: "Quelles conditions faut-il remplir pour voter aux élections françaises ?", o: ["Être majeur uniquement", "Être français, majeur, inscrit sur les listes électorales et jouir de ses droits civiques", "Avoir un diplôme", "Payer des impôts"], c: 1, e: "Pour voter en France, il faut remplir quatre conditions : avoir la nationalité française, être majeur (18 ans), être inscrit sur les listes électorales de sa commune, et jouir de ses droits civiques (ne pas avoir été privé du droit de vote par une condamnation)." },
    { id:"db-3-004", t:3, lvl:"B1", q: "Quel texte de 1789 garantit les droits fondamentaux des citoyens ?", o: ["Le Code civil", "La Déclaration des Droits de l'Homme et du Citoyen", "La Constitution de la Ve République", "Le Code pénal"], c: 1, e: "La Déclaration des Droits de l'Homme et du Citoyen de 1789 est un texte fondamental qui garantit les libertés et droits individuels. Adoptée pendant la Révolution française, elle affirme l'égalité, la liberté et les droits naturels. Elle a une valeur constitutionnelle." },
    { id:"db-3-005", t:3, lvl:"B1", q: "Que proclame l'article 1 de la Déclaration de 1789 ?", o: ["Les hommes naissent esclaves", "Les hommes naissent et demeurent libres et égaux en droits", "Les hommes doivent obéir au roi", "Les femmes n'ont pas de droits"], c: 1, e: "L'article 1 de la Déclaration de 1789 proclame : 'Les hommes naissent et demeurent libres et égaux en droits'. C'est le principe fondamental d'égalité qui s'applique à tous les êtres humains, quelle que soit leur origine ou condition." },
    { id:"db-3-006", t:3, lvl:"B2", q: "Qu'est-ce que la dignité humaine et pourquoi est-elle protégée ?", o: ["Un titre honorifique", "Le respect absolu de la personne humaine, valeur fondamentale inaliénable", "Un privilège des riches", "Une décoration"], c: 1, e: "La dignité humaine est le principe selon lequel chaque être humain a une valeur absolue qui doit être respectée. C'est un droit fondamental inaliénable : personne ne peut être traité de manière dégradante, humiliante ou inhumaine. L'État doit protéger la dignité de tous." },
    { id:"db-3-007", t:3, lvl:"B1", q: "Qu'est-ce que l'intégrité physique ?", o: ["Être honnête", "Le droit de ne pas subir de violences ou d'atteintes à son corps", "Avoir une bonne santé", "Être sportif"], c: 1, e: "L'intégrité physique est le droit fondamental de ne pas subir de violences, de tortures, de mutilations ou d'atteintes à son corps. Toute personne a le droit de voir son corps respecté. Les violences physiques sont punies par la loi." },
    { id:"db-3-008", t:3, lvl:"B2", q: "Qu'est-ce que l'intégrité psychologique ?", o: ["Être intelligent", "Le droit de ne pas subir de harcèlement, de pressions psychologiques ou de manipulations", "Avoir des diplômes", "Être heureux"], c: 1, e: "L'intégrité psychologique est le droit de ne pas subir de harcèlement moral, de pressions psychologiques, de manipulations ou de violences psychologiques. Les atteintes à l'intégrité mentale (harcèlement, intimidation) sont également punies par la loi." },
    { id:"db-3-009", t:3, lvl:"B1", q: "Qu'est-ce qu'un droit social ?", o: ["Le droit d'aller en boîte de nuit", "Un droit visant à garantir des conditions de vie dignes (santé, éducation, travail)", "Le droit d'avoir des amis", "Le droit de manifester"], c: 1, e: "Les droits sociaux sont des droits qui visent à assurer à chaque personne des conditions de vie dignes et équitables. Ils incluent le droit à l'éducation, à la santé, au travail, au logement, et à la protection sociale. L'État doit garantir ces droits." },
    { id:"db-3-010", t:3, lvl:"B1", q: "Le droit à l'éducation est-il garanti en France ?", o: ["Non, c'est un privilège", "Oui, l'instruction est obligatoire et l'école publique est gratuite", "Seulement pour les riches", "Seulement jusqu'à 12 ans"], c: 1, e: "Oui, le droit à l'éducation est garanti en France. L'instruction est obligatoire de 3 à 16 ans, et l'école publique est gratuite et laïque. C'est un droit fondamental qui permet à tous les enfants d'accéder au savoir." },
    { id:"db-3-011", t:3, lvl:"B2", q: "La France garantit-elle le droit à la santé ?", o: ["Non, la santé est privée", "Oui, via la Sécurité sociale et l'accès aux soins pour tous", "Seulement pour les Français", "Seulement dans les grandes villes"], c: 1, e: "Oui, la France garantit le droit à la santé via la Sécurité sociale qui rembourse les soins, et via l'accès aux soins d'urgence pour tous, y compris les personnes sans ressources (AME, CMU). C'est un pilier de la solidarité nationale." },
    { id:"db-3-012", t:3, lvl:"B1", q: "Qu'est-ce que la Charte de l'environnement de 2004 ?", o: ["Un guide touristique", "Un texte constitutionnel garantissant le droit à un environnement sain", "Une association écologique", "Une loi sur les parcs"], c: 1, e: "La Charte de l'environnement de 2004 est un texte à valeur constitutionnelle qui reconnaît le droit de chacun à vivre dans un environnement sain et équilibré. Elle impose aussi des devoirs de protection de l'environnement pour les générations futures." },

    // === OBLIGATIONS ET DEVOIRS DES CITOYENS (Questions 13-25) ===
    { id:"db-3-013", t:3, lvl:"B1", q: "Que signifie l'expression 'nul n'est censé ignorer la loi' ?", o: ["On peut ignorer la loi si on ne la connaît pas", "La loi s'applique à tous, même si on ne la connaît pas", "Seuls les juristes doivent connaître la loi", "La loi est secrète"], c: 1, e: "L'expression 'nul n'est censé ignorer la loi' signifie que la loi s'applique à tous, même si on ne la connaît pas personnellement. Ne pas connaître une loi ne dispense pas de la respecter. C'est pourquoi les lois sont publiées au Journal officiel." },
    { id:"db-3-014", t:3, lvl:"B1", q: "Est-il obligatoire de payer ses impôts en France ?", o: ["Non, c'est volontaire", "Oui, c'est un devoir citoyen obligatoire", "Seulement si on gagne beaucoup", "Seulement les entreprises"], c: 1, e: "Oui, payer ses impôts est un devoir obligatoire pour tous les citoyens et résidents. Les impôts financent les services publics (écoles, hôpitaux, routes, police, justice). Ne pas payer ses impôts ou frauder est un délit puni par la loi." },
    { id:"db-3-015", t:3, lvl:"B1", q: "Est-il obligatoire de déclarer ses revenus aux impôts ?", o: ["Non, seulement si on est riche", "Oui, tous les résidents doivent faire une déclaration", "Seulement les fonctionnaires", "Seulement si on possède une maison"], c: 1, e: "Oui, toute personne résidant en France doit déclarer ses revenus chaque année, même si elle ne paie pas d'impôts. Cette déclaration permet à l'administration de calculer les impôts dus et les éventuelles aides sociales. Ne pas déclarer est une infraction." },
    { id:"db-3-016", t:3, lvl:"B2", q: "Qu'est-ce que la fraude fiscale et comment est-elle sanctionnée ?", o: ["Oublier de payer, pas grave", "Dissimuler volontairement des revenus pour ne pas payer d'impôts, c'est un délit pénal", "Une erreur de calcul", "Un droit si on est malin"], c: 1, e: "La fraude fiscale consiste à dissimuler volontairement des revenus ou à mentir pour échapper à l'impôt. C'est un délit pénal grave puni par de lourdes amendes (jusqu'à 500 000 euros) et des peines de prison (jusqu'à 5 ans). La fraude prive la collectivité de ressources." },
    { id:"db-3-017", t:3, lvl:"B1", q: "Qu'est-ce que les cotisations sociales ?", o: ["Des dons volontaires", "Des prélèvements sur les salaires pour financer la Sécurité sociale", "Des amendes", "Des impôts locaux"], c: 1, e: "Les cotisations sociales sont des prélèvements obligatoires sur les salaires (payés par l'employeur et le salarié) qui financent la Sécurité sociale : santé, retraite, chômage, allocations familiales. C'est un système de solidarité collective." },
    { id:"db-3-018", t:3, lvl:"B1", q: "Quel est le rôle de la police et de la gendarmerie ?", o: ["Faire peur aux gens", "Garantir la sécurité, l'ordre public et faire respecter la loi", "Collecter les impôts", "Juger les criminels"], c: 1, e: "Le rôle de la police et de la gendarmerie est de garantir la sécurité des personnes et des biens, de maintenir l'ordre public, de prévenir et constater les infractions, et d'arrêter les auteurs de crimes et délits. Ils sont au service de la loi et des citoyens." },
    { id:"db-3-019", t:3, lvl:"B2", q: "Qu'est-ce que la Journée Défense et Citoyenneté (JDC) ?", o: ["Un jour férié", "Une journée obligatoire d'information sur la défense nationale à partir de 16 ans", "Un service militaire de 2 ans", "Une fête nationale"], c: 1, e: "La Journée Défense et Citoyenneté (JDC, anciennement JAPD) est une journée obligatoire d'information sur la défense nationale et les enjeux de citoyenneté. Tous les jeunes Français doivent y participer entre 16 et 25 ans après leur recensement." },
    { id:"db-3-020", t:3, lvl:"B1", q: "À quel âge doit-on se faire recenser à la mairie ?", o: ["12 ans", "16 ans", "18 ans", "21 ans"], c: 1, e: "Tous les jeunes Français doivent se faire recenser à la mairie dès 16 ans (dans les 3 mois suivant leur anniversaire). Ce recensement est obligatoire et permet de participer à la Journée Défense et Citoyenneté et de s'inscrire sur les listes électorales." },
    { id:"db-3-021", t:3, lvl:"B1", q: "Un citoyen français peut-il être juré dans un procès ?", o: ["Non, jamais", "Oui, c'est un devoir citoyen possible", "Seulement les avocats", "Seulement les juges professionnels"], c: 1, e: "Oui, tout citoyen français majeur peut être appelé à être juré dans un procès d'assises (crimes graves). C'est un devoir civique qui permet aux citoyens de participer directement à la justice. Les jurés sont tirés au sort sur les listes électorales." },
    { id:"db-3-022", t:3, lvl:"B2", q: "Peut-on refuser d'être juré dans un procès d'assises ?", o: ["Oui, librement", "Non, sauf motifs légitimes graves (maladie, impossibilité majeure)", "Oui, si on a peur", "Oui, si on est occupé"], c: 1, e: "Non, on ne peut refuser d'être juré que pour des motifs légitimes et graves (maladie grave, impossibilité professionnelle majeure). Refuser sans raison valable peut entraîner une amende. C'est considéré comme un devoir citoyen important." },
    { id:"db-3-023", t:3, lvl:"B1", q: "Qu'est-ce qu'une attitude citoyenne ?", o: ["Critiquer tout le temps", "Contribuer au bien collectif et respecter les règles communes", "Penser uniquement à soi", "Refuser de payer des impôts"], c: 1, e: "Une attitude citoyenne consiste à contribuer au bien collectif, respecter les règles communes, autrui et l'environnement. Cela inclut voter, payer ses impôts, respecter les lois, aider son prochain, et participer à la vie de la communauté." },
    { id:"db-3-024", t:3, lvl:"B1", q: "Peut-on jeter ses déchets par terre dans la rue ?", o: ["Oui, c'est normal", "Non, c'est interdit et puni par une amende", "Oui, si personne ne regarde", "Seulement la nuit"], c: 1, e: "Non, jeter ses déchets par terre est une infraction punie d'une amende (jusqu'à 135 euros). C'est un comportement incivique qui nuit à l'environnement et à la propreté collective. Chacun doit respecter l'espace public." },
    { id:"db-3-025", t:3, lvl:"B2", q: "Qu'est-ce que le respect de l'environnement en tant que devoir citoyen ?", o: ["Une option facultative", "Une responsabilité collective pour préserver la nature pour les générations futures", "Un hobby pour écologistes", "Une mode passagère"], c: 1, e: "Le respect de l'environnement est un devoir citoyen inscrit dans la Charte de l'environnement (2004). Chacun doit contribuer à la préservation de la nature et lutter contre la pollution pour garantir un environnement sain aux générations futures. C'est un devoir collectif." },

    // === LIBERTÉS INDIVIDUELLES ET LIMITES (Questions 26-38) ===
    { id:"db-3-026", t:3, lvl:"B1", q: "Les libertés individuelles sont-elles absolues en France ?", o: ["Oui, sans aucune limite", "Non, elles sont encadrées par la loi pour protéger l'ordre public et les droits d'autrui", "Oui, sauf en prison", "Non, elles sont interdites"], c: 1, e: "Non, les libertés individuelles ne sont pas absolues. Elles sont garanties mais encadrées par la loi. Elles s'arrêtent là où commence la liberté d'autrui et peuvent être limitées pour préserver l'ordre public, la sécurité, la santé publique et la dignité humaine." },
    { id:"db-3-027", t:3, lvl:"B2", q: "Qu'est-ce que l'ordre public et pourquoi peut-il limiter les libertés ?", o: ["Le silence dans les rues", "L'ensemble des règles garantissant la sécurité, la tranquillité, la salubrité et la dignité", "L'obéissance au gouvernement", "L'interdiction de manifester"], c: 1, e: "L'ordre public regroupe les conditions nécessaires au bon fonctionnement de la société : sécurité, tranquillité publique, salubrité (hygiène), et respect de la dignité humaine. Les libertés peuvent être limitées pour préserver l'ordre public (ex: interdire une manifestation violente)." },
    { id:"db-3-028", t:3, lvl:"B1", q: "Peut-on faire absolument tout ce qu'on veut chez soi ?", o: ["Oui, c'est son domicile", "Non, certaines règles s'appliquent même chez soi (violences, nuisances graves, infractions)", "Oui, sauf si on a des voisins", "Non, la police surveille tout"], c: 1, e: "Non, même chez soi, on doit respecter certaines règles : pas de violences (domestiques, sur les enfants), pas de nuisances graves pour le voisinage (tapage nocturne), pas d'activités illégales (drogues, trafic). Le domicile est protégé mais pas tout est permis." },
    { id:"db-3-029", t:3, lvl:"B1", q: "Qu'est-ce qu'un tapage nocturne ?", o: ["Écouter de la musique le jour", "Faire du bruit excessif la nuit troublant la tranquillité du voisinage", "Parler à ses voisins", "Regarder la télévision"], c: 1, e: "Le tapage nocturne est le fait de faire du bruit excessif la nuit (généralement entre 22h et 7h) qui trouble la tranquillité des voisins. C'est une infraction punie par une amende. Il faut respecter le repos d'autrui." },
    { id:"db-3-030", t:3, lvl:"B2", q: "Peut-on refuser de se soumettre à un contrôle d'identité par la police ?", o: ["Oui, c'est une liberté", "Non, refuser est une infraction passible d'amende et de garde à vue", "Oui, si on n'a rien fait", "Seulement la nuit"], c: 1, e: "Non, on ne peut pas refuser un contrôle d'identité demandé par la police ou la gendarmerie. Refuser de présenter ses papiers ou de décliner son identité est une infraction (outrage et rébellion) qui peut entraîner une garde à vue et des poursuites." },
    { id:"db-3-031", t:3, lvl:"B1", q: "La police peut-elle entrer chez vous sans votre autorisation ?", o: ["Oui, quand elle veut", "Seulement avec une autorisation judiciaire ou en cas de flagrant délit", "Non, jamais", "Seulement si vous êtes étranger"], c: 1, e: "En principe, non. Le domicile est inviolable. La police ne peut entrer chez vous qu'avec une autorisation judiciaire (mandat de perquisition) ou en cas de flagrant délit (crime ou délit en train de se commettre). Votre consentement peut aussi l'autoriser." },
    { id:"db-3-032", t:3, lvl:"B1", q: "Qu'est-ce qu'un flagrant délit ?", o: ["Un délit grave", "Une infraction en train de se commettre ou qui vient de se commettre", "Une erreur judiciaire", "Un crime ancien"], c: 1, e: "Un flagrant délit est une infraction qui se commet actuellement ou qui vient de se commettre. En flagrant délit, la police a des pouvoirs étendus : arrestation immédiate possible, perquisition sans autorisation du juge. C'est une situation d'urgence." },
    { id:"db-3-033", t:3, lvl:"B2", q: "Qu'est-ce que le droit au respect de la vie privée ?", o: ["Ne pas avoir de voisins", "Le droit de protéger sa vie personnelle, familiale et son image", "Le droit d'être seul", "Le droit de ne pas travailler"], c: 1, e: "Le droit au respect de la vie privée protège votre intimité personnelle et familiale, votre domicile, votre correspondance et votre image. Nul ne peut divulguer des informations privées sur vous ou publier votre photo sans votre consentement. C'est un droit fondamental." },
    { id:"db-3-034", t:3, lvl:"B1", q: "Peut-on filmer ou photographier quelqu'un dans la rue sans son accord ?", o: ["Oui, librement", "En principe non si la personne est identifiable et que la photo est diffusée publiquement", "Oui, toujours", "Seulement les touristes"], c: 1, e: "C'est complexe : on peut photographier une scène de rue, mais si une personne est clairement identifiable et isolée, il faut en principe son accord pour diffuser la photo publiquement. Filmer quelqu'un de manière insistante ou diffuser son image peut violer son droit à l'image." },
    { id:"db-3-035", t:3, lvl:"B1", q: "Qu'est-ce que le secret médical ?", o: ["Les médecins ne parlent pas entre eux", "L'obligation pour les professionnels de santé de ne pas divulguer les informations sur leurs patients", "Les médecins gagnent beaucoup d'argent", "Une technique chirurgicale"], c: 1, e: "Le secret médical oblige les professionnels de santé (médecins, infirmiers, pharmaciens) à ne pas divulguer les informations personnelles et médicales de leurs patients. C'est un principe fondamental qui protège la vie privée et la confiance. Le violer est un délit." },
    { id:"db-3-036", t:3, lvl:"B2", q: "Dans quels cas le secret médical peut-il être levé ?", o: ["Jamais, il est absolu", "Dans des cas exceptionnels graves prévus par la loi (maltraitance d'enfants, menace grave)", "Quand la famille le demande", "Quand le médecin le souhaite"], c: 1, e: "Le secret médical peut être levé dans des cas exceptionnels et graves prévus par la loi : maltraitance sur mineur ou personne vulnérable, risque de crime grave imminent, obligation légale de signalement. Le médecin doit alors alerter les autorités pour protéger des vies." },
    { id:"db-3-037", t:3, lvl:"B1", q: "Peut-on ouvrir le courrier de quelqu'un d'autre ?", o: ["Oui, si on vit ensemble", "Non, c'est une violation du secret de la correspondance, un délit", "Oui, si c'est de la famille", "Oui, si on a un doute"], c: 1, e: "Non, ouvrir le courrier personnel de quelqu'un d'autre sans son autorisation est un délit : violation du secret de la correspondance. Même entre époux ou membres d'une famille, chacun a droit au respect de son courrier. C'est puni d'un an de prison." },
    { id:"db-3-038", t:3, lvl:"B1", q: "Qu'est-ce que la protection des données personnelles ?", o: ["Un antivirus", "Le droit de contrôler l'usage de vos informations personnelles par les entreprises et administrations", "Une assurance", "Un mot de passe"], c: 1, e: "La protection des données personnelles garantit que vos informations (nom, adresse, données de santé, habitudes) ne peuvent être collectées, utilisées ou vendues sans votre consentement. En Europe, le RGPD protège ces droits. Vous pouvez demander l'accès, la rectification ou la suppression de vos données." },

    // === MISES EN SITUATION - DROITS ET DEVOIRS (Questions 39-50) ===
    { id:"db-3-039", t:3, lvl:"B1", q: "Jean, 17 ans, veut voter aux élections présidentielles. Peut-il le faire ?", o: ["Oui, à partir de 17 ans", "Non, il faut avoir 18 ans révolus", "Oui, avec l'autorisation de ses parents", "Oui, s'il travaille"], c: 1, e: "Non, Jean ne peut pas voter car il faut avoir 18 ans révolus le jour du scrutin pour exercer son droit de vote en France. La majorité électorale est fixée à 18 ans depuis 1974." },
    { id:"db-3-040", t:3, lvl:"B2", q: "Marie, citoyenne française, vit en Espagne. Peut-elle voter aux élections municipales espagnoles ?", o: ["Non, jamais", "Oui, les citoyens européens peuvent voter aux élections locales du pays où ils résident", "Seulement aux présidentielles", "Non, sauf si elle renonce à sa nationalité française"], c: 1, e: "Oui, en tant que citoyenne européenne résidant en Espagne, Marie peut voter aux élections municipales espagnoles et aux élections européennes. C'est un droit lié à la citoyenneté européenne qui facilite l'intégration dans le pays de résidence." },
    { id:"db-3-041", t:3, lvl:"B1", q: "Paul gagne 2000 euros par mois. Doit-il déclarer ses revenus aux impôts ?", o: ["Non, c'est trop peu", "Oui, tout le monde doit faire une déclaration", "Seulement s'il le souhaite", "Seulement après 10 ans de travail"], c: 1, e: "Oui, Paul doit obligatoirement déclarer ses revenus chaque année, quel que soit leur montant. Même s'il ne paie pas d'impôts (en dessous d'un certain seuil), la déclaration est obligatoire. Elle sert aussi à calculer d'autres droits (aides sociales, tarifs municipaux)." },
    { id:"db-3-042", t:3, lvl:"B2", q: "Léa découvre que son employeur ne déclare pas son salaire pour éviter les cotisations sociales. Que risque l'employeur ?", o: ["Rien, c'est courant", "Des poursuites pénales pour travail dissimulé et fraude sociale", "Juste une petite amende", "Rien si Léa est d'accord"], c: 1, e: "L'employeur risque des poursuites pénales graves pour travail dissimulé et fraude aux cotisations sociales. Les sanctions peuvent aller jusqu'à 3 ans de prison et 45 000 euros d'amende, plus le remboursement des cotisations. C'est un délit sérieux qui prive Léa de ses droits sociaux." },
    { id:"db-3-043", t:3, lvl:"B1", q: "Thomas, 15 ans, ne veut pas aller à l'école. Ses parents peuvent-ils l'en dispenser ?", o: ["Oui, c'est leur choix", "Non, l'instruction est obligatoire jusqu'à 16 ans", "Oui, s'il travaille", "Oui, s'il fait du sport"], c: 1, e: "Non, l'instruction est obligatoire pour tous les enfants de 3 à 16 ans en France. Les parents ont l'obligation légale de scolariser leur enfant (ou d'assurer une instruction à domicile déclarée). Ne pas le faire expose à des sanctions pénales." },
    { id:"db-3-044", t:3, lvl:"B1", q: "Sophie trouve un portefeuille avec 500 euros dans la rue. Peut-elle garder l'argent ?", o: ["Oui, c'est de la chance", "Non, elle doit le rapporter à la police ou à la mairie", "Oui, si personne ne la voit", "Oui, après 24 heures"], c: 1, e: "Non, Sophie doit rapporter le portefeuille aux objets trouvés (mairie, police). Garder un objet trouvé dont on connaît le propriétaire ou qu'on peut identifier est un délit d'appropriation frauduleuse. Si personne ne le réclame après un délai, elle pourra le récupérer." },
    { id:"db-3-045", t:3, lvl:"B2", q: "Lucas reçoit sa feuille d'impôts mais ne peut pas payer immédiatement. Que doit-il faire ?", o: ["Ne rien payer et attendre", "Contacter immédiatement les impôts pour demander un échéancier ou un délai", "Déménager dans un autre pays", "Ignorer la lettre"], c: 1, e: "Lucas doit immédiatement contacter le service des impôts pour expliquer sa situation et demander un échéancier de paiement ou un délai. L'administration fiscale peut accorder des facilités si on la contacte avant les poursuites. Ne rien faire aggrave la situation." }, 
    { id:"db-3-046", t:3, lvl:"B1", q: "Karim voit son voisin battre violemment son enfant. Que doit-il faire ?", o: ["Ne rien faire, c'est la vie privée", "Appeler la police ou le 119 (enfance en danger) immédiatement", "En parler aux voisins", "Attendre quelques jours"], c: 1, e: "Karim doit immédiatement appeler la police (17) ou le 119 (numéro d'urgence enfance en danger, gratuit et anonyme). Les violences sur enfant sont un crime. Tout témoin a le devoir moral et légal de signaler pour protéger l'enfant." }, 
    { id:"db-3-047", t:3, lvl:"B2", q: "Lucie est convoquée comme témoin dans un procès. Peut-elle refuser de témoigner ?", o: ["Oui, librement", "Non, témoigner est une obligation légale sauf cas exceptionnels", "Oui, si elle a peur", "Oui, si elle est occupée"], c: 1, e: "Non, témoigner devant la justice est une obligation légale. Refuser de comparaître ou de témoigner sans motif légitime grave peut entraîner une amende et même une contrainte par la force publique. Mentir sous serment (faux témoignage) est un délit pénal." }, 
    { id:"db-3-048", t:3, lvl:"B1", q: "Pierre organise une fête chez lui jusqu'à 4h du matin avec musique très forte. Ses voisins peuvent-ils porter plainte ?", o: ["Non, c'est chez lui", "Oui, pour tapage nocturne perturbant la tranquillité", "Non, sauf s'il fait ça tous les jours", "Seulement s'ils sont méchants"], c: 1, e: "Oui, les voisins peuvent appeler la police et porter plainte pour tapage nocturne. Faire du bruit excessif la nuit qui trouble la tranquillité du voisinage est une infraction, même chez soi. Pierre risque une amende de 68 à 450 euros." }, 
    { id:"db-3-049", t:3, lvl:"B2", q: "Claire, pharmacienne, raconte à ses amis qu'un voisin est venu acheter un traitement contre le cancer. A-t-elle le droit ?", o: ["Oui, c'est juste une conversation", "Non, c'est une violation grave du secret professionnel, un délit", "Oui, si elle ne dit pas le nom", "Oui, entre amis c'est permis"], c: 1, e: "Non, Claire commet un délit très grave : violation du secret professionnel. Elle risque un an de prison et 15 000 euros d'amende, plus une interdiction d'exercer. Le secret médical et pharmaceutique est absolu et protège toutes les informations sur les patients." }, 
    { id:"db-3-050", t:3, lvl:"B1", q: "David ouvre et lit les lettres personnelles de sa femme sans sa permission. Est-ce légal ?", o: ["Oui, ils sont mariés", "Non, c'est une violation du secret de la correspondance", "Oui, s'ils vivent ensemble", "Cela dépend du contenu"], c: 1, e: "Non, c'est illégal. Ouvrir le courrier personnel de quelqu'un, même son conjoint, sans autorisation est une violation du secret de la correspondance, un délit puni d'un an de prison et 45 000 euros d'amende. Le mariage ne supprime pas le droit à la vie privée." },

    // === JUSTICE ET PROCÉDURES (Questions 51-65) ===
    { id:"db-3-051", t:3, lvl:"B1", q: "Si vous êtes victime d'une infraction, où pouvez-vous porter plainte ?", o: ["Seulement au tribunal", "À la police, à la gendarmerie ou directement au procureur", "Seulement chez un avocat", "Sur internet uniquement"], c: 1, e: "Vous pouvez porter plainte dans n'importe quel commissariat de police ou brigade de gendarmerie, même si l'infraction s'est produite ailleurs. Vous pouvez aussi porter plainte directement auprès du procureur de la République par courrier, ou en ligne pour certaines infractions." },
    { id:"db-3-052", t:3, lvl:"B1", q: "Faut-il payer pour porter plainte en France ?", o: ["Oui, c'est payant", "Non, porter plainte est gratuit", "Oui, sauf si on est pauvre", "Cela dépend de l'infraction"], c: 1, e: "Non, porter plainte est totalement gratuit en France. C'est un droit fondamental accessible à tous. La police ou la gendarmerie ne peut pas refuser d'enregistrer une plainte. Si nécessaire, vous pouvez demander un avocat commis d'office gratuit (aide juridictionnelle)." },
    { id:"db-3-053", t:3, lvl:"B2", q: "Qu'est-ce que l'aide juridictionnelle ?", o: ["Une aide pour trouver un avocat", "Une aide financière de l'État pour payer les frais de justice si on a peu de ressources", "Une assurance privée", "Un prêt bancaire"], c: 1, e: "L'aide juridictionnelle est une aide financière accordée par l'État aux personnes ayant de faibles revenus pour payer les frais de justice (avocat, expert, huissier). Elle peut être totale ou partielle selon les ressources. Cela garantit l'accès à la justice pour tous." },
    { id:"db-3-054", t:3, lvl:"B1", q: "Qu'est-ce qu'une garde à vue ?", o: ["Une punition", "Une mesure permettant de retenir une personne au commissariat pour les besoins d'une enquête", "Une condamnation", "Un type de prison"], c: 1, e: "La garde à vue est une mesure permettant à la police de retenir une personne soupçonnée d'avoir commis une infraction dans les locaux du commissariat pour les besoins de l'enquête. Sa durée est limitée (24h, prolongeable) et la personne a des droits : être informée, voir un avocat, prévenir un proche." },
    { id:"db-3-055", t:3, lvl:"B2", q: "Quels sont les droits d'une personne en garde à vue ?", o: ["Aucun droit", "Droit de garder le silence, droit à un avocat, droit de prévenir un proche, droit à un examen médical", "Seulement le droit de téléphoner", "Seulement le droit à un avocat si on est riche"], c: 1, e: "Une personne en garde à vue a plusieurs droits fondamentaux : être informée des faits reprochés, garder le silence, demander un avocat (gratuit si nécessaire), faire prévenir un proche ou son employeur, demander un examen médical. Ces droits doivent être notifiés dès le début." },
    { id:"db-3-056", t:3, lvl:"B1", q: "Que signifie 'avoir le droit de garder le silence' ?", o: ["Ne jamais parler de sa vie", "Ne pas être obligé de répondre aux questions de la police", "Ne pas pouvoir parler", "Être muet"], c: 1, e: "Avoir le droit de garder le silence signifie qu'on n'est jamais obligé de répondre aux questions de la police lors d'un interrogatoire. On peut choisir de ne rien dire sans que cela soit considéré comme un aveu de culpabilité. C'est un droit fondamental." },
    { id:"db-3-057", t:3, lvl:"B1", q: "Peut-on avoir un avocat même si on n'a pas d'argent ?", o: ["Non, il faut être riche", "Oui, un avocat peut être désigné gratuitement (commis d'office)", "Non, sauf si on est innocent", "Seulement pour les crimes graves"], c: 1, e: "Oui, toute personne, même sans ressources, peut bénéficier d'un avocat. Pour les gardes à vue, un avocat est désigné gratuitement si on le demande. Pour un procès, on peut demander l'aide juridictionnelle qui permet d'avoir un avocat gratuit selon ses revenus." },
    { id:"db-3-058", t:3, lvl:"B2", q: "Qu'est-ce qu'une mise en examen ?", o: ["Une condamnation", "Une décision du juge d'instruction indiquant qu'il existe des indices graves de culpabilité", "Un acquittement", "Une amende"], c: 1, e: "La mise en examen est une décision prise par un juge d'instruction qui considère qu'il existe des indices graves ou concordants rendant vraisemblable la participation de la personne à l'infraction. Ce n'est pas une condamnation : la personne reste présumée innocente jusqu'au jugement." },
    { id:"db-3-059", t:3, lvl:"B1", q: "Qu'est-ce qu'un procès ?", o: ["Une fête", "Une audience devant un tribunal où un juge tranche un litige ou juge une infraction", "Une réunion de famille", "Un examen"], c: 1, e: "Un procès est une audience devant un tribunal où un juge (ou des juges et des jurés) examine les faits, écoute les parties (accusation et défense), et rend une décision de justice : condamnation, acquittement, ou règlement d'un litige civil." },
    { id:"db-3-060", t:3, lvl:"B1", q: "Qu'est-ce qu'un acquittement ?", o: ["Une condamnation légère", "Une décision déclarant l'accusé non coupable", "Une amende", "Une prison"], c: 1, e: "Un acquittement est une décision de justice déclarant l'accusé non coupable et le libérant de toutes poursuites. Cela signifie que le tribunal considère que les preuves ne sont pas suffisantes ou que la personne est innocente. L'acquitté retrouve sa pleine liberté." },
    { id:"db-3-061", t:3, lvl:"B2", q: "Qu'est-ce qu'une condamnation avec sursis ?", o: ["Pas de condamnation", "Une peine prononcée mais non appliquée si la personne ne récidive pas", "Une double peine", "Une condamnation annulée"], c: 1, e: "Une condamnation avec sursis signifie que la peine (prison ou amende) est prononcée mais qu'elle ne sera pas exécutée si le condamné ne commet pas de nouvelle infraction pendant un délai fixé (délai d'épreuve). Si la personne récidive, elle devra exécuter la peine initiale plus la nouvelle." },
    { id:"db-3-062", t:3, lvl:"B1", q: "Qu'est-ce qu'une amende pénale ?", o: ["Un cadeau", "Une somme d'argent à payer suite à une condamnation", "Un prêt", "Un salaire"], c: 1, e: "Une amende pénale est une sanction financière imposée par un tribunal à une personne condamnée pour une infraction. Son montant varie selon la gravité : de quelques euros pour une contravention à plusieurs millions pour certains crimes économiques. Ne pas la payer peut entraîner d'autres sanctions." },
    { id:"db-3-063", t:3, lvl:"B1", q: "Qu'est-ce qu'une peine de prison ferme ?", o: ["Une prison confortable", "Une peine de prison qui doit être exécutée immédiatement", "Une visite de prison", "Une prison pour les femmes"], c: 1, e: "Une peine de prison ferme est une peine d'emprisonnement qui doit être exécutée immédiatement et effectivement. Le condamné est incarcéré et doit purger sa peine en détention. Elle s'oppose à la peine avec sursis qui n'est pas exécutée si la personne ne récidive pas." },
    { id:"db-3-064", t:3, lvl:"B2", q: "Qu'est-ce qu'un casier judiciaire ?", o: ["Un placard au tribunal", "Un fichier recensant les condamnations pénales d'une personne", "Un certificat médical", "Un diplôme"], c: 1, e: "Le casier judiciaire est un fichier national qui recense toutes les condamnations pénales prononcées contre une personne. Certaines condamnations y restent inscrites et peuvent être consultées par les employeurs (pour certains métiers), l'administration ou la justice. Cela peut limiter l'accès à certains emplois." },
    { id:"db-3-065", t:3, lvl:"B1", q: "Peut-on faire appel d'un jugement si on n'est pas d'accord ?", o: ["Non, jamais", "Oui, on peut faire appel devant une juridiction supérieure", "Seulement si on est riche", "Seulement pour les crimes"], c: 1, e: "Oui, dans la plupart des cas, on peut faire appel d'un jugement devant une cour d'appel si on estime qu'il est injuste. L'affaire sera réexaminée par de nouveaux juges. C'est un droit fondamental qui garantit une justice équitable. Le délai d'appel est généralement de 10 jours." },

    // === SÉCURITÉ, POLICE ET CITOYENNETÉ (Questions 66-80) ===
    { id:"db-3-066", t:3, lvl:"B1", q: "Quel est le numéro d'urgence de la police en France ?", o: ["15", "17", "18", "112"], c: 1, e: "Le 17 est le numéro d'urgence de la police et de la gendarmerie en France. Il est gratuit et accessible 24h/24 pour signaler une agression, un vol, un accident, un trouble à l'ordre public ou toute situation nécessitant une intervention policière." },
    { id:"db-3-067", t:3, lvl:"B1", q: "Quel est le numéro d'urgence des pompiers en France ?", o: ["15", "17", "18", "112"], c: 2, e: "Le 18 est le numéro d'urgence des sapeurs-pompiers en France. Il est gratuit et disponible 24h/24 pour les incendies, accidents, secours aux personnes en danger, noyades, intoxications, et toute situation nécessitant une intervention des pompiers." },
    { id:"db-3-068", t:3, lvl:"B1", q: "Quel est le numéro d'urgence médicale (SAMU) en France ?", o: ["15", "17", "18", "114"], c: 0, e: "Le 15 est le numéro d'urgence médicale du SAMU (Service d'Aide Médicale Urgente) en France. Il est gratuit et accessible 24h/24 pour toute urgence médicale : malaise grave, accident, difficultés respiratoires, douleurs thoraciques, etc. Un médecin régulateur oriente les secours." },
    { id:"db-3-069", t:3, lvl:"B1", q: "Quel est le numéro d'urgence européen utilisable dans tous les pays de l'UE ?", o: ["911", "999", "112", "113"], c: 2, e: "Le 112 est le numéro d'urgence européen, gratuit et accessible dans tous les pays de l'Union européenne. En France, il permet de joindre tous les services d'urgence (police, pompiers, SAMU). Il fonctionne même sans réseau ou avec un téléphone bloqué." },
    { id:"db-3-070", t:3, lvl:"B2", q: "Quel est le numéro pour signaler un enfant en danger ?", o: ["17", "119", "115", "116"], c: 1, e: "Le 119 est le numéro national d'urgence pour l'enfance en danger. Il est gratuit, accessible 24h/24, et fonctionne de façon anonyme. Toute personne témoin ou victime de maltraitance sur mineur peut appeler ce numéro. Les professionnels évaluent la situation et alertent les autorités." },
    { id:"db-3-071", t:3, lvl:"B1", q: "Quel est le numéro d'urgence pour les personnes sourdes ou malentendantes ?", o: ["112", "114", "117", "119"], c: 1, e: "Le 114 est le numéro d'urgence par SMS accessible aux personnes sourdes, malentendantes ou ayant des difficultés à parler. Il permet de contacter tous les services d'urgence (police, pompiers, SAMU) par écrit 24h/24. C'est un service gratuit." },
    { id:"db-3-072", t:3, lvl:"B1", q: "Si vous êtes témoin d'un accident de la route, que devez-vous faire ?", o: ["Filmer et partir", "Sécuriser le lieu, appeler les secours (15 ou 18), porter assistance si possible", "Klaxonner et partir", "Ne rien faire"], c: 1, e: "Vous devez d'abord sécuriser les lieux (feux de détresse, triangle), appeler immédiatement les secours (15 ou 18 ou 112), et porter assistance aux victimes dans la mesure de vos capacités sans vous mettre en danger. Ne pas porter secours à une personne en péril est un délit (non-assistance à personne en danger)." },
    { id:"db-3-073", t:3, lvl:"B2", q: "Qu'est-ce que la non-assistance à personne en danger ?", o: ["Refuser de prêter de l'argent", "Ne pas porter secours à une personne en péril, c'est un délit", "Ne pas aider un ami à déménager", "Refuser de donner son numéro"], c: 1, e: "La non-assistance à personne en danger est un délit pénal : ne pas porter secours à une personne en péril grave et immédiat alors qu'on peut le faire sans risque pour soi. Ce délit est puni de 5 ans de prison et 75 000 euros d'amende. Cela inclut au minimum l'obligation d'appeler les secours." },
    { id:"db-3-074", t:3, lvl:"B1", q: "Pouvez-vous refuser de présenter vos papiers d'identité à la police ?", o: ["Oui, c'est une liberté", "Non, c'est obligatoire sous peine de sanction", "Oui, si on n'a rien fait", "Seulement la nuit"], c: 1, e: "Non, vous ne pouvez pas refuser un contrôle d'identité. La police et la gendarmerie peuvent contrôler votre identité dans certaines situations légales. Refuser de présenter vos papiers ou de décliner votre identité est une infraction qui peut entraîner une garde à vue." },
    { id:"db-3-075", t:3, lvl:"B1", q: "Qu'est-ce qu'une infraction routière ?", o: ["Un accident", "Une violation du code de la route punie par la loi", "Une panne de voiture", "Un embouteillage"], c: 1, e: "Une infraction routière est une violation du code de la route punie par la loi : excès de vitesse, conduite en état d'ivresse, téléphone au volant, non-respect des feux, etc. Les sanctions vont de l'amende au retrait de points, suspension de permis, voire prison pour les plus graves." },
    { id:"db-3-076", t:3, lvl:"B2", q: "Qu'est-ce que l'alcoolémie légale maximale au volant pour un conducteur expérimenté ?", o: ["0 gramme", "0,5 gramme par litre de sang", "1 gramme par litre", "2 grammes par litre"], c: 1, e: "Pour un conducteur expérimenté (plus de 3 ans de permis), le taux d'alcoolémie maximal autorisé est de 0,5 gramme par litre de sang (ou 0,25 mg par litre d'air expiré). Au-delà, c'est une infraction punie d'amende, retrait de points, suspension de permis et possiblement prison." },
    { id:"db-3-077", t:3, lvl:"B1", q: "Que risque-t-on en conduisant sans permis de conduire ?", o: ["Rien", "Jusqu'à 1 an de prison, 15 000 euros d'amende, confiscation du véhicule", "Juste un avertissement", "Une petite amende"], c: 1, e: "Conduire sans permis valide est un délit grave puni de 1 an de prison, 15 000 euros d'amende, confiscation possible du véhicule, et interdiction de passer le permis pendant plusieurs années. C'est une infraction très sévèrement sanctionnée car elle met en danger autrui." },
    { id:"db-3-078", t:3, lvl:"B1", q: "Que risque-t-on en conduisant sous l'emprise de stupéfiants ?", o: ["Rien si on roule bien", "Jusqu'à 2 ans de prison, 4 500 euros d'amende, retrait de points", "Juste une amende", "Rien la première fois"], c: 1, e: "Conduire après avoir consommé des stupéfiants (cannabis, cocaïne, etc.) est un délit puni de 2 ans de prison, 4 500 euros d'amende, retrait de 6 points, suspension de permis, et stage obligatoire. Si combiné à l'alcool, les peines peuvent aller jusqu'à 3 ans de prison." },
    { id:"db-3-079", t:3, lvl:"B2", q: "Qu'est-ce qu'un délit de fuite après un accident ?", o: ["Partir vite après un accident", "Quitter les lieux d'un accident sans s'identifier ni porter secours, un délit grave", "Conduire vite", "Fuir la police"], c: 1, e: "Le délit de fuite consiste à quitter les lieux d'un accident qu'on a provoqué sans s'arrêter, s'identifier et porter secours aux éventuelles victimes. C'est un délit très grave puni de 3 ans de prison, 75 000 euros d'amende, retrait de points et suspension de permis." },
    { id:"db-3-080", t:3, lvl:"B1", q: "Peut-on utiliser son téléphone en conduisant ?", o: ["Oui, librement", "Non, c'est interdit même avec kit mains libres", "Oui, avec oreillette", "Oui, aux feux rouges"], c: 1, e: "Non, l'usage du téléphone tenu en main est strictement interdit au volant, même à l'arrêt (feu rouge, embouteillage). Les oreillettes et kits mains libres sont aussi interdits. Sanction : 135 euros d'amende et 3 points retirés. Cela cause de nombreux accidents." },

    // === MISES EN SITUATION - DROITS ET DEVOIRS AVANCÉS (Questions 81-100) ===
    { id:"db-3-081", t:3, lvl:"B2", q: "Julie est témoin d'un vol à l'arraché dans le métro. Elle court après le voleur mais ne le rattrape pas. A-t-elle commis un délit de non-assistance ?", o: ["Oui, elle aurait dû le rattraper", "Non, elle a fait ce qu'elle pouvait sans danger pour elle", "Oui, elle doit payer une amende", "Oui, elle aurait dû se battre"], c: 1, e: "Non, Julie n'a pas commis de délit. La non-assistance à personne en danger suppose qu'on peut agir sans risque pour soi. Julie a appelé les secours et tenté d'aider dans la mesure de ses moyens. On ne peut pas exiger qu'elle se mette physiquement en danger." },
    { id:"db-3-082", t:3, lvl:"B1", q: "Marc est convoqué comme juré dans un procès criminel mais il a un voyage prévu. Peut-il refuser ?", o: ["Oui, librement", "Non, sauf motif grave justifié (maladie, impossibilité majeure)", "Oui, s'il a payé son voyage", "Oui, s'il envoie un remplaçant"], c: 1, e: "Non, Marc ne peut refuser que pour un motif grave et légitime accepté par le tribunal (maladie grave, obligation professionnelle majeure). Un simple voyage de loisirs ne suffit pas. Être juré est un devoir civique important, et refuser sans raison valable peut entraîner une amende." },
    { id:"db-3-083", t:3, lvl:"B2", q: "Sophie reçoit son avis d'impôts avec une erreur évidente en sa faveur (500 euros de trop remboursés). Doit-elle le signaler ?", o: ["Non, c'est de la chance", "Oui, elle doit signaler l'erreur, sinon c'est une fraude", "Non, si l'administration se trompe c'est leur problème", "Seulement si on la contacte"], c: 1, e: "Oui, Sophie doit obligatoirement signaler l'erreur aux impôts. Profiter sciemment d'une erreur administrative en sa faveur sans la signaler constitue une fraude fiscale. L'administration finira par découvrir l'erreur et Sophie devra rembourser avec des pénalités et risque des poursuites." },
    { id:"db-3-084", t:3, lvl:"B1", q: "Lucas trouve un smartphone dans un parc. Peut-il le garder et l'utiliser ?", o: ["Oui, c'est une trouvaille", "Non, il doit le remettre aux objets trouvés", "Oui, après 24 heures", "Oui, si personne ne le réclame tout de suite"], c: 1, e: "Non, Lucas doit remettre le smartphone aux objets trouvés (mairie, police). Garder un objet trouvé est un délit d'appropriation frauduleuse (recel). Si personne ne le réclame après un délai légal (généralement 1 an), Lucas pourra alors le récupérer légalement." },
    { id:"db-3-085", t:3, lvl:"B2", q: "Léa, infirmière, voit sur le dossier médical d'un patient célèbre qu'il a une maladie grave. Peut-elle en parler à sa famille ?", o: ["Oui, c'est grave donc elle doit prévenir", "Non, jamais, c'est une violation grave du secret médical", "Oui, uniquement à sa famille proche", "Oui, si c'est anonyme"], c: 1, e: "Non, jamais. Léa est tenue au secret médical absolu, même envers sa propre famille. Révéler des informations médicales sur un patient, même célèbre, est un délit pénal très grave puni de prison et d'interdiction d'exercer. Le secret médical ne souffre aucune exception hors cas légaux." },
    { id:"db-3-086", t:3, lvl:"B1", q: "Thomas, 16 ans, veut se faire recenser à la mairie. A-t-il raison ?", o: ["Non, c'est trop tôt", "Oui, c'est obligatoire dès 16 ans", "Non, il faut attendre 18 ans", "Oui, mais seulement s'il veut"], c: 1, e: "Oui, Thomas a raison. Tous les jeunes Français doivent se faire recenser à la mairie dans les 3 mois qui suivent leur 16e anniversaire. C'est obligatoire et permet ensuite de participer à la Journée Défense et Citoyenneté et d'être inscrit sur les listes électorales à 18 ans." },
    { id:"db-3-087", t:3, lvl:"B2", q: "Karim a été licencié abusivement. Combien de temps a-t-il pour saisir le conseil de prud'hommes ?", o: ["1 mois", "1 an", "5 ans", "10 ans"], c: 1, e: "Karim dispose d'un délai de 1 an (12 mois) à partir de la notification du licenciement pour saisir le conseil de prud'hommes et contester son licenciement. Passé ce délai, son action est prescrite et il ne pourra plus agir en justice. Il est important de ne pas tarder." },
    { id:"db-3-088", t:3, lvl:"B1", q: "Julie est arrêtée pour vol. Elle n'a pas d'argent pour un avocat. Que se passe-t-il ?", o: ["Elle n'aura pas d'avocat", "Un avocat lui sera désigné gratuitement (commis d'office)", "Elle doit emprunter de l'argent", "Elle ira en prison sans défense"], c: 1, e: "Un avocat lui sera automatiquement désigné gratuitement (avocat commis d'office) pour la garde à vue et l'audience. Si elle est jugée, elle pourra demander l'aide juridictionnelle pour avoir un avocat gratuitement selon ses revenus. Le droit à la défense est garanti pour tous." },
    { id:"db-3-089", t:3, lvl:"B2", q: "David achète une voiture d'occasion et découvre 2 mois après qu'elle a un grave défaut caché. Peut-il agir ?", o: ["Non, c'est trop tard", "Oui, il peut demander l'annulation de la vente ou une réduction du prix", "Non, c'est son problème", "Seulement s'il a une assurance"], c: 1, e: "Oui, David peut agir en justice contre le vendeur pour vice caché. Si le défaut était présent lors de la vente mais non visible, et qu'il rend la voiture impropre à l'usage prévu, David peut demander l'annulation de la vente et le remboursement, ou une réduction du prix. Délai : 2 ans." },
    { id:"db-3-090", t:3, lvl:"B1", q: "Marie reçoit un PV de stationnement de 35 euros. Doit-elle absolument le payer ?", o: ["Non, elle peut l'ignorer", "Oui, sous peine de majoration et poursuites", "Non, si elle n'est pas d'accord", "Seulement si la police revient"], c: 1, e: "Oui, Marie doit payer l'amende dans les délais indiqués. Si elle ne paie pas, l'amende sera majorée (jusqu'à 180 euros pour du stationnement), puis des poursuites peuvent être engagées. Si elle conteste l'amende, elle doit suivre la procédure de contestation, mais ne peut pas simplement l'ignorer." },
    { id:"db-3-091", t:3, lvl:"B2", q: "Paul conduit à 160 km/h sur une autoroute limitée à 130 km/h. Que risque-t-il ?", o: ["Rien, c'est courant", "Amende de 135 euros, retrait de 2 points, possible suspension de permis", "Juste un avertissement", "Prison immédiate"], c: 1, e: "Paul risque une amende forfaitaire de 135 euros, un retrait de 2 points sur son permis, et une possible suspension de permis. Pour un excès supérieur à 50 km/h, ce serait encore plus grave : délit pénal avec amende de 1500 euros, 6 points, suspension et confiscation possible du véhicule." },
    { id:"db-3-092", t:3, lvl:"B1", q: "Rachid voit un incendie dans un immeuble. Il appelle les pompiers (18). A-t-il bien fait ?", o: ["Non, ce n'est pas son problème", "Oui, c'est un geste citoyen et une obligation morale", "Non, il aurait dû essayer d'éteindre seul", "Non, c'est le travail des voisins"], c: 1, e: "Oui, Rachid a très bien fait. Appeler les secours face à un danger (incendie, accident, personne en danger) est un devoir citoyen et une obligation légale. Ne pas le faire pourrait constituer une non-assistance à personne en danger. Son geste peut sauver des vies." },
    { id:"db-3-093", t:3, lvl:"B2", q: "Lucie découvre que son collègue copie des fichiers confidentiels de l'entreprise pour les vendre. Doit-elle le signaler ?", o: ["Non, ce n'est pas son problème", "Oui, elle devrait alerter sa hiérarchie ou la justice", "Non, sinon elle sera une balance", "Non, sauf si on lui demande"], c: 1, e: "Oui, Lucie devrait signaler ces faits à sa hiérarchie ou, si nécessaire, à la justice. Le vol de données confidentielles est un délit grave qui peut nuire gravement à l'entreprise et à ses salariés. Ne pas signaler pourrait même rendre Lucie complice si elle en a connaissance." },
    { id:"db-3-094", t:3, lvl:"B1", q: "Emma, 17 ans, veut ouvrir un compte bancaire seule. Peut-elle le faire ?", o: ["Oui, librement", "Non, elle a besoin de l'autorisation de ses parents (mineure)", "Oui, si elle travaille", "Non, il faut attendre 21 ans"], c: 1, e: "Non, Emma est mineure (moins de 18 ans) et a besoin de l'autorisation de ses représentants légaux (parents ou tuteur) pour ouvrir un compte bancaire. Les mineurs peuvent avoir un compte, mais les parents doivent autoriser l'ouverture et généralement cosigner." }, 
    { id:"db-3-095", t:3, lvl:"B2", q: "Antoine est condamné à 6 mois de prison avec sursis. Qu'est-ce que cela signifie concrètement ?", o: ["Il va en prison 6 mois", "Il ne va pas en prison sauf s'il récidive pendant le délai d'épreuve", "Il paie une amende", "Il est innocent"], c: 1, e: "Antoine ne va pas en prison immédiatement. La peine de 6 mois est 'suspendue' : elle ne sera appliquée que s'il commet une nouvelle infraction pendant le délai d'épreuve fixé par le juge (généralement 5 ans). S'il ne récidive pas, il n'ira jamais en prison pour cette condamnation." }, 
    { id:"db-3-096", t:3, lvl:"B1", q: "Emma veut contester une décision administrative qui lui refuse une allocation. Où peut-elle s'adresser ?", o: ["Nulle part, c'est impossible", "Au Défenseur des droits et/ou au tribunal administratif", "À la police", "À son député seulement"], c: 1, e: "Emma peut saisir le Défenseur des droits (autorité indépendante, gratuit) qui peut l'aider à résoudre le litige avec l'administration. Elle peut aussi former un recours devant le tribunal administratif pour contester la décision. Elle peut demander l'aide juridictionnelle si elle a peu de ressources." }, 
    { id:"db-3-097", t:3, lvl:"B2", q: "Nicolas conduit avec 0,7 gramme d'alcool dans le sang (limite : 0,5g). Que risque-t-il ?", o: ["Rien, c'est juste au-dessus", "Amende de 135 euros, retrait de 6 points, suspension de permis possible", "Juste un avertissement", "Retrait définitif du permis"], c: 1, e: "Nicolas commet une contravention de 4e classe. Il risque une amende forfaitaire de 135 euros (minorée à 90€ si payée rapidement), un retrait de 6 points sur son permis, et une suspension de permis jusqu'à 3 ans. Son véhicule peut aussi être immobilisé. Entre 0,5 et 0,8g, c'est une contravention ; au-delà de 0,8g, c'est un délit pénal." }, 
    { id:"db-3-098", t:3, lvl:"B1", q: "Lucas, 15 ans, veut travailler pendant les vacances d'été. Peut-il le faire ?", o: ["Non, interdit avant 18 ans", "Oui, à partir de 14 ans pendant les vacances scolaires avec autorisation", "Oui, librement", "Non, il faut attendre 16 ans"], c: 1, e: "Oui, Lucas peut travailler à partir de 14 ans pendant les vacances scolaires (au moins la moitié des vacances doit rester libre), avec l'autorisation de ses parents et de l'inspection du travail. Le travail doit être adapté à son âge (travaux légers) et sa rémunération est encadrée (minimum 80% du SMIC)." }, 
    { id:"db-3-099", t:3, lvl:"B2", q: "Samira est témoin d'un accident mais elle est pressée. Doit-elle quand même s'arrêter ?", o: ["Non, si elle est pressée", "Oui, elle doit au minimum alerter les secours (15/18), sinon c'est un délit", "Non, d'autres le feront", "Seulement si elle connaît les victimes"], c: 1, e: "Oui, Samira a l'obligation légale de porter assistance ou au minimum d'alerter les secours. Ne pas le faire constitue un délit de non-assistance à personne en danger, puni de 5 ans de prison et 75 000 euros d'amende. Être pressé ne dispense pas de cette obligation citoyenne et légale." },
    { id:"db-3-100", t:3, lvl:"B1", q: "Pierre trouve 20 euros par terre dans la rue. Peut-il les garder ?", o: ["Oui, c'est peu d'argent", "Techniquement non, il devrait les rapporter aux objets trouvés", "Oui, toujours", "Non, c'est illégal"], c: 1, e: "Techniquement, même une somme modeste trouvée devrait être rapportée aux objets trouvés. En pratique, pour de petites sommes sans moyen d'identifier le propriétaire, il n'y a généralement pas de poursuites. Mais légalement, garder un bien trouvé sans chercher à retrouver son propriétaire reste une appropriation frauduleuse." },

    // === QUESTIONS COMPLÉMENTAIRES - TEXTES FONDAMENTAUX ET DROITS (Questions 101-112) ===
    { id:"db-3-101", t:3, lvl:"B1", q: "Qu'est-ce que la Constitution française ?", o: ["Un simple règlement", "Le texte fondamental qui organise les pouvoirs et garantit les droits", "Une loi comme les autres", "Un traité international"], c: 1, e: "La Constitution est le texte juridique le plus important de la République. Elle définit l'organisation des pouvoirs (Président, Gouvernement, Parlement, Justice) et garantit les droits fondamentaux des citoyens. Toutes les lois doivent la respecter." },
    { id:"db-3-102", t:3, lvl:"B2", q: "Quel texte est le plus difficile à modifier en France ?", o: ["Une loi ordinaire", "La Constitution", "Un décret", "Un arrêté municipal"], c: 1, e: "La Constitution est le texte le plus difficile à modifier. Sa révision nécessite soit un vote des deux chambres du Parlement puis un référendum, soit un vote du Congrès (Parlement réuni) à la majorité des 3/5. Cette rigidité protège les droits fondamentaux." },
    { id:"db-3-103", t:3, lvl:"B1", q: "Que contient la Constitution française ?", o: ["Uniquement les impôts à payer", "L'organisation des pouvoirs et les droits fondamentaux des citoyens", "Les règles de conduite automobile", "Les programmes scolaires"], c: 1, e: "La Constitution française contient l'organisation des pouvoirs publics (Président, Parlement, Gouvernement, Justice), les principes fondamentaux de la République (liberté, égalité, laïcité), et les droits et libertés des citoyens via le Préambule et la Déclaration de 1789." },
    { id:"db-3-104", t:3, lvl:"B2", q: "À quelle liberté fondamentale la PMA (procréation médicalement assistée) fait-elle référence ?", o: ["La liberté d'expression", "La liberté de disposer de son corps et le droit de fonder une famille", "La liberté de circulation", "La liberté du commerce"], c: 1, e: "La PMA relève de la liberté de disposer de son corps et du droit de fonder une famille. Depuis 2021, elle est ouverte à toutes les femmes en France, qu'elles soient en couple hétérosexuel, homosexuel ou célibataires. C'est une avancée pour l'égalité des droits." },
    { id:"db-3-105", t:3, lvl:"B1", q: "Que signifie PMA ?", o: ["Protection des Mineurs Abandonnés", "Procréation Médicalement Assistée", "Programme Municipal d'Aide", "Plan de Mobilité Alternative"], c: 1, e: "PMA signifie Procréation Médicalement Assistée. C'est l'ensemble des techniques médicales permettant d'aider les personnes à avoir un enfant quand la conception naturelle n'est pas possible. Depuis 2021, la PMA est ouverte à toutes les femmes en France." },
    { id:"db-3-106", t:3, lvl:"B1", q: "Que garantit la liberté de la presse en France ?", o: ["Le droit de mentir", "Le droit d'informer librement sans censure préalable de l'État", "Le droit d'insulter les gens", "Le droit de diffuser de fausses nouvelles"], c: 1, e: "La liberté de la presse garantit le droit d'informer et d'être informé sans censure préalable de l'État. Les journalistes peuvent critiquer le gouvernement, enquêter librement. Cette liberté est encadrée par les lois sur la diffamation, la vie privée et les fausses informations." },
    { id:"db-3-107", t:3, lvl:"B2", q: "Que prévoit la Charte de l'environnement de 2004 ?", o: ["Uniquement la protection des animaux", "Le droit de vivre dans un environnement sain et le devoir de le préserver", "L'interdiction des voitures", "La création de parcs naturels"], c: 1, e: "La Charte de l'environnement, intégrée à la Constitution, reconnaît à chacun le droit de vivre dans un environnement équilibré et respectueux de la santé. Elle impose aussi un devoir de préservation de l'environnement et le principe de précaution face aux risques écologiques." },
    { id:"db-3-108", t:3, lvl:"B1", q: "Que signifie la dignité humaine ?", o: ["Être riche et respecté", "Le respect absolu dû à toute personne humaine, quelles que soient ses caractéristiques", "Avoir un titre de noblesse", "Être célèbre"], c: 1, e: "La dignité humaine signifie que chaque être humain a une valeur absolue qui doit être respectée. Personne ne peut être traité de manière dégradante, humiliante ou inhumaine. Cette notion fonde l'interdiction de la torture, de l'esclavage et des traitements inhumains." },
    { id:"db-3-109", t:3, lvl:"B2", q: "Au nom de quoi l'État peut-il restreindre certains droits et libertés ?", o: ["Pour son propre intérêt", "Pour protéger l'ordre public, la sécurité, la santé publique ou les droits d'autrui", "Pour économiser de l'argent", "Pour aucune raison, les droits sont absolus"], c: 1, e: "L'État peut limiter certains droits uniquement pour protéger l'ordre public, la sécurité nationale, la santé publique ou les droits des autres personnes. Ces restrictions doivent être proportionnées, nécessaires et prévues par la loi. Les droits fondamentaux ne sont pas absolus." },
    { id:"db-3-110", t:3, lvl:"B1", q: "Une femme majeure a-t-elle le droit de voter aux élections en France ?", o: ["Non, seulement les hommes", "Oui, depuis 1944 les femmes ont le droit de vote", "Seulement aux élections locales", "Seulement si elle est mariée"], c: 1, e: "Oui, les femmes ont le droit de vote en France depuis 1944. C'est un droit fondamental acquis après de longues luttes. Toute citoyenne française majeure, inscrite sur les listes électorales et jouissant de ses droits civiques, peut voter à toutes les élections." },
    { id:"db-3-111", t:3, lvl:"B2", q: "Quelle phrase célèbre est inscrite dans la Déclaration des Droits de l'Homme de 1789 ?", o: ["L'État c'est moi", "Les hommes naissent et demeurent libres et égaux en droits", "Liberté, Égalité, Fraternité", "Vive la République"], c: 1, e: "L'article 1er de la Déclaration de 1789 proclame : 'Les hommes naissent et demeurent libres et égaux en droits'. Cette phrase fondatrice affirme l'égalité naturelle de tous les êtres humains, principe au cœur de la République française." },
    { id:"db-3-112", t:3, lvl:"B1", q: "Que signifie le droit de manifester ?", o: ["Le droit de casser des vitrines", "Le droit de se rassembler pacifiquement pour exprimer des revendications", "Le droit de bloquer les hôpitaux", "Le droit d'insulter la police"], c: 1, e: "Le droit de manifester permet aux citoyens de se rassembler pacifiquement dans l'espace public pour exprimer des opinions ou des revendications. Ce droit fondamental doit s'exercer dans le respect de l'ordre public : les manifestations doivent généralement être déclarées en préfecture." },

    // === QUESTIONS COMPLÉMENTAIRES - OBLIGATIONS ET ENVIRONNEMENT (Questions 113-122) ===
    { id:"db-3-113", t:3, lvl:"B1", q: "Que doit-on faire face aux ordres légitimes des policiers ou gendarmes ?", o: ["Les ignorer", "Obéir, dans le respect de ses droits fondamentaux", "Fuir", "Discuter longuement"], c: 1, e: "Face aux ordres légitimes des forces de l'ordre, on doit obéir (contrôle d'identité, injonction de circuler). Refuser ou résister peut constituer un délit (outrage, rébellion). Cependant, on conserve ses droits fondamentaux : droit au silence, droit à un avocat, droit de contester ensuite." },
    { id:"db-3-114", t:3, lvl:"B2", q: "Concernant l'utilisation des réseaux sociaux, quelle règle s'applique ?", o: ["On peut tout dire car c'est virtuel", "Les mêmes lois qu'ailleurs s'appliquent : pas d'injures, de harcèlement ni de haine", "Aucune loi ne s'applique sur internet", "Seuls les mineurs sont protégés"], c: 1, e: "Les mêmes lois s'appliquent sur les réseaux sociaux que dans la vie réelle. Les injures, la diffamation, le harcèlement, l'incitation à la haine, les menaces sont des délits punis par la loi, même en ligne. L'anonymat n'empêche pas les poursuites judiciaires." },
    { id:"db-3-115", t:3, lvl:"B1", q: "Pourquoi doit-on trier ses déchets ?", o: ["C'est facultatif", "Pour permettre le recyclage et protéger l'environnement", "Pour faire plaisir au maire", "Pour payer moins d'impôts"], c: 1, e: "Trier ses déchets est une obligation citoyenne qui permet le recyclage des matériaux (plastique, verre, papier, métal) et réduit la pollution. C'est un geste essentiel pour protéger l'environnement et préserver les ressources pour les générations futures." },
    { id:"db-3-116", t:3, lvl:"B1", q: "Où peut-on déposer un gros appareil électroménager usagé (réfrigérateur, machine à laver) ?", o: ["Dans la rue", "En déchetterie ou lors d'un achat (reprise par le vendeur)", "Dans la poubelle normale", "Dans la nature"], c: 1, e: "Les gros appareils électroménagers doivent être déposés en déchetterie ou repris gratuitement par le vendeur lors de l'achat d'un appareil équivalent. Les jeter dans la rue ou la nature est une infraction punie d'amende. Ces appareils contiennent des substances polluantes à traiter spécialement." },
    { id:"db-3-117", t:3, lvl:"B2", q: "Qu'est-ce que la traite des êtres humains ?", o: ["Le commerce légal", "L'exploitation de personnes par la contrainte à des fins de travail forcé ou sexuel, un crime", "Un type de transport", "Une taxe sur les voyages"], c: 1, e: "La traite des êtres humains est un crime grave consistant à recruter, transporter ou héberger des personnes par la menace ou la contrainte pour les exploiter (travail forcé, exploitation sexuelle, mendicité forcée). C'est une forme moderne d'esclavage, sévèrement punie." },
    { id:"db-3-118", t:3, lvl:"B1", q: "Quelle est l'attitude à avoir lorsqu'on est témoin de violences ?", o: ["Ne rien faire, ce n'est pas notre affaire", "Alerter les secours (17) et si possible sécuriser la victime sans se mettre en danger", "Filmer pour les réseaux sociaux", "Partir rapidement"], c: 1, e: "Être témoin de violences impose d'agir : appeler les secours (17 pour la police), sécuriser la victime si possible sans se mettre en danger, témoigner ensuite. Ne rien faire peut constituer une non-assistance à personne en danger, un délit puni par la loi." },
    { id:"db-3-119", t:3, lvl:"B2", q: "Quel exemple illustre une limitation de liberté pour protéger l'intérêt général ?", o: ["Interdire de voter", "L'obligation de porter la ceinture de sécurité ou les limitations de vitesse", "Interdire de travailler", "Interdire de se marier"], c: 1, e: "L'obligation de porter la ceinture de sécurité ou les limitations de vitesse sont des exemples de restrictions de liberté justifiées par l'intérêt général : protéger la vie des usagers de la route. Ces contraintes, proportionnées, sauvent des milliers de vies chaque année." },
    { id:"db-3-120", t:3, lvl:"B1", q: "Quelle proposition représente un exemple de délit ?", o: ["Un stationnement interdit", "Un vol simple, des violences légères, une conduite en état d'ivresse", "Un meurtre", "Traverser au feu rouge"], c: 1, e: "Un délit est une infraction de gravité moyenne, jugée par le tribunal correctionnel. Exemples : vol simple, violences sans incapacité grave, conduite en état d'ivresse, discrimination. Les délits sont punis de peines allant jusqu'à 10 ans de prison. Le meurtre est un crime, plus grave." },
    { id:"db-3-121", t:3, lvl:"B2", q: "Quelle proposition représente un exemple de crime ?", o: ["Un excès de vitesse", "Un meurtre, un viol, un acte terroriste", "Un vol à l'étalage", "Une injure publique"], c: 1, e: "Un crime est l'infraction la plus grave, jugée par la cour d'assises avec un jury populaire. Exemples : meurtre, assassinat, viol, acte terroriste, trafic de drogue à grande échelle. Les crimes sont punis de peines allant de 15 ans de prison à la perpétuité." },
    { id:"db-3-122", t:3, lvl:"B1", q: "Qui veille au maintien de l'ordre public en France ?", o: ["L'armée uniquement", "La police nationale et la gendarmerie nationale", "Les citoyens eux-mêmes", "Les juges"], c: 1, e: "La police nationale (dans les villes) et la gendarmerie nationale (en zone rurale et périurbaine) veillent au maintien de l'ordre public. Elles assurent la sécurité des personnes et des biens, préviennent les infractions et interpellent les auteurs de délits et crimes." },

    // === QUESTIONS COMPLÉMENTAIRES - SITUATIONS PRATIQUES (Questions 123-130) ===
    { id:"db-3-123", t:3, lvl:"B1", q: "Que doit faire une personne victime de violences ?", o: ["Se taire et accepter", "Porter plainte à la police ou gendarmerie et consulter un médecin", "Attendre que ça passe", "En parler uniquement à ses amis"], c: 1, e: "Une victime de violences doit porter plainte à la police ou la gendarmerie (c'est gratuit et possible partout). Elle devrait aussi consulter un médecin pour faire constater ses blessures (certificat médical). Des associations d'aide aux victimes peuvent l'accompagner dans ses démarches." },
    { id:"db-3-124", t:3, lvl:"B2", q: "Pour quel motif peut-on légalement limiter la liberté d'expression ?", o: ["Pour empêcher les critiques du gouvernement", "Pour protéger contre les propos diffamatoires, haineux ou mettant en danger autrui", "Pour interdire les opinions minoritaires", "Pour aucun motif, elle est absolue"], c: 1, e: "La liberté d'expression peut être limitée pour protéger d'autres droits : interdiction de la diffamation (accusations mensongères), des injures, de l'incitation à la haine raciale ou religieuse, de l'apologie du terrorisme, des atteintes à la vie privée. Ces limites protègent la dignité d'autrui." },
    { id:"db-3-125", t:3, lvl:"B1", q: "Jeter un mégot de cigarette par terre est-il autorisé ?", o: ["Oui, c'est petit", "Non, c'est interdit et puni d'une amende de 135 euros", "Oui, si on est pressé", "Seulement dans les parcs"], c: 1, e: "Non, jeter un mégot par terre est une infraction punie d'une amende de 135 euros. Un mégot pollue jusqu'à 500 litres d'eau et met 12 ans à se dégrader. C'est un geste incivique qui nuit à l'environnement et à la propreté des espaces publics." },
    { id:"db-3-126", t:3, lvl:"B2", q: "Quelle obligation concerne toutes les personnes résidant en France, quelle que soit leur nationalité ?", o: ["Voter aux élections", "Respecter les lois françaises", "Servir dans l'armée", "Parler uniquement français"], c: 1, e: "Toute personne résidant en France, quelle que soit sa nationalité, doit respecter les lois françaises. C'est le principe fondamental 'nul n'est censé ignorer la loi'. Les autres obligations (vote, service national) sont réservées aux citoyens français." },
    { id:"db-3-127", t:3, lvl:"B1", q: "Déposer des encombrants sur le trottoir sans autorisation est-il légal ?", o: ["Oui, la mairie les enlève", "Non, c'est interdit et puni d'une amende pouvant aller jusqu'à 1 500 euros", "Oui, la nuit seulement", "Oui, si on prévient les voisins"], c: 1, e: "Non, déposer des encombrants sur le trottoir sans autorisation est interdit. Il faut les déposer en déchetterie ou attendre le jour de collecte prévu par la mairie. Déposer des déchets sauvages peut être puni d'une amende allant jusqu'à 1 500 euros, voire 75 000 euros en cas de dépôt important." },
    { id:"db-3-128", t:3, lvl:"B1", q: "Comment peut-on réduire ses déchets au quotidien ?", o: ["En les jetant n'importe où", "En évitant le suremballage, en compostant et en réutilisant", "En brûlant ses déchets", "En les cachant"], c: 1, e: "On peut réduire ses déchets en évitant les produits suremballés, en utilisant des sacs réutilisables, en compostant les déchets organiques, en donnant ou vendant les objets encore utilisables, et en choisissant des produits durables plutôt que jetables. Chaque geste compte." },
    { id:"db-3-129", t:3, lvl:"B2", q: "Qu'est-ce que le droit de grève et quelles sont ses limites ?", o: ["Le droit de ne jamais travailler", "Le droit d'arrêter le travail pour des revendications professionnelles, dans le respect de la loi", "Le droit de détruire l'entreprise", "Un droit réservé aux fonctionnaires"], c: 1, e: "Le droit de grève permet aux salariés de cesser collectivement le travail pour défendre des revendications professionnelles. C'est un droit constitutionnel. Ses limites : pas de violence, pas de blocage des non-grévistes, service minimum dans certains secteurs publics (hôpitaux, transports)." },
    { id:"db-3-130", t:3, lvl:"B1", q: "Faut-il réduire ses déchets en France ?", o: ["Non, ce n'est pas important", "Oui, c'est un devoir citoyen et environnemental", "Seulement si on est écologiste", "Seulement en ville"], c: 1, e: "Oui, réduire ses déchets est un devoir citoyen inscrit dans la Charte de l'environnement. Chaque Français produit environ 500 kg de déchets par an. Réduire, réutiliser et recycler sont essentiels pour préserver les ressources naturelles et lutter contre la pollution." },

    // === QUESTIONS COMPLÉMENTAIRES - COUVERTURE OFFICIELLE (Thème 3) ===
    { id:"db-3-131", t:3, lvl:"B1", q: "Que permet la citoyenneté française ?", o: ["Uniquement de vivre en France", "De voter, d'accéder à la fonction publique et de bénéficier de la protection de l'État", "Seulement de travailler en France", "De ne pas payer d'impôts"], c: 1, e: "La citoyenneté française confère des droits importants : le droit de vote à toutes les élections, l'accès aux emplois de la fonction publique, la protection consulaire à l'étranger et le droit de transmettre la nationalité à ses enfants. Elle implique aussi des devoirs comme respecter la loi et contribuer aux charges publiques." },
    { id:"db-3-132", t:3, lvl:"B2", q: "Le recours à l'interruption volontaire de grossesse (IVG) est-il autorisé en France ?", o: ["Non, c'est interdit", "Oui, c'est un droit garanti par la Constitution depuis 2024", "Seulement en cas de danger pour la mère", "Seulement avec l'accord du conjoint"], c: 1, e: "Oui, l'IVG (interruption volontaire de grossesse) est un droit en France, inscrit dans la Constitution depuis mars 2024. Toute femme peut y recourir librement, sans avoir à justifier sa décision. L'IVG est possible jusqu'à 14 semaines de grossesse et est prise en charge à 100 % par l'Assurance Maladie." },
    { id:"db-3-133", t:3, lvl:"B1", q: "Concernant le droit de se marier en France, quelle affirmation est correcte ?", o: ["Seul le mariage religieux est reconnu", "Toute personne majeure peut se marier librement, y compris avec une personne du même sexe", "Il faut l'autorisation des parents même après 18 ans", "Le mariage n'est autorisé qu'entre personnes de nationalité française"], c: 1, e: "En France, toute personne majeure peut se marier librement, sans distinction de sexe, d'origine ou de religion. Le mariage entre personnes de même sexe est légal depuis 2013. Seul le mariage civil célébré en mairie est reconnu par l'État. Le mariage forcé est un crime." },
    { id:"db-3-134", t:3, lvl:"B2", q: "Comment s'appelle le contrat signé par les personnes étrangères arrivant en France qui énonce les droits et devoirs de la vie en France ?", o: ["Le contrat de travail", "Le contrat d'intégration républicaine (CIR)", "Le contrat de citoyenneté", "Le contrat social"], c: 1, e: "Le contrat d'intégration républicaine (CIR) est signé par les personnes étrangères admises pour la première fois au séjour en France. Il engage le signataire à respecter les valeurs de la République et à suivre des formations (civique et linguistique). En retour, l'État accompagne le parcours d'intégration." },
    { id:"db-3-135", t:3, lvl:"B1", q: "Quel est un exemple d'assistance à personne en danger ?", o: ["Filmer un accident avec son téléphone", "Appeler les secours (15, 18 ou 112) en voyant une personne blessée", "Partir rapidement pour ne pas être impliqué", "Attendre que quelqu'un d'autre intervienne"], c: 1, e: "Appeler les secours lorsqu'on voit une personne en danger est l'exemple le plus simple d'assistance à personne en danger. Nul n'est obligé de se mettre en danger, mais chacun doit au minimum alerter les secours. Ne rien faire est un délit de non-assistance à personne en danger, puni de 5 ans de prison." },
    { id:"db-3-136", t:3, lvl:"B1", q: "Quelle est la différence entre la police nationale et la gendarmerie nationale ?", o: ["Il n'y a aucune différence", "La police intervient en ville, la gendarmerie en zone rurale et périurbaine", "La gendarmerie ne s'occupe que des routes", "La police est civile, la gendarmerie n'existe plus"], c: 1, e: "La police nationale intervient principalement dans les zones urbaines (villes) tandis que la gendarmerie nationale couvre les zones rurales et périurbaines. La gendarmerie est une force militaire placée sous l'autorité du ministère de l'Intérieur. Les deux forces ont les mêmes missions : sécurité, ordre public et respect de la loi." },
    
    // === GRANDES PÉRIODES HISTORIQUES (Questions 1-15) ===
    { id:"db-4-001", t:4, lvl:"B1", q: "En quelle année a débuté la Révolution française ?", o: ["1789", "1792", "1804", "1815"], c: 0, e: "La Révolution française a débuté en 1789 avec la prise de la Bastille le 14 juillet. Cette révolution a mis fin à la monarchie absolue et établi les principes de Liberté, Égalité et Fraternité qui fondent la République française actuelle." },
    { id:"db-4-002", t:4, lvl:"B1", q: "Quel événement est commémoré le 14 juillet ?", o: ["La victoire de 1918", "La prise de la Bastille en 1789 et la Fête de la Fédération en 1790", "L'abolition de l'esclavage", "La fin de la monarchie"], c: 1, e: "Le 14 juillet commémore deux événements : la prise de la Bastille le 14 juillet 1789, symbole de la fin de l'absolutisme royal, et la Fête de la Fédération du 14 juillet 1790, célébrant l'unité nationale. C'est la fête nationale française depuis 1880." },
    { id:"db-4-003", t:4, lvl:"B1", q: "En quelle année a été proclamée la Première République française ?", o: ["1789", "1792", "1804", "1848"], c: 1, e: "La Première République française a été proclamée en 1792, après l'abolition de la monarchie. C'est le début du régime républicain en France, marquant la fin définitive du pouvoir royal et l'avènement de la souveraineté populaire." },
    { id:"db-4-004", t:4, lvl:"B1", q: "Qui était Napoléon Bonaparte ?", o: ["Un roi de France", "Un empereur français qui a créé le Code civil", "Un philosophe", "Un révolutionnaire"], c: 1, e: "Napoléon Bonaparte (1769-1821) a dirigé la France en tant que Premier Consul puis Empereur de 1799 à 1815. Il a modernisé l'État français en créant notamment le Code civil en 1804, qui régit encore aujourd'hui les relations entre citoyens. Il a mené de nombreuses guerres en Europe." },
    { id:"db-4-005", t:4, lvl:"B1", q: "Qu'est-ce que le Code civil créé par Napoléon ?", o: ["Un code secret", "Un ensemble de lois régissant les relations entre les personnes", "Un code militaire", "Un système de communication"], c: 1, e: "Le Code civil, créé en 1804 sous Napoléon, est un ensemble de lois qui régit les relations entre les personnes en matière de famille, de propriété, de contrats et d'héritage. C'est l'un des fondements du droit français moderne et il a inspiré de nombreux pays." },
    { id:"db-4-006", t:4, lvl:"B1", q: "En quelle année l'esclavage a-t-il été définitivement aboli en France ?", o: ["1789", "1848", "1905", "1945"], c: 1, e: "L'esclavage a été définitivement aboli en France en 1848 sous la Seconde République, grâce notamment à l'action de Victor Schœlcher. Cette abolition met fin à une pratique inhumaine qui avait perduré dans les colonies françaises malgré une première abolition en 1794." },
    { id:"db-4-007", t:4, lvl:"B2", q: "Qui était Victor Schœlcher ?", o: ["Un esclavagiste", "Un homme politique ayant œuvré pour l'abolition de l'esclavage en 1848", "Un général", "Un roi"], c: 1, e: "Victor Schœlcher (1804-1893) était un homme politique et journaliste français qui a lutté toute sa vie contre l'esclavage. En tant que sous-secrétaire d'État aux Colonies en 1848, il a rédigé le décret d'abolition définitive de l'esclavage dans les colonies françaises." },
    { id:"db-4-008", t:4, lvl:"B1", q: "Qui était Jules Ferry et qu'a-t-il fait pour l'éducation ?", o: ["Un écrivain", "Le ministre qui a rendu l'école gratuite, laïque et obligatoire dans les années 1880", "Un général", "Un médecin"], c: 1, e: "Jules Ferry était un homme politique français, ministre de l'Instruction publique dans les années 1880. Il a fait voter les lois rendant l'école primaire publique gratuite, laïque et obligatoire. Ces réformes fondamentales ont permis l'accès de tous les enfants à l'éducation." },
    { id:"db-4-009", t:4, lvl:"B1", q: "Quand a eu lieu la Première Guerre mondiale ?", o: ["1870-1871", "1914-1918", "1939-1945", "1950-1953"], c: 1, e: "La Première Guerre mondiale s'est déroulée de 1914 à 1918. Ce conflit mondial a opposé principalement la France, le Royaume-Uni et la Russie (puis les États-Unis) à l'Allemagne et l'Autriche-Hongrie. Elle a fait plus de 9 millions de morts." },
    { id:"db-4-010", t:4, lvl:"B1", q: "Quel jour férié commémore la fin de la Première Guerre mondiale ?", o: ["Le 8 mai", "Le 11 novembre", "Le 14 juillet", "Le 1er mai"], c: 1, e: "Le 11 novembre est un jour férié qui commémore l'armistice de 1918, marquant la fin des combats de la Première Guerre mondiale. Chaque année, on rend hommage aux soldats morts pour la France lors de cérémonies au monument aux morts." },
    { id:"db-4-011", t:4, lvl:"B1", q: "Quand a eu lieu la Seconde Guerre mondiale ?", o: ["1914-1918", "1939-1945", "1950-1960", "1870-1871"], c: 1, e: "La Seconde Guerre mondiale s'est déroulée de 1939 à 1945. Elle a opposé les Alliés (France, Royaume-Uni, États-Unis, URSS) aux puissances de l'Axe (Allemagne nazie, Italie, Japon). C'est le conflit le plus meurtrier de l'histoire avec plus de 50 millions de morts." },
    { id:"db-4-012", t:4, lvl:"B1", q: "Quel jour férié commémore la fin de la Seconde Guerre mondiale en Europe ?", o: ["Le 11 novembre", "Le 8 mai", "Le 14 juillet", "Le 1er janvier"], c: 1, e: "Le 8 mai est un jour férié qui commémore la victoire des Alliés sur l'Allemagne nazie et la fin de la Seconde Guerre mondiale en Europe le 8 mai 1945. C'est un jour de mémoire nationale importante." },
    { id:"db-4-013", t:4, lvl:"B2", q: "Qu'est-ce que la Shoah ?", o: ["Une bataille", "Le génocide des Juifs d'Europe par les nazis pendant la Seconde Guerre mondiale", "Une révolution", "Un traité de paix"], c: 1, e: "La Shoah (mot hébreu signifiant 'catastrophe') désigne le génocide systématique des Juifs d'Europe par le régime nazi pendant la Seconde Guerre mondiale. Environ 6 millions de Juifs ont été assassinés dans les camps de concentration et d'extermination. C'est un crime contre l'humanité." },
    { id:"db-4-014", t:4, lvl:"B1", q: "Qui était le général de Gaulle ?", o: ["Un roi", "Le chef de la Résistance française et fondateur de la Ve République", "Un philosophe", "Un artiste"], c: 1, e: "Charles de Gaulle (1890-1970) était un général et homme d'État français. Chef de la France libre pendant la Seconde Guerre mondiale, il a dirigé la Résistance contre l'occupation nazie. Il a fondé la Ve République en 1958 et en a été le premier président jusqu'en 1969." },
    { id:"db-4-015", t:4, lvl:"B1", q: "Qu'a fait le général de Gaulle le 18 juin 1940 ?", o: ["Il a signé l'armistice", "Il a lancé un appel à la résistance depuis Londres", "Il a démissionné", "Il a fui en Amérique"], c: 1, e: "Le 18 juin 1940, le général de Gaulle a lancé depuis Londres un appel radiophonique refusant la défaite face à l'Allemagne nazie et appelant les Français à continuer le combat. Cet 'Appel du 18 juin' marque le début de la Résistance française organisée." },

    // === HISTOIRE RÉCENTE (Questions 16-25) ===
    { id:"db-4-016", t:4, lvl:"B1", q: "En quelle année les femmes ont-elles obtenu le droit de vote en France ?", o: ["1789", "1848", "1944", "1974"], c: 2, e: "Les femmes françaises ont obtenu le droit de vote en 1944 grâce à une ordonnance du gouvernement provisoire du général de Gaulle. Elles ont voté pour la première fois aux élections municipales d'avril 1945. La France a été l'un des derniers pays d'Europe occidentale à accorder ce droit." },
    { id:"db-4-017", t:4, lvl:"B2", q: "Qu'était le régime de Vichy (1940-1944) ?", o: ["Une démocratie", "Un régime autoritaire collaborant avec l'Allemagne nazie", "Une république", "Un empire"], c: 1, e: "Le régime de Vichy (1940-1944) était un régime autoritaire dirigé par le maréchal Pétain, établi après la défaite française face à l'Allemagne. Ce régime a collaboré avec les nazis et porte une responsabilité dans la déportation de dizaines de milliers de Juifs de France." },
    { id:"db-4-018", t:4, lvl:"B1", q: "Quel événement majeur s'est produit le 6 juin 1944 ?", o: ["La fin de la guerre", "Le débarquement allié en Normandie", "L'appel du 18 juin", "La prise de la Bastille"], c: 1, e: "Le 6 juin 1944, appelé 'Jour J' (D-Day), marque le débarquement des forces alliées (américaines, britanniques, canadiennes) sur les plages de Normandie. Cette opération militaire massive a été une étape décisive dans la libération de la France et de l'Europe de l'occupation nazie." },
    { id:"db-4-019", t:4, lvl:"B1", q: "En quelle année a été créée l'Organisation des Nations Unies (ONU) ?", o: ["1918", "1939", "1945", "1960"], c: 2, e: "L'ONU a été créée en 1945 après la Seconde Guerre mondiale pour maintenir la paix et la sécurité internationales. La France est l'un des cinq membres permanents du Conseil de sécurité avec les États-Unis, le Royaume-Uni, la Russie et la Chine." },
    { id:"db-4-020", t:4, lvl:"B1", q: "En quelle année la Communauté économique européenne (CEE) a-t-elle été créée ?", o: ["1945", "1957", "1968", "1992"], c: 1, e: "La Communauté économique européenne a été créée en 1957 par le traité de Rome, signé par six pays fondateurs dont la France. C'était le début de la construction européenne visant à établir une union économique et à garantir la paix en Europe." },
    { id:"db-4-021", t:4, lvl:"B2", q: "Qu'était la décolonisation française (1950-1962) ?", o: ["Une guerre civile", "Le processus d'indépendance des anciennes colonies françaises", "Une révolution", "Une réforme économique"], c: 1, e: "La décolonisation française (1950-1962) est le processus par lequel les colonies et territoires sous domination française ont accédé à l'indépendance. Ce processus, parfois violent (guerres d'Indochine et d'Algérie), a concerné l'Afrique, l'Asie et le Maghreb." },
    { id:"db-4-022", t:4, lvl:"B1", q: "Qu'était Mai 68 en France ?", o: ["Une guerre", "Un important mouvement social et étudiant contestant l'ordre établi", "Une élection", "Une catastrophe naturelle"], c: 1, e: "Mai 68 désigne un mouvement social, culturel et politique majeur initié par des étudiants parisiens puis étendu aux ouvriers et salariés. Ces manifestations et grèves massives ont contesté l'autorité traditionnelle et entraîné d'importantes transformations sociales et culturelles en France." },
    { id:"db-4-023", t:4, lvl:"B1", q: "En quelle année l'âge de la majorité est-il passé de 21 à 18 ans en France ?", o: ["1945", "1968", "1974", "1981"], c: 2, e: "L'âge de la majorité est passé de 21 à 18 ans en 1974 sous la présidence de Valéry Giscard d'Estaing. Cette réforme a permis aux jeunes de 18 ans de voter, de se marier sans autorisation parentale et d'exercer pleinement leurs droits civils." },
    { id:"db-4-024", t:4, lvl:"B2", q: "Quelle loi importante a été promulguée en 1975 concernant les femmes ?", o: ["Le droit de vote", "La loi sur l'interruption volontaire de grossesse (IVG)", "Le droit de travailler", "Le droit d'étudier"], c: 1, e: "La loi Veil de 1975, portée par Simone Veil alors Ministre de la Santé, a légalisé l'interruption volontaire de grossesse (IVG) en France. Cette loi historique a donné aux femmes le droit de disposer de leur corps et a marqué une avancée majeure pour l'égalité femmes-hommes." },
    { id:"db-4-025", t:4, lvl:"B1", q: "En quelle année la peine de mort a-t-elle été abolie en France ?", o: ["1945", "1968", "1981", "2000"], c: 2, e: "La peine de mort a été abolie en France en 1981 sous la présidence de François Mitterrand, grâce à l'action du Garde des Sceaux Robert Badinter. La France a été l'un des derniers pays d'Europe occidentale à supprimer cette peine. C'est une mesure irréversible." },

    // === GÉOGRAPHIE DE LA FRANCE (Questions 26-40) ===
    { id:"db-4-026", t:4, lvl:"B1", q: "Quelle est la capitale de la France ?", o: ["Lyon", "Marseille", "Paris", "Bordeaux"], c: 2, e: "Paris est la capitale politique, économique et culturelle de la France. Située au centre du pays, sur la Seine, Paris est également la ville la plus peuplée de France avec plus de 2 millions d'habitants dans la ville et 12 millions dans son agglomération." },
    { id:"db-4-027", t:4, lvl:"B1", q: "Quel fleuve traverse Paris ?", o: ["La Loire", "Le Rhône", "La Seine", "La Garonne"], c: 2, e: "La Seine traverse Paris d'est en ouest. Ce fleuve de 777 km prend sa source en Bourgogne et se jette dans la Manche. Les quais de Seine à Paris sont inscrits au patrimoine mondial de l'UNESCO." },
    { id:"db-4-028", t:4, lvl:"B1", q: "Quel est le plus long fleuve de France ?", o: ["La Seine", "La Loire", "Le Rhône", "Le Rhin"], c: 1, e: "La Loire est le plus long fleuve entièrement en France avec 1 012 km. Elle prend sa source dans le Massif central et se jette dans l'océan Atlantique à Saint-Nazaire. Elle est surnommée 'le dernier fleuve sauvage d'Europe'." },
    { id:"db-4-029", t:4, lvl:"B1", q: "Quels sont les principaux fleuves français ?", o: ["La Tamise et le Danube", "La Loire, la Seine, la Garonne, le Rhône, le Rhin", "Le Nil et l'Amazone", "Le Mississippi et le Colorado"], c: 1, e: "Les cinq principaux fleuves français sont : la Loire (le plus long), la Seine (traverse Paris), la Garonne (Sud-Ouest), le Rhône (Sud-Est), et le Rhin (frontière avec l'Allemagne). Ces fleuves structurent le territoire et son économie." },
    { id:"db-4-030", t:4, lvl:"B1", q: "Quel est le point culminant de la France et de l'Europe occidentale ?", o: ["Le Mont Blanc", "Le Pic du Midi", "Le Puy de Dôme", "Les Pyrénées"], c: 0, e: "Le Mont Blanc, situé dans les Alpes à la frontière franco-italienne, est le point culminant de la France et de l'Europe occidentale avec 4 807 mètres d'altitude. C'est un haut lieu de l'alpinisme et du tourisme de montagne." },
    { id:"db-4-031", t:4, lvl:"B1", q: "Quels sont les principaux massifs montagneux français ?", o: ["Les Rocheuses et les Andes", "Les Alpes, les Pyrénées, le Massif central, les Vosges, le Jura", "L'Himalaya et le Caucase", "Les Appalaches"], c: 1, e: "Les principaux massifs montagneux français sont : les Alpes (sommet : Mont Blanc), les Pyrénées (frontière avec l'Espagne), le Massif central (volcans anciens), les Vosges (Est) et le Jura (frontière suisse). Ces montagnes sont importantes pour le tourisme et l'écologie." },
    { id:"db-4-032", t:4, lvl:"B1", q: "Environ combien d'habitants compte la France en 2025 ?", o: ["40 millions", "55 millions", "68 millions", "100 millions"], c: 2, e: "La France compte environ 68 millions d'habitants en 2025 (67,8 millions au 1er janvier 2024 selon l'INSEE). C'est le deuxième pays le plus peuplé de l'Union européenne après l'Allemagne et le 20e pays mondial par sa population." },
    { id:"db-4-033", t:4, lvl:"B2", q: "Quelle proportion de Français vit dans des aires urbaines ?", o: ["50%", "70%", "90%", "30%"], c: 2, e: "Environ 9 Français sur 10 (soit 90%) vivent dans des aires urbaines, c'est-à-dire dans des villes et leur zone d'influence. La France est donc un pays très urbanisé, même si son territoire comporte encore de vastes espaces ruraux." },
    { id:"db-4-034", t:4, lvl:"B1", q: "Combien de régions compte la France métropolitaine depuis 2016 ?", o: ["22", "13", "27", "18"], c: 1, e: "Depuis la réforme territoriale de 2016, la France métropolitaine compte 13 régions (contre 22 auparavant). À cela s'ajoutent 5 régions d'outre-mer (DROM), portant le total à 18 régions françaises." },
    { id:"db-4-035", t:4, lvl:"B1", q: "Combien y a-t-il de départements en France ?", o: ["50", "96", "101", "150"], c: 2, e: "La France compte 101 départements au total : 96 en métropole et 5 en outre-mer (Guadeloupe, Martinique, Guyane, La Réunion, Mayotte). Chaque département est identifié par un numéro qui figure notamment sur les plaques d'immatriculation." },
    { id:"db-4-036", t:4, lvl:"B1", q: "Quels sont les 5 Départements et Régions d'Outre-Mer (DROM) ?", o: ["Corse, Alsace, Bretagne, Normandie, Savoie", "Guadeloupe, Martinique, Guyane, La Réunion, Mayotte", "Monaco, Andorre, Luxembourg, Belgique, Suisse", "Québec, Haïti, Madagascar, Sénégal, Mali"], c: 1, e: "Les 5 DROM sont : la Guadeloupe et la Martinique (Antilles), la Guyane (Amérique du Sud), La Réunion (océan Indien) et Mayotte (océan Indien). Ces territoires ultramarins font partie intégrante de la France et de l'Union européenne." },
    { id:"db-4-037", t:4, lvl:"B2", q: "Quelles mers et océans bordent la France ?", o: ["L'océan Indien uniquement", "La mer Méditerranée, l'océan Atlantique, la Manche, la mer du Nord", "L'océan Pacifique uniquement", "La mer Rouge et la mer Noire"], c: 1, e: "La France métropolitaine est bordée par quatre façades maritimes : la mer Méditerranée au sud, l'océan Atlantique à l'ouest, la Manche au nord-ouest, et la mer du Nord au nord. Grâce à l'outre-mer, la France possède le 2e domaine maritime mondial." },
    { id:"db-4-038", t:4, lvl:"B1", q: "Quels pays ont une frontière terrestre avec la France ?", o: ["Allemagne, Pologne, Autriche", "Espagne, Italie, Suisse, Allemagne, Belgique, Luxembourg", "Portugal, Grèce, Norvège", "Russie, Turquie, Maroc"], c: 1, e: "La France partage des frontières terrestres avec 8 pays : l'Espagne et Andorre (Pyrénées), l'Italie (Alpes), la Suisse (Jura et Alpes), l'Allemagne (Rhin), le Luxembourg et la Belgique (Nord-Est), et Monaco (Côte d'Azur). Plus le Brésil et le Suriname (Guyane)." },
    { id:"db-4-039", t:4, lvl:"B1", q: "Quelles sont les 10 principales métropoles françaises ?", o: ["Seulement Paris", "Paris, Lyon, Marseille, Toulouse, Lille, Bordeaux, Nice, Nantes, Strasbourg, Rennes", "Londres, Berlin, Madrid", "New York, Tokyo, Pékin"], c: 1, e: "Les 10 principales métropoles françaises sont, par ordre de population : Paris, Lyon, Marseille, Toulouse, Lille, Bordeaux, Nice, Nantes, Strasbourg et Rennes. Ces grandes villes concentrent l'activité économique, culturelle et les services." },
    { id:"db-4-040", t:4, lvl:"B2", q: "Pourquoi dit-on que la France est l'Hexagone ?", o: ["À cause de ses 6 régions", "À cause de sa forme géométrique approximative à 6 côtés", "À cause de ses 6 fleuves", "À cause de Paris"], c: 1, e: "On appelle la France métropolitaine 'l'Hexagone' en raison de sa forme géométrique qui évoque approximativement un polygone à six côtés. Cette image géométrique est devenue un symbole populaire pour désigner le territoire français continental." },

    // === GÉOGRAPHIE ET ÉCONOMIE (Questions 41-50) ===
    { id:"db-4-041", t:4, lvl:"B2", q: "Quelles sont les 6 régions françaises les plus peuplées ?", o: ["Corse, Bretagne, Normandie, Alsace, Savoie, Limousin", "Île-de-France, Auvergne-Rhône-Alpes, Nouvelle-Aquitaine, Occitanie, Hauts-de-France, Provence-Alpes-Côte d'Azur", "Toutes ont la même population", "Seule l'Île-de-France compte"], c: 1, e: "Les 6 régions les plus peuplées sont : l'Île-de-France (12 millions), Auvergne-Rhône-Alpes (8 millions), Nouvelle-Aquitaine, Occitanie, Hauts-de-France et Provence-Alpes-Côte d'Azur. L'Île-de-France concentre à elle seule près de 20% de la population française." },
    { id:"db-4-042", t:4, lvl:"B1", q: "Quels sont les principaux ports français ?", o: ["Aucun port important", "Marseille, Le Havre, Dunkerque, Nantes-Saint-Nazaire", "Londres et Amsterdam", "New York et Shanghai"], c: 1, e: "Les principaux ports français sont : Marseille (1er port français en Méditerranée), Le Havre (mer du Nord), Dunkerque (Nord), et Nantes-Saint-Nazaire (Atlantique). Ces ports sont essentiels pour le commerce international et l'économie française." },
    { id:"db-4-043", t:4, lvl:"B2", q: "Où se situent principalement les activités économiques en France ?", o: ["Dans les campagnes isolées", "À proximité des grandes villes et des axes de communication", "Uniquement à Paris", "Dans les montagnes"], c: 1, e: "Les principales activités économiques se situent à proximité des grandes villes (Paris, Lyon, Marseille, Toulouse) et le long des grands axes de communication (autoroutes, voies ferrées, fleuves). Cette concentration géographique s'explique par l'accès aux infrastructures, main-d'œuvre et marchés." },
    { id:"db-4-044", t:4, lvl:"B1", q: "La France est-elle une destination touristique importante ?", o: ["Non, peu de touristes", "Oui, c'est la première destination touristique mondiale", "Non, elle est 50ème", "Seulement pour les Français"], c: 1, e: "Oui, la France est la première destination touristique mondiale avec environ 90 millions de visiteurs étrangers par an. Le tourisme représente un secteur économique majeur grâce au patrimoine culturel, aux paysages variés, à la gastronomie et aux infrastructures de qualité." },
    { id:"db-4-045", t:4, lvl:"B2", q: "Quelles sont les principales régions touristiques françaises ?", o: ["Seulement Paris", "Les grandes villes (Paris, Lyon), les côtes (Côte d'Azur, Bretagne, Normandie), les montagnes (Alpes, Pyrénées)", "Uniquement le Nord", "Il n'y a pas de tourisme"], c: 1, e: "Les principales régions touristiques sont : les grandes villes (Paris, Lyon), les littoraux (Côte d'Azur, littoral atlantique, Bretagne, Normandie), les massifs montagneux (Alpes pour le ski, Pyrénées) et les châteaux de la Loire. Cette diversité attire des profils de touristes variés." },
    { id:"db-4-046", t:4, lvl:"B1", q: "Quelle forme géographique la France a-t-elle approximativement ?", o: ["Un cercle", "Un hexagone", "Un triangle", "Un carré"], c: 1, e: "La France métropolitaine a approximativement la forme d'un hexagone, ce qui lui vaut le surnom d''Hexagone'. Cette forme symbolique simplifie la géographie complexe du pays et est devenue un symbole national." },
    { id:"db-4-047", t:4, lvl:"B1", q: "La France a-t-elle des territoires en dehors de l'Europe ?", o: ["Non, seulement en Europe", "Oui, dans les océans Atlantique, Indien et Pacifique", "Oui, seulement en Afrique", "Non, elle a tout perdu"], c: 1, e: "Oui, la France possède des territoires dans le monde entier : 5 DROM (Guadeloupe, Martinique, Guyane, La Réunion, Mayotte) et 7 collectivités d'outre-mer (Nouvelle-Calédonie, Polynésie française, etc.). Ces territoires font de la France la 2e puissance maritime mondiale." },
    { id:"db-4-048", t:4, lvl:"B2", q: "Qu'est-ce qui fait de la France la 2e puissance maritime mondiale ?", o: ["Ses bateaux", "Son vaste domaine maritime grâce aux territoires ultramarins", "Ses ports uniquement", "Son armée"], c: 1, e: "Grâce à ses territoires ultramarins répartis dans tous les océans, la France dispose du 2e plus grand domaine maritime mondial (Zone Économique Exclusive de 11 millions de km²), juste après les États-Unis. Cela lui confère d'importantes ressources et une présence géopolitique mondiale." },
    { id:"db-4-049", t:4, lvl:"B1", q: "Combien de collectivités d'outre-mer (COM) la France possède-t-elle ?", o: ["Aucune", "7 collectivités", "2 collectivités", "20 collectivités"], c: 1, e: "La France possède 7 collectivités d'outre-mer (COM) avec des statuts variés : Nouvelle-Calédonie, Polynésie française, Saint-Barthélemy, Saint-Martin, Saint-Pierre-et-Miquelon, Wallis-et-Futuna, et les Terres australes et antarctiques françaises. Elles ont une autonomie plus importante que les DROM." },
    { id:"db-4-050", t:4, lvl:"B1", q: "Dans quel océan se trouve l'île de La Réunion ?", o: ["Océan Atlantique", "Océan Indien", "Océan Pacifique", "Mer Méditerranée"], c: 1, e: "La Réunion est située dans l'océan Indien, à l'est de Madagascar. C'est un département et une région d'outre-mer français. L'île compte environ 860 000 habitants et est célèbre pour son volcan actif, le Piton de la Fournaise." },

    // === PATRIMOINE ET CULTURE (Questions 51-65) ===
    { id:"db-4-051", t:4, lvl:"B1", q: "Quel monument parisien a été construit pour l'Exposition universelle de 1889 ?", o: ["L'Arc de Triomphe", "La Tour Eiffel", "Notre-Dame", "Le Louvre"], c: 1, e: "La Tour Eiffel a été construite par l'ingénieur Gustave Eiffel pour l'Exposition universelle de 1889, qui célébrait le centenaire de la Révolution française. Haute de 330 mètres, elle est devenue le symbole de Paris et accueille près de 7 millions de visiteurs par an." },
    { id:"db-4-052", t:4, lvl:"B1", q: "Quel monument historique se trouve à Versailles ?", o: ["La Tour Eiffel", "Le château de Versailles construit par Louis XIV", "La cathédrale Notre-Dame", "Le Louvre"], c: 1, e: "Le château de Versailles est un immense palais royal construit au XVIIe siècle par le roi Louis XIV, le 'Roi Soleil'. C'était le siège du pouvoir royal jusqu'à la Révolution. Avec ses jardins somptueux et sa galerie des Glaces, c'est l'un des sites touristiques les plus visités de France." },
    { id:"db-4-053", t:4, lvl:"B1", q: "Quel site historique en Normandie est une abbaye sur un îlot rocheux ?", o: ["La Tour Eiffel", "Le Mont-Saint-Michel", "Le château de Chambord", "Le Louvre"], c: 1, e: "Le Mont-Saint-Michel est une abbaye médiévale construite sur un îlot rocheux en Normandie, entouré par la mer à marée haute. Classé au patrimoine mondial de l'UNESCO, c'est l'un des sites les plus visités de France avec environ 3 millions de visiteurs par an." },
    { id:"db-4-054", t:4, lvl:"B2", q: "Qu'est-ce que les châteaux de la Loire ?", o: ["Des hôtels modernes", "Un ensemble de châteaux Renaissance situés dans la vallée de la Loire", "Des prisons", "Des casernes militaires"], c: 1, e: "Les châteaux de la Loire sont un ensemble de châteaux royaux et seigneuriaux construits principalement à la Renaissance (XVe-XVIe siècles) dans la vallée de la Loire. Les plus célèbres sont Chambord, Chenonceau, Amboise et Blois. Ils témoignent de la puissance royale et du raffinement artistique français." },
    { id:"db-4-055", t:4, lvl:"B1", q: "Quel musée parisien était autrefois un palais royal et abrite La Joconde ?", o: ["Le musée d'Orsay", "Le Louvre", "Le Centre Pompidou", "Le musée Rodin"], c: 1, e: "Le musée du Louvre, situé dans un ancien palais royal au cœur de Paris, est le plus grand musée du monde et le plus visité. Il abrite des œuvres majeures comme La Joconde de Léonard de Vinci, la Vénus de Milo et la Victoire de Samothrace." },
    { id:"db-4-056", t:4, lvl:"B1", q: "Qui a peint La Joconde ?", o: ["Pablo Picasso", "Léonard de Vinci", "Claude Monet", "Vincent Van Gogh"], c: 1, e: "La Joconde (Mona Lisa) a été peinte par Léonard de Vinci, artiste italien de la Renaissance, au début du XVIe siècle. Ce portrait énigmatique est le tableau le plus célèbre du monde et attire des millions de visiteurs au musée du Louvre chaque année." },
    { id:"db-4-057", t:4, lvl:"B2", q: "Qui était Molière ?", o: ["Un roi", "Le plus célèbre auteur de théâtre français du XVIIe siècle", "Un général", "Un peintre"], c: 1, e: "Molière (1622-1673) est le plus célèbre auteur de théâtre français. Il a vécu sous le règne de Louis XIV et a écrit des comédies satiriques comme Le Misanthrope, Tartuffe, L'Avare et Le Malade imaginaire. Ses pièces sont encore jouées dans le monde entier." },
    { id:"db-4-058", t:4, lvl:"B1", q: "Qui a écrit 'Les Misérables' et 'Notre-Dame de Paris' ?", o: ["Molière", "Voltaire", "Victor Hugo", "Émile Zola"], c: 2, e: "Victor Hugo (1802-1885) est l'un des plus grands écrivains français du XIXe siècle. Il a écrit des romans célèbres comme Les Misérables et Notre-Dame de Paris, ainsi que de nombreux poèmes. Il s'est aussi engagé politiquement contre la peine de mort et pour la justice sociale." },
    { id:"db-4-059", t:4, lvl:"B2", q: "Qui était Voltaire ?", o: ["Un roi", "Un philosophe des Lumières défendant la tolérance et la liberté de pensée", "Un général", "Un peintre"], c: 1, e: "Voltaire (1694-1778) était un philosophe, écrivain et polémiste des Lumières. Il a combattu toute sa vie pour la tolérance religieuse, la liberté de pensée et contre l'obscurantisme. Ses écrits ont influencé la Révolution française et les droits de l'homme." },
    { id:"db-4-060", t:4, lvl:"B1", q: "Qui était Jeanne d'Arc ?", o: ["Une reine", "Une héroïne nationale qui a combattu les Anglais au XVe siècle", "Une philosophe", "Une artiste"], c: 1, e: "Jeanne d'Arc (1412-1431) était une jeune paysanne qui, pendant la guerre de Cent Ans, a conduit les armées françaises à plusieurs victoires contre les Anglais. Capturée et brûlée vive à Rouen, elle est devenue une héroïne nationale et un symbole du courage français." },
    { id:"db-4-061", t:4, lvl:"B2", q: "Qu'est-ce que la gastronomie française ?", o: ["La cuisine rapide", "L'art culinaire français reconnu au patrimoine mondial de l'UNESCO", "La nourriture industrielle", "Les fast-foods"], c: 1, e: "La gastronomie française désigne l'art de bien manger et la richesse culinaire de la France. Inscrite au patrimoine culturel immatériel de l'UNESCO depuis 2010, elle se caractérise par la diversité des produits, le savoir-faire des chefs, et l'importance du repas comme moment de convivialité." },
    { id:"db-4-062", t:4, lvl:"B1", q: "Quels sont des plats typiques de la cuisine française ?", o: ["Le hamburger et les frites", "Le coq au vin, la quiche lorraine, la ratatouille, le bœuf bourguignon", "Les sushis et les pizzas", "Les tacos et les burritos"], c: 1, e: "Des plats typiques français incluent : le coq au vin, la quiche lorraine, la ratatouille, le bœuf bourguignon, la bouillabaisse, le cassoulet, les escargots, le pot-au-feu, et bien d'autres. Chaque région a ses spécialités qui reflètent son terroir et son histoire." },
    { id:"db-4-063", t:4, lvl:"B1", q: "Quel produit français est mondialement réputé ?", o: ["Le riz", "Le fromage et le vin", "Le thé", "Le café"], c: 1, e: "Le fromage et le vin français sont mondialement réputés. On dit qu'il existe plus de 400 variétés de fromages français (camembert, brie, roquefort, comté...). Les vins français (Bordeaux, Bourgogne, Champagne) sont parmi les plus prestigieux au monde." },
    { id:"db-4-064", t:4, lvl:"B2", q: "Combien de personnes parlent français dans le monde ?", o: ["50 millions", "150 millions", "321 millions", "1 milliard"], c: 2, e: "Environ 321 millions de personnes parlent français dans le monde en 2024. Le français est la 5e langue mondiale et est parlé sur les cinq continents. C'est une langue officielle dans 29 pays et dans de nombreuses organisations internationales (ONU, UNESCO, UE)." },
    { id:"db-4-065", t:4, lvl:"B1", q: "Qu'est-ce que la Francophonie ?", o: ["Un parti politique", "L'ensemble des pays et personnes parlant français dans le monde", "Un festival", "Une entreprise"], c: 1, e: "La Francophonie désigne l'ensemble des pays, régions et personnes qui parlent français dans le monde. L'Organisation internationale de la Francophonie (OIF) regroupe 88 États et gouvernements qui partagent l'usage du français et des valeurs communes de démocratie et de droits de l'homme." },

    // === PERSONNAGES HISTORIQUES ET CULTURE (Questions 66-80) ===
    { id:"db-4-066", t:4, lvl:"B2", q: "Qui était Clovis ?", o: ["Un empereur romain", "Le premier roi des Francs qui a unifié des royaumes au Ve siècle", "Un philosophe", "Un peintre"], c: 1, e: "Clovis (466-511) est considéré comme le premier roi des Francs. Il a unifié plusieurs royaumes francs et adopté le christianisme, jetant les bases de ce qui deviendra la France. Son baptême à Reims a marqué l'alliance entre le pouvoir royal et l'Église catholique." },
    { id:"db-4-067", t:4, lvl:"B2", q: "Qui était Louis XIV ?", o: ["Un philosophe", "Le 'Roi Soleil' qui a régné 72 ans et construit Versailles", "Un général", "Un président"], c: 1, e: "Louis XIV (1638-1715), surnommé le 'Roi Soleil', a régné pendant 72 ans (record historique). Il a incarné la monarchie absolue, construit le château de Versailles, et fait de la France la première puissance européenne. Son règne a marqué l'apogée de l'absolutisme royal." },
    { id:"db-4-068", t:4, lvl:"B1", q: "Qui était Louis XVI ?", o: ["Un empereur", "Le dernier roi avant la Révolution, guillotiné en 1793", "Un président", "Un artiste"], c: 1, e: "Louis XVI (1754-1793) était le roi de France au moment de la Révolution. Incapable de résoudre la crise financière et politique, il a été renversé, jugé pour trahison et guillotiné en janvier 1793. Sa mort marque la fin symbolique de la monarchie millénaire en France." },
    { id:"db-4-069", t:4, lvl:"B2", q: "Qui était François Mitterrand ?", o: ["Un roi", "Le président qui a aboli la peine de mort en 1981", "Un général", "Un philosophe"], c: 1, e: "François Mitterrand (1916-1996) a été président de la République de 1981 à 1995 (deux mandats de 7 ans). Premier président socialiste de la Ve République, il a marqué l'histoire par l'abolition de la peine de mort en 1981 et de nombreuses réformes sociales." },
    { id:"db-4-070", t:4, lvl:"B2", q: "Qui était Simone Veil ?", o: ["Une actrice", "Une femme politique qui a fait adopter la loi sur l'IVG en 1975", "Une chanteuse", "Une sportive"], c: 1, e: "Simone Veil (1927-2017) était une femme politique française, rescapée de la Shoah. En tant que Ministre de la Santé, elle a fait adopter en 1975 la loi légalisant l'interruption volontaire de grossesse (IVG). Elle a été la première présidente du Parlement européen élu au suffrage universel." },
    { id:"db-4-071", t:4, lvl:"B1", q: "Quel écrivain français a écrit 'Germinal' et 'L'Assommoir' ?", o: ["Victor Hugo", "Molière", "Émile Zola", "Voltaire"], c: 2, e: "Émile Zola (1840-1902) était un écrivain et journaliste français, chef de file du naturalisme. Il a écrit une série de 20 romans (Les Rougon-Macquart) dont Germinal (sur les mineurs) et L'Assommoir (sur le monde ouvrier). Il s'est aussi engagé dans l'affaire Dreyfus avec son célèbre 'J'accuse'." },
    { id:"db-4-072", t:4, lvl:"B2", q: "Qui était Marie Curie ?", o: ["Une actrice", "Une physicienne d'origine polonaise, prix Nobel, pionnière de la radioactivité", "Une chanteuse", "Une reine"], c: 1, e: "Marie Curie (1867-1934), née en Pologne, était une physicienne et chimiste française pionnière dans l'étude de la radioactivité. Elle est la première femme à recevoir un prix Nobel et la seule personne à en recevoir deux dans deux disciplines différentes (physique et chimie). Elle repose au Panthéon." },
    { id:"db-4-073", t:4, lvl:"B1", q: "Où sont enterrés les grands personnages de l'histoire française ?", o: ["Au cimetière du Père-Lachaise", "Au Panthéon", "À Versailles", "À la Tour Eiffel"], c: 1, e: "Le Panthéon, à Paris, est le monument où reposent les grands personnages de la Nation française : Voltaire, Rousseau, Victor Hugo, Émile Zola, Jean Jaurès, Marie Curie, Simone Veil, etc. L'inscription 'Aux grands hommes, la Patrie reconnaissante' orne son fronton." },
    { id:"db-4-074", t:4, lvl:"B2", q: "Qui était Edith Piaf ?", o: ["Une actrice", "Une chanteuse française emblématique du XXe siècle", "Une politicienne", "Une peintre"], c: 1, e: "Edith Piaf (1915-1963) était l'une des plus grandes chanteuses françaises du XXe siècle. Surnommée 'la Môme Piaf', elle a interprété des chansons devenues mythiques comme La Vie en rose, Non, je ne regrette rien, et L'Hymne à l'amour. Elle est une icône culturelle mondiale." },
    { id:"db-4-075", t:4, lvl:"B1", q: "Quel peintre français est célèbre pour ses tableaux de nymphéas et son jardin de Giverny ?", o: ["Pablo Picasso", "Claude Monet", "Vincent Van Gogh", "Leonardo da Vinci"], c: 1, e: "Claude Monet (1840-1926) était un peintre impressionniste français. Il est célèbre pour ses tableaux de nymphéas (nénuphars) peints dans son jardin de Giverny. Il est l'un des fondateurs de l'impressionnisme, mouvement artistique majeur né en France au XIXe siècle." },
    { id:"db-4-076", t:4, lvl:"B2", q: "Quel événement sportif international a lieu chaque année en France au mois de juillet ?", o: ["La Coupe du monde de football", "Le Tour de France cycliste", "Les Jeux Olympiques", "Roland-Garros"], c: 1, e: "Le Tour de France est une course cycliste par étapes qui se déroule chaque année en juillet depuis 1903. C'est l'une des épreuves sportives les plus prestigieuses et suivies au monde, parcourant environ 3 500 km à travers la France et parfois les pays voisins." },
    { id:"db-4-077", t:4, lvl:"B1", q: "Quel tournoi de tennis majeur se déroule à Paris chaque année ?", o: ["Wimbledon", "Roland-Garros", "US Open", "Open d'Australie"], c: 1, e: "Roland-Garros est l'un des quatre tournois du Grand Chelem de tennis, qui se déroule chaque année à Paris fin mai-début juin. C'est le seul Grand Chelem joué sur terre battue. Il attire les meilleurs joueurs mondiaux et des centaines de milliers de spectateurs." },
    { id:"db-4-078", t:4, lvl:"B1", q: "Quelles fêtes importantes sont célébrées en France ?", o: ["Seulement le 14 juillet", "Noël, le Nouvel An, Pâques, le 14 juillet, le 8 mai, le 11 novembre", "Aucune fête", "Seulement des fêtes religieuses"], c: 1, e: "Les principales fêtes en France incluent : Noël (25 décembre), le Nouvel An (1er janvier), Pâques (variable), la fête du Travail (1er mai), la victoire 1945 (8 mai), la fête nationale (14 juillet), l'Assomption (15 août), la Toussaint (1er novembre), l'armistice 1918 (11 novembre)." },
    { id:"db-4-079", t:4, lvl:"B2", q: "Qu'est-ce que le Festival de Cannes ?", o: ["Un festival de musique", "Un festival international de cinéma parmi les plus prestigieux au monde", "Un festival de danse", "Une fête nationale"], c: 1, e: "Le Festival de Cannes est un festival international de cinéma qui se tient chaque année en mai à Cannes, sur la Côte d'Azur. Créé en 1946, c'est l'un des festivals de cinéma les plus prestigieux au monde. La récompense suprême est la Palme d'or." },
    { id:"db-4-080", t:4, lvl:"B1", q: "Qu'est-ce que la baguette française ?", o: ["Un instrument de musique", "Un pain traditionnel long et croustillant, symbole de la France", "Un bâton", "Un fromage"], c: 1, e: "La baguette est un pain traditionnel français, long (environ 65 cm), mince et croustillant. C'est un symbole culinaire de la France reconnu mondialement. En 2022, le savoir-faire artisanal et la culture de la baguette ont été inscrits au patrimoine immatériel de l'UNESCO." },

    // === QUESTIONS COMPLÉMENTAIRES - HISTOIRE (Questions 81-100) ===
    { id:"db-4-081", t:4, lvl:"B2", q: "En quelle année Napoléon Ier est-il devenu empereur des Français ?", o: ["1789", "1799", "1804", "1815"], c: 2, e: "Napoléon Bonaparte est devenu empereur des Français en 1804, sous le nom de Napoléon Ier. Il a été sacré à Notre-Dame de Paris. Son règne a duré jusqu'en 1814-1815. Il a modernisé la France (Code civil, lycées, préfets) mais aussi mené de nombreuses guerres en Europe." },
    { id:"db-4-082", t:4, lvl:"B1", q: "Quel roi de France a été exécuté pendant la Révolution française ?", o: ["Louis XIII", "Louis XIV", "Louis XV", "Louis XVI"], c: 3, e: "Louis XVI a été exécuté par guillotine le 21 janvier 1793, place de la Révolution (actuelle place de la Concorde) à Paris. Il avait été jugé pour trahison par la Convention nationale. Son exécution marque symboliquement la fin de la monarchie absolue en France." },
    { id:"db-4-083", t:4, lvl:"B2", q: "De quand date l'appel à la Résistance du général de Gaulle ?", o: ["14 juillet 1940", "18 juin 1940", "8 mai 1945", "6 juin 1944"], c: 1, e: "L'appel du 18 juin 1940 est le discours radiophonique prononcé par le général de Gaulle depuis Londres, appelant les Français à résister à l'occupation allemande. C'est l'acte fondateur de la Résistance française. Cette date est aujourd'hui commémorée chaque année." },
    { id:"db-4-084", t:4, lvl:"B1", q: "Pourquoi la Shoah est-elle enseignée à l'école ?", o: ["C'est facultatif", "Pour comprendre l'histoire et lutter contre la haine et le racisme", "C'est interdit d'en parler", "Seulement en cours de religion"], c: 1, e: "La Shoah (génocide de 6 millions de Juifs par les nazis) est enseignée pour transmettre la mémoire, comprendre comment la haine peut mener au pire, et lutter contre l'antisémitisme et toutes les formes de racisme. C'est un devoir de mémoire pour que cela ne se reproduise jamais." },
    { id:"db-4-085", t:4, lvl:"B2", q: "Depuis quand les Français élisent-ils le Président de la République au suffrage universel direct ?", o: ["1848", "1958", "1962", "1981"], c: 2, e: "Depuis 1962, les Français élisent leur Président au suffrage universel direct, suite à un référendum voulu par le général de Gaulle. Avant cela, le Président était élu par un collège de grands électeurs. Cette réforme a renforcé la légitimité démocratique du Président." },
    { id:"db-4-086", t:4, lvl:"B1", q: "Quelle est la première étape de la construction européenne en 1951 ?", o: ["L'euro", "La CECA (Communauté Européenne du Charbon et de l'Acier)", "L'Union européenne", "L'espace Schengen"], c: 1, e: "La CECA (Communauté Européenne du Charbon et de l'Acier), créée en 1951 par le traité de Paris, est la première étape de la construction européenne. Six pays (France, Allemagne, Italie, Belgique, Pays-Bas, Luxembourg) ont mis en commun leurs ressources pour garantir la paix." },
    { id:"db-4-087", t:4, lvl:"B2", q: "Durant le mandat de quel président la peine de mort a-t-elle été abolie en France ?", o: ["Charles de Gaulle", "Valéry Giscard d'Estaing", "François Mitterrand", "Jacques Chirac"], c: 2, e: "La peine de mort a été abolie en France le 9 octobre 1981 sous la présidence de François Mitterrand, grâce à l'action du garde des Sceaux Robert Badinter. La France a été l'un des derniers pays d'Europe occidentale à abolir ce châtiment. C'est une avancée majeure pour les droits humains." },
    { id:"db-4-088", t:4, lvl:"B1", q: "Quel régime politique a été instauré en France en 1792 pendant la Révolution ?", o: ["L'Empire", "La Monarchie constitutionnelle", "La Première République", "La dictature"], c: 2, e: "La Première République française a été proclamée le 22 septembre 1792, après l'abolition de la monarchie. C'est la première fois que la France adopte un régime républicain. Elle a duré jusqu'en 1804, date à laquelle Napoléon a instauré l'Empire." },
    { id:"db-4-089", t:4, lvl:"B2", q: "Qui était une figure emblématique de la Résistance française pendant la Seconde Guerre mondiale ?", o: ["Napoléon Bonaparte", "Jean Moulin", "Louis XIV", "Charlemagne"], c: 1, e: "Jean Moulin (1899-1943) est l'une des figures les plus emblématiques de la Résistance française. Préfet révoqué par Vichy, il a unifié les mouvements de résistance sous l'autorité du général de Gaulle. Arrêté et torturé par la Gestapo, il est mort sans avoir parlé. Il repose au Panthéon." },
    { id:"db-4-090", t:4, lvl:"B1", q: "En 1944, qu'est-ce qui a changé pour les femmes françaises ?", o: ["Elles ont perdu leurs droits", "Elles ont obtenu le droit de vote", "Elles ont dû porter un uniforme", "Rien n'a changé"], c: 1, e: "En 1944, les femmes françaises ont obtenu le droit de vote et d'éligibilité, grâce à une ordonnance du général de Gaulle. Elles ont voté pour la première fois en avril 1945 lors des élections municipales. C'était une avancée majeure pour l'égalité des droits." },
    { id:"db-4-091", t:4, lvl:"B1", q: "Quelle organisation internationale a été créée en 1945 après la Seconde Guerre mondiale ?", o: ["L'Union européenne", "L'ONU (Organisation des Nations Unies)", "L'OTAN", "Le G7"], c: 1, e: "L'ONU (Organisation des Nations Unies) a été créée en 1945 pour maintenir la paix mondiale après les horreurs de la Seconde Guerre mondiale. Son siège est à New York. La France est l'un des cinq membres permanents du Conseil de sécurité avec droit de veto." },
    { id:"db-4-092", t:4, lvl:"B1", q: "Quelle peine a été abolie en France en 1981 ?", o: ["La prison à vie", "La peine de mort", "Les travaux forcés", "L'amende"], c: 1, e: "La peine de mort (peine capitale) a été abolie en France le 9 octobre 1981. Robert Badinter, garde des Sceaux, a porté ce projet devant l'Assemblée nationale. Depuis, la France défend l'abolition universelle de la peine de mort dans le monde." },
    { id:"db-4-093", t:4, lvl:"B1", q: "En quelle année l'euro est-il devenu la monnaie utilisée au quotidien en France ?", o: ["1992", "1999", "2002", "2010"], c: 2, e: "Les pièces et billets en euros sont entrés en circulation le 1er janvier 2002, remplaçant le franc français. L'euro existait depuis 1999 pour les transactions bancaires. Aujourd'hui, 20 pays de l'Union européenne utilisent l'euro comme monnaie commune." },
    { id:"db-4-094", t:4, lvl:"B1", q: "En quelle année a commencé la Première Guerre mondiale ?", o: ["1870", "1914", "1939", "1945"], c: 1, e: "La Première Guerre mondiale a commencé en 1914 et s'est terminée en 1918. Ce conflit a fait environ 10 millions de morts, dont 1,4 million de Français. L'armistice a été signé le 11 novembre 1918, date commémorée chaque année en France." },
    { id:"db-4-095", t:4, lvl:"B1", q: "Où a eu lieu le débarquement allié du 6 juin 1944 ?", o: ["En Provence", "En Normandie", "En Bretagne", "À Paris"], c: 1, e: "Le débarquement du 6 juin 1944 (D-Day) a eu lieu sur les plages de Normandie. C'est la plus grande opération militaire de l'histoire, qui a permis la libération de la France et de l'Europe de l'occupation nazie. Les plages du débarquement sont inscrites au patrimoine mondial." },
    { id:"db-4-096", t:4, lvl:"B2", q: "Quel continent a été le plus concerné par la décolonisation française après 1945 ?", o: ["L'Amérique", "L'Afrique", "L'Asie", "L'Océanie"], c: 1, e: "L'Afrique a été le continent le plus concerné par la décolonisation française. La plupart des colonies africaines (Algérie, Sénégal, Côte d'Ivoire, etc.) ont obtenu leur indépendance entre 1954 et 1962. L'Indochine (Asie) avait obtenu son indépendance en 1954 après la guerre d'Indochine." },
    { id:"db-4-097", t:4, lvl:"B1", q: "Que commémore-t-on le 8 mai en France ?", o: ["La prise de la Bastille", "La victoire de 1945 et la fin de la Seconde Guerre mondiale en Europe", "L'armistice de 1918", "La fête du Travail"], c: 1, e: "Le 8 mai commémore la victoire des Alliés sur l'Allemagne nazie et la fin de la Seconde Guerre mondiale en Europe (8 mai 1945). C'est un jour férié en France. Des cérémonies sont organisées devant les monuments aux morts pour honorer les combattants et les victimes." },
    { id:"db-4-098", t:4, lvl:"B1", q: "Lequel de ces personnages historiques a un lien direct avec la République française ?", o: ["Napoléon III empereur", "Marianne, symbole de la République", "Louis XIV roi", "Charlemagne empereur"], c: 1, e: "Marianne est le symbole de la République française. Son buste est présent dans toutes les mairies. Elle incarne les valeurs de Liberté, Égalité, Fraternité. Les autres personnages (Napoléon III, Louis XIV, Charlemagne) représentent des régimes monarchiques ou impériaux, pas la République." },

    // === QUESTIONS COMPLÉMENTAIRES - GÉOGRAPHIE (Questions 101-115) ===
    { id:"db-4-099", t:4, lvl:"B1", q: "Quelle mer se situe entre la France et l'Angleterre ?", o: ["La mer Méditerranée", "La Manche", "La mer du Nord", "L'océan Atlantique"], c: 1, e: "La Manche est la mer qui sépare la France de l'Angleterre. Large de 30 à 250 km, elle relie l'océan Atlantique à la mer du Nord. Le tunnel sous la Manche, inauguré en 1994, permet de relier la France au Royaume-Uni en train." },
    { id:"db-4-100", t:4, lvl:"B1", q: "Qu'est-ce que la France d'outre-mer ?", o: ["Les régions frontalières", "Les territoires français situés hors d'Europe", "Les anciennes colonies", "Les ambassades françaises"], c: 1, e: "La France d'outre-mer désigne l'ensemble des territoires français situés hors de l'Europe continentale : les DROM (Guadeloupe, Martinique, Guyane, La Réunion, Mayotte) et les collectivités d'outre-mer (Polynésie, Nouvelle-Calédonie, etc.). Leurs habitants sont citoyens français." },
    { id:"db-4-101", t:4, lvl:"B1", q: "Quelle chaîne de montagnes sépare la France de l'Espagne ?", o: ["Les Alpes", "Les Pyrénées", "Le Jura", "Les Vosges"], c: 1, e: "Les Pyrénées forment une chaîne de montagnes longue de 430 km qui marque la frontière naturelle entre la France et l'Espagne. Le pic d'Aneto (3 404 m) côté espagnol et le Vignemale (3 298 m) côté français en sont les plus hauts sommets." },
    { id:"db-4-102", t:4, lvl:"B1", q: "Quelle île française se trouve dans l'océan Indien ?", o: ["La Guadeloupe", "La Martinique", "La Réunion", "La Corse"], c: 2, e: "La Réunion est un département français situé dans l'océan Indien, à l'est de Madagascar. Mayotte, également dans l'océan Indien, est aussi un département français. La Guadeloupe et la Martinique sont dans les Caraïbes (océan Atlantique)." },
    { id:"db-4-103", t:4, lvl:"B1", q: "Quelle est la population approximative de la France en 2025 ?", o: ["45 millions", "68 millions", "100 millions", "150 millions"], c: 1, e: "La France compte environ 68 millions d'habitants en 2025, ce qui en fait le deuxième pays le plus peuplé de l'Union européenne après l'Allemagne. La population se concentre dans les grandes métropoles : Paris, Lyon, Marseille, Toulouse, Lille." },
    { id:"db-4-104", t:4, lvl:"B1", q: "Quel fleuve traverse Paris ?", o: ["La Loire", "Le Rhône", "La Seine", "La Garonne"], c: 2, e: "La Seine traverse Paris d'est en ouest. Ce fleuve de 777 km prend sa source en Bourgogne et se jette dans la Manche au Havre. Les quais de Seine à Paris sont classés au patrimoine mondial de l'UNESCO. De nombreux monuments bordent ses rives." },
    { id:"db-4-105", t:4, lvl:"B1", q: "Quel pays a une frontière terrestre avec la France au nord-est ?", o: ["L'Espagne", "L'Italie", "La Belgique", "La Suisse"], c: 2, e: "La Belgique partage une frontière terrestre avec la France au nord-est (620 km). Les autres pays frontaliers au nord-est sont le Luxembourg et l'Allemagne. L'Espagne est au sud-ouest, l'Italie et la Suisse au sud-est." },
    { id:"db-4-106", t:4, lvl:"B1", q: "Où habite la majorité des Français ?", o: ["À la campagne", "Dans les villes et zones urbaines", "En montagne", "Sur les côtes uniquement"], c: 1, e: "La grande majorité des Français (environ 80%) habite dans des zones urbaines. Les grandes métropoles (Paris, Lyon, Marseille, Toulouse, Lille) concentrent population, emplois et services. La France connaît un phénomène d'exode rural depuis le XIXe siècle." },
    { id:"db-4-107", t:4, lvl:"B2", q: "Quelle région française est la plus peuplée ?", o: ["La Provence-Alpes-Côte d'Azur", "L'Île-de-France", "L'Occitanie", "Les Hauts-de-France"], c: 1, e: "L'Île-de-France est la région la plus peuplée de France avec environ 12 millions d'habitants, soit près de 18% de la population française. Elle comprend Paris et sa banlieue. C'est aussi le principal centre économique du pays." },
    { id:"db-4-108", t:4, lvl:"B1", q: "Quelle ville française fait partie des 10 plus grandes métropoles du pays ?", o: ["Chartres", "Lyon", "Avignon", "Biarritz"], c: 1, e: "Lyon est la deuxième ou troisième métropole de France (après Paris et selon les classements, Marseille). Les 10 plus grandes métropoles sont : Paris, Lyon, Marseille, Toulouse, Lille, Bordeaux, Nice, Nantes, Strasbourg et Rennes." },
    { id:"db-4-109", t:4, lvl:"B2", q: "Quel département français est le plus visité par les touristes ?", o: ["Le Finistère", "Paris (75)", "Les Alpes-Maritimes", "La Gironde"], c: 1, e: "Paris et son département (75) est de loin le plus visité par les touristes en France et l'un des plus visités au monde. La Tour Eiffel, le Louvre, Notre-Dame attirent des millions de visiteurs. Les Alpes-Maritimes (Nice, Cannes) et la Gironde (Bordeaux) suivent." },
    { id:"db-4-110", t:4, lvl:"B1", q: "Quand peut-on visiter gratuitement certains musées et monuments en France ?", o: ["Jamais", "Le premier dimanche du mois pour beaucoup de musées nationaux", "Tous les jours", "Uniquement le 14 juillet"], c: 1, e: "De nombreux musées nationaux (Louvre, Orsay, etc.) sont gratuits le premier dimanche de chaque mois. Les moins de 26 ans résidant dans l'UE bénéficient souvent de la gratuité. Les Journées du Patrimoine (3e week-end de septembre) ouvrent gratuitement de nombreux sites." },
    { id:"db-4-111", t:4, lvl:"B1", q: "Lequel de ces pays partage une frontière terrestre avec la France métropolitaine ?", o: ["Le Portugal", "La Suisse", "Les Pays-Bas", "Le Royaume-Uni"], c: 1, e: "La Suisse partage une frontière terrestre avec la France (573 km). Les 8 pays frontaliers de la France métropolitaine sont : Belgique, Luxembourg, Allemagne, Suisse, Italie, Monaco, Espagne et Andorre. Le Royaume-Uni est séparé par la Manche." },

    // === QUESTIONS COMPLÉMENTAIRES - CULTURE (Questions 116-130) ===
    { id:"db-4-112", t:4, lvl:"B2", q: "Qui était Marguerite Yourcenar ?", o: ["Une chanteuse", "La première femme élue à l'Académie française, écrivaine", "Une reine", "Une scientifique"], c: 1, e: "Marguerite Yourcenar (1903-1987) fut la première femme élue à l'Académie française en 1980. Écrivaine majeure du XXe siècle, elle est l'auteure des 'Mémoires d'Hadrien' et de 'L'Œuvre au Noir'. Son élection a marqué une étape importante pour l'égalité femmes-hommes." },
    { id:"db-4-113", t:4, lvl:"B1", q: "Qui était Auguste Rodin ?", o: ["Un peintre impressionniste", "Un sculpteur célèbre, auteur du 'Penseur'", "Un compositeur", "Un architecte"], c: 1, e: "Auguste Rodin (1840-1917) est l'un des plus grands sculpteurs français. Ses œuvres les plus célèbres sont 'Le Penseur', 'Le Baiser' et 'Les Bourgeois de Calais'. Le musée Rodin à Paris présente ses créations. Il a révolutionné la sculpture moderne." },
    { id:"db-4-114", t:4, lvl:"B1", q: "Quel peintre français est célèbre pour ses nymphéas et son jardin de Giverny ?", o: ["Auguste Renoir", "Paul Cézanne", "Claude Monet", "Edgar Degas"], c: 2, e: "Claude Monet (1840-1926) est célèbre pour ses tableaux de nymphéas peints dans son jardin de Giverny en Normandie. Fondateur de l'impressionnisme, il a révolutionné la peinture. Son jardin et sa maison se visitent aujourd'hui." },
    { id:"db-4-115", t:4, lvl:"B2", q: "Qui était Auguste Renoir ?", o: ["Un sculpteur", "Un peintre impressionniste célèbre pour ses portraits et scènes de vie", "Un musicien", "Un écrivain"], c: 1, e: "Auguste Renoir (1841-1919) est l'un des grands maîtres de l'impressionnisme français. Il est célèbre pour ses portraits lumineux, ses scènes de vie parisienne et ses nus féminins. 'Le Bal du moulin de la Galette' et 'Le Déjeuner des canotiers' sont parmi ses œuvres les plus connues." },
    { id:"db-4-116", t:4, lvl:"B1", q: "Quel musée parisien est dédié à l'art impressionniste ?", o: ["Le Louvre", "Le musée d'Orsay", "Le Centre Pompidou", "Le musée Rodin"], c: 1, e: "Le musée d'Orsay, installé dans une ancienne gare, est consacré à l'art occidental de 1848 à 1914, notamment l'impressionnisme. On y trouve des œuvres de Monet, Renoir, Van Gogh, Cézanne, Degas. C'est l'un des musées les plus visités de France." },
    { id:"db-4-117", t:4, lvl:"B2", q: "Quel est le rang de la langue française parmi les langues les plus parlées dans le monde ?", o: ["2e", "5e", "10e", "15e"], c: 1, e: "Le français est la 5e langue la plus parlée dans le monde (environ 321 millions de locuteurs). Elle est présente sur les 5 continents et est langue officielle dans 29 pays. C'est aussi une langue officielle de nombreuses organisations internationales (ONU, UE, CIO)." },
    { id:"db-4-118", t:4, lvl:"B1", q: "Quelle cathédrale célèbre a été partiellement détruite par un incendie en 2019 ?", o: ["La cathédrale de Chartres", "Notre-Dame de Paris", "La cathédrale de Reims", "La cathédrale de Strasbourg"], c: 1, e: "Notre-Dame de Paris, chef-d'œuvre de l'art gothique, a été ravagée par un incendie le 15 avril 2019. La flèche et la toiture ont été détruites. Une reconstruction à l'identique a été entreprise. La cathédrale a rouvert en décembre 2024 après 5 ans de travaux." },
    { id:"db-4-119", t:4, lvl:"B2", q: "Qui était une célèbre écrivaine française du XIXe siècle ayant utilisé un pseudonyme masculin ?", o: ["Simone de Beauvoir", "George Sand", "Marguerite Duras", "Colette"], c: 1, e: "George Sand (1804-1876), de son vrai nom Amantine Aurore Lucile Dupin, a utilisé un pseudonyme masculin pour publier ses romans. Elle a été une pionnière du féminisme, portant le pantalon et vivant librement. Elle a écrit 'La Mare au Diable' et 'La Petite Fadette'." },
    { id:"db-4-120", t:4, lvl:"B2", q: "Qui était un célèbre compositeur français de musique classique ?", o: ["Wolfgang Mozart", "Claude Debussy", "Ludwig van Beethoven", "Johann Sebastian Bach"], c: 1, e: "Claude Debussy (1862-1918) est l'un des plus grands compositeurs français. Créateur de l'impressionnisme musical, il a composé 'Clair de Lune', 'La Mer' et 'Prélude à l'après-midi d'un faune'. Maurice Ravel et Hector Berlioz sont d'autres grands compositeurs français." },
    { id:"db-4-121", t:4, lvl:"B1", q: "Quelle fête traditionnelle française a lieu le 2 février ?", o: ["La Chandeleur (crêpes)", "Pâques", "Noël", "La Toussaint"], c: 0, e: "La Chandeleur est célébrée le 2 février en France. C'est traditionnellement le jour où l'on fait des crêpes. Selon la tradition, il faut faire sauter les crêpes de la main droite en tenant une pièce dans la main gauche pour attirer la prospérité." },
    { id:"db-4-122", t:4, lvl:"B1", q: "Quand célèbre-t-on Noël en France ?", o: ["Le 31 décembre", "Le 25 décembre", "Le 1er janvier", "Le 6 janvier"], c: 1, e: "Noël est célébré le 25 décembre en France. C'est un jour férié où les familles se réunissent pour un repas festif et l'échange de cadeaux. Bien que d'origine religieuse (naissance de Jésus-Christ), Noël est célébré par une grande partie de la population, croyante ou non." },
    { id:"db-4-123", t:4, lvl:"B1", q: "Qui était Paul Cézanne ?", o: ["Un écrivain", "Un peintre post-impressionniste, précurseur de l'art moderne", "Un sculpteur", "Un musicien"], c: 1, e: "Paul Cézanne (1839-1906) était un peintre français post-impressionniste, considéré comme le père de l'art moderne. Ses natures mortes, paysages de Provence et représentations de la montagne Sainte-Victoire ont influencé le cubisme. Il a ouvert la voie à Picasso et Braque." },
    { id:"db-4-124", t:4, lvl:"B2", q: "Qui était Marc Chagall ?", o: ["Un architecte", "Un peintre d'origine russe naturalisé français, aux œuvres colorées et oniriques", "Un écrivain", "Un cinéaste"], c: 1, e: "Marc Chagall (1887-1985) était un peintre d'origine russe naturalisé français. Ses œuvres colorées et poétiques mêlent folklore russe, tradition juive et modernité. Il a réalisé le plafond de l'Opéra de Paris et des vitraux pour des cathédrales du monde entier." },
    { id:"db-4-125", t:4, lvl:"B1", q: "Qui était Joséphine Baker ?", o: ["Une reine", "Une artiste franco-américaine, résistante et militante des droits civiques", "Une scientifique", "Une sportive"], c: 1, e: "Joséphine Baker (1906-1975) était une artiste franco-américaine, chanteuse et danseuse devenue star à Paris dans les années 1920. Résistante pendant la Seconde Guerre mondiale, militante pour les droits civiques, elle a été panthéonisée en 2021, première femme noire à entrer au Panthéon." },

    // === QUESTIONS COMPLÉMENTAIRES - COUVERTURE OFFICIELLE (Thème 4) ===
    { id:"db-4-126", t:4, lvl:"B1", q: "Qui était Charles Baudelaire ?", o: ["Un peintre impressionniste", "Un poète, auteur des 'Fleurs du mal'", "Un compositeur de musique classique", "Un homme politique de la Révolution"], c: 1, e: "Charles Baudelaire (1821-1867) était un poète français, auteur du recueil 'Les Fleurs du mal' (1857), considéré comme l'un des textes fondateurs de la poésie moderne. Par son style novateur et ses thèmes audacieux, il a profondément influencé la littérature française et mondiale." },
    { id:"db-4-127", t:4, lvl:"B1", q: "Qui était Albert Camus ?", o: ["Un musicien", "Un écrivain et philosophe, prix Nobel de littérature en 1957", "Un scientifique", "Un général de la Seconde Guerre mondiale"], c: 1, e: "Albert Camus (1913-1960) était un écrivain et philosophe français né en Algérie. Auteur de 'L'Étranger' et 'La Peste', il a reçu le prix Nobel de littérature en 1957. Engagé contre l'injustice, il reste l'un des intellectuels français les plus lus et traduits dans le monde." },
    { id:"db-4-128", t:4, lvl:"B1", q: "Qui était Jean de La Fontaine ?", o: ["Un roi de France", "Un poète célèbre pour ses fables animalières", "Un peintre de la Renaissance", "Un explorateur"], c: 1, e: "Jean de La Fontaine (1621-1695) était un poète français célèbre pour ses Fables, comme 'Le Corbeau et le Renard' ou 'La Cigale et la Fourmi'. Ses textes, qui mettent en scène des animaux pour donner des leçons de morale, font partie du patrimoine littéraire français appris dès l'école primaire." },
    { id:"db-4-129", t:4, lvl:"B2", q: "Qui était Simone de Beauvoir ?", o: ["Une chanteuse populaire", "Une philosophe et écrivaine féministe, auteure du 'Deuxième Sexe'", "Une scientifique prix Nobel", "Une reine de France"], c: 1, e: "Simone de Beauvoir (1908-1986) était une philosophe et écrivaine française, figure majeure du féminisme. Son essai 'Le Deuxième Sexe' (1949) est un texte fondateur de la pensée féministe moderne. Compagne de Jean-Paul Sartre, elle a défendu toute sa vie l'émancipation des femmes et l'égalité des droits." },
    { id:"db-4-130", t:4, lvl:"B1", q: "Quel était le surnom de Louis XIV ?", o: ["Le roi philosophe", "Le Roi-Soleil", "Le roi des rois", "Le roi bâtisseur"], c: 1, e: "Louis XIV (1638-1715) était surnommé le 'Roi-Soleil' car il se comparait au soleil qui éclaire et nourrit tout. Il a régné 72 ans, incarné la monarchie absolue et fait construire le château de Versailles, symbole de sa puissance et de son faste." },
    { id:"db-4-131", t:4, lvl:"B1", q: "Quel océan borde la côte ouest de la France ?", o: ["L'océan Indien", "L'océan Atlantique", "L'océan Pacifique", "La mer Méditerranée"], c: 1, e: "L'océan Atlantique borde toute la côte ouest de la France, de la Bretagne au Pays basque. Cette façade maritime, longue de plus de 2 000 km, abrite de grands ports comme Nantes-Saint-Nazaire et Bordeaux. La France possède la deuxième plus grande zone maritime au monde grâce à ses territoires ultramarins." },
    { id:"db-4-132", t:4, lvl:"B1", q: "Où se situe la Corse ?", o: ["Dans l'océan Atlantique", "En mer Méditerranée, au sud-est de la France continentale", "Dans la Manche", "En mer du Nord"], c: 1, e: "La Corse est une île française située en mer Méditerranée, au sud-est de la France continentale et au nord de la Sardaigne (Italie). Surnommée 'l'Île de Beauté', elle est une collectivité territoriale à statut particulier. Napoléon Bonaparte y est né en 1769, à Ajaccio." },
    { id:"db-4-133", t:4, lvl:"B2", q: "Quel pays a été colonisé par la France ?", o: ["L'Angleterre", "L'Algérie", "L'Allemagne", "L'Espagne"], c: 1, e: "L'Algérie a été colonisée par la France de 1830 à 1962. La France a possédé un vaste empire colonial incluant aussi le Sénégal, la Côte d'Ivoire, le Maroc, la Tunisie, Madagascar, l'Indochine (Vietnam, Laos, Cambodge) et d'autres territoires. La décolonisation s'est achevée dans les années 1960." },
    { id:"db-4-134", t:4, lvl:"B1", q: "Paris est la capitale de la France. Qu'est-ce qui la caractérise aussi ?", o: ["C'est la plus petite ville de France", "C'est la plus grande ville de France par sa population", "Elle ne compte aucun monument", "Elle est située au bord de la mer"], c: 1, e: "Paris est à la fois la capitale et la plus grande ville de France, avec plus de 2 millions d'habitants intra-muros et 12 millions dans l'agglomération. Centre politique, économique et culturel du pays, elle abrite de nombreux monuments (Tour Eiffel, Louvre, Notre-Dame) et accueille chaque année des millions de touristes." },
    { id:"db-4-135", t:4, lvl:"B1", q: "Quel grand musée parisien est mondialement connu pour abriter la Joconde de Léonard de Vinci ?", o: ["Le musée d'Orsay", "Le Louvre", "Le Centre Pompidou", "Le musée Rodin"], c: 1, e: "Le Louvre est le plus grand et le plus visité des musées du monde, avec près de 10 millions de visiteurs par an. Ancien palais royal, il abrite la Joconde de Léonard de Vinci, la Vénus de Milo et des milliers d'œuvres couvrant plusieurs millénaires d'art. Il se trouve au cœur de Paris." },
    
    // === S'INSTALLER ET RÉSIDER EN FRANCE (Questions 1-15) ===
    { id:"db-5-001", t:5, lvl:"B1", q: "Faut-il déclarer son changement d'adresse quand on déménage en France ?", o: ["Non, ce n'est pas nécessaire", "Oui, il faut informer les administrations (impôts, CAF, préfecture, etc.)", "Seulement si on change de région", "Seulement après 6 mois"], c: 1, e: "Oui, lors d'un déménagement, il est obligatoire de déclarer son changement d'adresse à plusieurs administrations : impôts, CAF, sécurité sociale, préfecture (pour le titre de séjour), employeur, banque, assurances. Cela garantit que vous recevez vos courriers importants et vos droits." },
    { id:"db-5-002", t:5, lvl:"B1", q: "Qu'est-ce qu'une assurance responsabilité civile ?", o: ["Une assurance pour la voiture", "Une assurance obligatoire couvrant les dommages causés à autrui", "Une assurance santé", "Une assurance vie"], c: 1, e: "L'assurance responsabilité civile couvre les dommages matériels ou corporels que vous pourriez causer à des tiers (autres personnes). Elle est obligatoire pour certaines activités et souvent incluse dans l'assurance habitation. Elle protège votre responsabilité financière en cas d'accident." },
    { id:"db-5-003", t:5, lvl:"B2", q: "Un étranger titulaire d'un permis de conduire étranger peut-il conduire en France ?", o: ["Non, jamais", "Oui temporairement, puis il doit l'échanger ou le faire reconnaître", "Oui, définitivement", "Non, il doit tout repasser"], c: 1, e: "Un étranger peut conduire temporairement en France avec son permis étranger (durée variable selon le pays). S'il s'installe durablement, il doit demander l'échange de son permis contre un permis français (si accord bilatéral) ou repasser l'examen. Le permis doit être en cours de validité et traduit si nécessaire." },
    { id:"db-5-004", t:5, lvl:"B1", q: "Qu'est-ce qu'un titre de séjour ?", o: ["Un billet de train", "Un document autorisant un étranger à résider légalement en France", "Une carte d'identité", "Un passeport"], c: 1, e: "Un titre de séjour est un document officiel délivré par la préfecture qui autorise un étranger à résider légalement en France. Il existe différents types selon la situation : étudiant, salarié, vie privée et familiale, carte de résident. Il doit être renouvelé avant expiration." },
    { id:"db-5-005", t:5, lvl:"B2", q: "Combien de temps avant l'expiration faut-il renouveler son titre de séjour ?", o: ["Le jour même de l'expiration", "2 à 3 mois avant l'expiration", "1 an avant", "Après l'expiration"], c: 1, e: "Il faut déposer une demande de renouvellement de titre de séjour 2 à 3 mois avant son expiration (délai variable selon les préfectures). Attendre l'expiration expose à une situation irrégulière. La préfecture délivre un récépissé en attendant le nouveau titre." },
    { id:"db-5-006", t:5, lvl:"B1", q: "Qu'est-ce que la naturalisation ?", o: ["Un traitement médical", "La procédure permettant à un étranger d'acquérir la nationalité française", "Un voyage", "Un diplôme"], c: 1, e: "La naturalisation est la procédure par laquelle un étranger peut demander à devenir français. Elle nécessite de remplir plusieurs conditions : résidence stable en France (généralement 5 ans), intégration (langue, valeurs), ressources suffisantes. L'administration vérifie l'assimilation à la communauté française." },
    { id:"db-5-007", t:5, lvl:"B2", q: "Quel est le principe d'assimilation pour la naturalisation ?", o: ["Oublier sa culture d'origine", "Maîtriser le français (B1), connaître l'histoire et adhérer aux valeurs républicaines", "Changer de religion", "Changer de nom"], c: 1, e: "L'assimilation implique : maîtriser la langue française (niveau B1 oral et écrit), avoir une connaissance suffisante de l'histoire, de la culture et de la société françaises, et adhérer aux principes et valeurs de la République. On peut conserver sa culture d'origine tout en adoptant les valeurs françaises." },
    { id:"db-5-008", t:5, lvl:"B1", q: "Où doit-on déclarer une naissance en France ?", o: ["À l'hôpital uniquement", "À la mairie du lieu de naissance dans les 5 jours", "À la préfecture", "Sur internet"], c: 1, e: "Une naissance doit être déclarée à la mairie du lieu de naissance dans les 5 jours suivant l'accouchement (délai de 3 jours si l'accouchement a lieu dans une maternité). C'est généralement le père ou un proche qui fait cette déclaration. L'hôpital fournit un certificat médical." },
    { id:"db-5-009", t:5, lvl:"B1", q: "Où doit-on déclarer un mariage en France ?", o: ["À l'église", "À la mairie, seul le mariage civil est reconnu par l'État", "Chez un notaire", "À la préfecture"], c: 1, e: "En France, seul le mariage civil célébré à la mairie par un officier d'état civil (maire ou adjoint) est reconnu légalement par l'État. Le mariage religieux est facultatif mais doit obligatoirement avoir lieu après le mariage civil. La mairie délivre un livret de famille." },
    { id:"db-5-010", t:5, lvl:"B2", q: "Qu'est-ce que la CAF et quel est son rôle ?", o: ["Une banque", "La Caisse d'Allocations Familiales qui verse des aides sociales et familiales", "Une assurance", "Un syndicat"], c: 1, e: "La CAF (Caisse d'Allocations Familiales) est un organisme public qui verse diverses prestations sociales selon la situation familiale et les revenus : allocations familiales, aide au logement (APL, ALF), RSA, prime d'activité, complément familial, etc. Elle soutient les familles et les personnes en difficulté." },
    { id:"db-5-011", t:5, lvl:"B1", q: "Qu'est-ce que le RSA ?", o: ["Un diplôme", "Le Revenu de Solidarité Active, une aide pour les personnes sans ressources", "Une taxe", "Un impôt"], c: 1, e: "Le RSA (Revenu de Solidarité Active) est une allocation versée par la CAF aux personnes sans ressources ou avec de faibles revenus, pour garantir un minimum vital. Il est ouvert aux plus de 25 ans (ou jeunes avec enfant) sous conditions de résidence. Son montant varie selon la composition familiale." },
    { id:"db-5-012", t:5, lvl:"B1", q: "Qu'est-ce qu'une aide au logement (APL, ALF) ?", o: ["Un prêt immobilier", "Une aide financière pour payer le loyer ou rembourser un prêt immobilier", "Une assurance habitation", "Un bail"], c: 1, e: "Les aides au logement (APL, ALF, ALS) sont des prestations versées par la CAF ou la MSA pour réduire le montant du loyer ou des remboursements d'emprunt immobilier. Leur montant dépend des ressources, de la composition familiale, du loyer et de la zone géographique." },
    { id:"db-5-013", t:5, lvl:"B2", q: "Qu'est-ce qu'un bail de location ?", o: ["Un permis de conduire", "Un contrat entre propriétaire et locataire fixant les conditions de location", "Une assurance", "Un crédit"], c: 1, e: "Le bail de location (ou contrat de location) est un contrat écrit signé entre le propriétaire (bailleur) et le locataire qui fixe : le montant du loyer et des charges, la durée de location (minimum 3 ans pour location vide), le dépôt de garantie, les obligations de chacun. C'est un document juridique important." },
    { id:"db-5-014", t:5, lvl:"B1", q: "Quelles sont les obligations principales d'un locataire ?", o: ["Aucune obligation", "Payer le loyer, entretenir le logement, respecter le règlement et le voisinage", "Seulement payer le loyer", "Seulement nettoyer"], c: 1, e: "Le locataire doit : payer le loyer et les charges à temps, entretenir le logement et faire les petites réparations, respecter le règlement intérieur de l'immeuble, ne pas nuire au voisinage (bruit, comportement), souscrire une assurance habitation, et prévenir le propriétaire de tout problème grave." },
    { id:"db-5-015", t:5, lvl:"B2", q: "Qu'est-ce que le dépôt de garantie (caution) dans une location ?", o: ["Un cadeau au propriétaire", "Une somme versée à la signature du bail, restituée en fin de location si tout est en ordre", "Un loyer anticipé", "Une taxe"], c: 1, e: "Le dépôt de garantie (maximum 1 mois de loyer pour une location vide) est une somme versée au propriétaire à la signature du bail. Elle couvre d'éventuels dégâts ou loyers impayés. Si le logement est rendu en bon état, elle doit être restituée sous 1 à 2 mois après le départ." },

    // === ACCÈS AUX SOINS ET SANTÉ (Questions 16-25) ===
    { id:"db-5-016", t:5, lvl:"B1", q: "Qu'est-ce qu'un médecin traitant ?", o: ["Un médecin à l'hôpital", "Le médecin référent pour le suivi médical, à déclarer pour un meilleur remboursement", "Un médecin gratuit", "Un médecin qui vient à domicile"], c: 1, e: "Le médecin traitant est le médecin que vous choisissez comme référent pour votre suivi médical. Le déclarer à la Sécurité sociale permet un meilleur remboursement des consultations et évite des pénalités financières. Il coordonne votre parcours de soins et vous oriente vers des spécialistes si nécessaire." },
    { id:"db-5-017", t:5, lvl:"B1", q: "Qu'est-ce que la Sécurité sociale (Assurance Maladie) ?", o: ["Une police privée", "Le système public de remboursement des frais de santé", "Une banque", "Un hôpital"], c: 1, e: "La Sécurité sociale (Assurance Maladie) est le système public français qui rembourse une partie des frais de santé (consultations, médicaments, hospitalisation). Elle est financée par les cotisations sociales. Le taux de remboursement varie selon les soins (70% pour une consultation chez le médecin traitant)." },
    { id:"db-5-018", t:5, lvl:"B2", q: "Qu'est-ce qu'une mutuelle santé ?", o: ["Un hôpital", "Une assurance complémentaire qui rembourse ce que la Sécurité sociale ne couvre pas", "Une banque", "Un médicament"], c: 1, e: "Une mutuelle (ou complémentaire santé) est une assurance facultative qui rembourse tout ou partie des frais de santé non couverts par la Sécurité sociale (ticket modérateur, dépassements d'honoraires, optique, dentaire). De nombreux employeurs proposent une mutuelle collective pour leurs salariés." },
    { id:"db-5-019", t:5, lvl:"B1", q: "Où peut-on se faire soigner en France ?", o: ["Seulement à l'hôpital", "Chez le médecin traitant, les spécialistes, à l'hôpital, en clinique, aux urgences", "Uniquement à la pharmacie", "Seulement en clinique privée"], c: 1, e: "On peut se faire soigner : chez son médecin traitant (généraliste), chez des médecins spécialistes, dans les hôpitaux publics, dans les cliniques privées, aux urgences (pour les cas graves), dans les centres de santé. Le parcours de soins coordonné commence par le médecin traitant." },
    { id:"db-5-020", t:5, lvl:"B1", q: "Quels sont les numéros d'urgence médicale en France ?", o: ["17 et 18", "15 (SAMU) et 112 (urgence européenne)", "911", "999"], c: 1, e: "Les numéros d'urgence médicale sont : le 15 (SAMU) pour toute urgence médicale vitale, et le 112 (numéro d'urgence européen) qui fonctionne dans toute l'Europe. Ces numéros sont gratuits et accessibles 24h/24, même sans crédit téléphonique." },
    { id:"db-5-021", t:5, lvl:"B2", q: "Qu'est-ce que le parcours de soins coordonné ?", o: ["Un marathon", "Consulter d'abord son médecin traitant qui oriente vers un spécialiste pour un meilleur remboursement", "Une visite touristique", "Un traitement médical"], c: 1, e: "Le parcours de soins coordonné consiste à consulter d'abord son médecin traitant qui, si nécessaire, vous oriente vers un spécialiste. Cela permet un meilleur suivi médical et un meilleur remboursement par la Sécurité sociale. Consulter directement un spécialiste sans passer par le médecin traitant entraîne une baisse de remboursement." },
    { id:"db-5-022", t:5, lvl:"B1", q: "Quelles sont les obligations vaccinales en France ?", o: ["Aucune obligation", "11 vaccins obligatoires pour les enfants nés depuis 2018", "Seulement pour les adultes", "Uniquement contre la grippe"], c: 1, e: "En France, 11 vaccins sont obligatoires pour tous les enfants nés depuis le 1er janvier 2018 : diphtérie, tétanos, poliomyélite, coqueluche, rougeole, oreillons, rubéole, hépatite B, méningocoque C, pneumocoque, Haemophilus influenzae B. Ces vaccins protègent contre des maladies graves et sont gratuits." },
    { id:"db-5-023", t:5, lvl:"B2", q: "Quels sont les droits du patient en France ?", o: ["Aucun droit", "Droit au libre choix du praticien, à l'information, au respect du secret médical, au consentement", "Seulement payer", "Obéir sans question"], c: 1, e: "Les droits du patient incluent : le libre choix de son médecin et établissement de santé, le droit à l'information claire sur son état et les traitements, le respect du secret médical (confidentialité), le droit de consentir ou refuser un traitement (sauf urgence vitale), l'accès à son dossier médical." },
    { id:"db-5-024", t:5, lvl:"B1", q: "Un médecin peut-il révéler des informations sur votre santé à votre famille sans votre accord ?", o: ["Oui, toujours", "Non, sauf si vous l'autorisez, c'est le secret médical", "Oui, pour les parents", "Oui, pour le conjoint"], c: 1, e: "Non, le médecin est tenu au secret médical. Il ne peut révéler aucune information sur votre santé à quiconque (même votre famille) sans votre consentement explicite. C'est un principe fondamental qui protège votre vie privée et la confiance dans la relation médicale." },
    { id:"db-5-025", t:5, lvl:"B1", q: "Peut-on refuser un traitement médical proposé par un médecin ?", o: ["Non, jamais", "Oui, après information, sauf urgence vitale avec impossibilité de recueillir le consentement", "Non, on doit toujours obéir", "Seulement les traitements chers"], c: 1, e: "Oui, tout patient majeur et conscient peut refuser un traitement après avoir été informé des conséquences. C'est le principe du consentement libre et éclairé. Exception : en cas d'urgence vitale où le patient ne peut pas exprimer sa volonté, le médecin fait ce qui est nécessaire pour le sauver." },

    // === TRAVAILLER EN FRANCE (Questions 26-40) ===
    { id:"db-5-026", t:5, lvl:"B1", q: "Quelle est la durée légale du travail par semaine en France ?", o: ["30 heures", "35 heures", "40 heures", "50 heures"], c: 1, e: "La durée légale du travail est de 35 heures par semaine en France depuis 2000. Au-delà, les heures effectuées sont considérées comme des heures supplémentaires et sont rémunérées avec une majoration. Des accords d'entreprise peuvent prévoir des durées différentes." },
    { id:"db-5-027", t:5, lvl:"B1", q: "Combien de semaines de congés payés minimum un salarié a-t-il par an ?", o: ["2 semaines", "4 semaines", "5 semaines", "8 semaines"], c: 2, e: "Tout salarié en France a droit à un minimum de 5 semaines de congés payés par an (soit 30 jours ouvrables ou 25 jours ouvrés). Ce droit augmente avec l'ancienneté dans certaines entreprises. Les congés payés sont un droit fondamental acquis progressivement au cours de l'année." },
    { id:"db-5-028", t:5, lvl:"B1", q: "Qu'est-ce qu'un CDI ?", o: ["Un diplôme", "Un Contrat à Durée Indéterminée, le contrat de travail standard sans date de fin", "Un CDD", "Un stage"], c: 1, e: "Le CDI (Contrat à Durée Indéterminée) est le contrat de travail standard en France, sans date de fin prédéfinie. Il offre la plus grande stabilité d'emploi et la meilleure protection sociale. C'est la forme normale et générale de la relation de travail." },
    { id:"db-5-029", t:5, lvl:"B1", q: "Qu'est-ce qu'un CDD ?", o: ["Un diplôme", "Un Contrat à Durée Déterminée, un contrat temporaire avec une date de fin", "Un CDI", "Une formation"], c: 1, e: "Le CDD (Contrat à Durée Déterminée) est un contrat de travail temporaire avec une date de fin précise ou liée à un événement (remplacement, surcroît d'activité). Sa durée maximale est généralement de 18 mois. À la fin, le salarié perçoit une prime de précarité de 10% du salaire brut total." },
    { id:"db-5-030", t:5, lvl:"B2", q: "Qu'est-ce que le SMIC ?", o: ["Un diplôme", "Le Salaire Minimum Interprofessionnel de Croissance, le salaire horaire minimum légal", "Une taxe", "Un syndicat"], c: 1, e: "Le SMIC (Salaire Minimum Interprofessionnel de Croissance) est le salaire horaire minimum en dessous duquel aucun salarié ne peut être payé en France. Il est revalorisé chaque année. En 2024, il est d'environ 11,65 euros brut de l'heure (environ 1 767 euros brut par mois pour 35h)." },
    { id:"db-5-031", t:5, lvl:"B1", q: "Où peut-on chercher un emploi en France ?", o: ["Seulement dans les journaux", "À Pôle Emploi, sur internet, dans les agences d'intérim, par réseau", "Nulle part", "Seulement en envoyant des CV au hasard"], c: 1, e: "On peut chercher un emploi : à Pôle Emploi (service public gratuit), sur des sites d'emploi en ligne (Indeed, LinkedIn, LeBonCoin), dans les agences d'intérim, en contactant directement les entreprises, via son réseau professionnel et personnel, dans les salons de l'emploi." },
    { id:"db-5-032", t:5, lvl:"B1", q: "Qu'est-ce que Pôle Emploi ?", o: ["Une école", "Le service public de l'emploi qui aide à trouver un travail et verse des allocations chômage", "Une banque", "Un syndicat"], c: 1, e: "Pôle Emploi est le service public français de l'emploi. Il accompagne les demandeurs d'emploi dans leur recherche (offres, conseils, formations), verse les allocations chômage (ARE) aux personnes éligibles, et aide les entreprises à recruter. L'inscription est gratuite et ouverte à tous." },
    { id:"db-5-033", t:5, lvl:"B2", q: "Qu'est-ce que l'allocation chômage (ARE) ?", o: ["Un salaire", "Une indemnisation temporaire versée aux personnes ayant perdu leur emploi", "Une retraite", "Une bourse"], c: 1, e: "L'ARE (Allocation de Retour à l'Emploi) est une indemnisation versée par Pôle Emploi aux personnes ayant involontairement perdu leur emploi (licenciement, fin de CDD), sous conditions : avoir travaillé suffisamment, être inscrit comme demandeur d'emploi, rechercher activement un travail. Sa durée et son montant dépendent du salaire et de la durée d'emploi antérieure." },
    { id:"db-5-034", t:5, lvl:"B1", q: "Qu'est-ce qu'un bulletin de salaire (fiche de paie) ?", o: ["Une facture", "Un document mensuel détaillant le salaire brut, les cotisations et le salaire net", "Un contrat", "Un diplôme"], c: 1, e: "Le bulletin de salaire (ou fiche de paie) est un document obligatoire remis chaque mois par l'employeur. Il détaille : le salaire brut, toutes les cotisations sociales prélevées (santé, retraite, chômage), et le salaire net versé. Il faut le conserver toute sa vie car il prouve les droits sociaux (retraite, chômage)." },
    { id:"db-5-035", t:5, lvl:"B2", q: "Quelle est la différence entre salaire brut et salaire net ?", o: ["Il n'y a pas de différence", "Le brut est avant cotisations, le net est ce qui est versé sur le compte après prélèvements", "Le net est plus élevé", "Le brut est un bonus"], c: 1, e: "Le salaire brut est le salaire avant déduction des cotisations sociales obligatoires (environ 22-25% pour un salarié). Le salaire net est ce qui est effectivement versé sur votre compte bancaire après prélèvement des cotisations. Sur la fiche de paie, les deux montants apparaissent." },
    { id:"db-5-036", t:5, lvl:"B1", q: "Qu'est-ce qu'un syndicat ?", o: ["Une entreprise", "Une organisation qui défend les droits et intérêts des travailleurs", "Une banque", "Un parti politique"], c: 1, e: "Un syndicat est une organisation de travailleurs qui défend leurs droits et intérêts professionnels : salaires, conditions de travail, protection de l'emploi. Les syndicats négocient avec les employeurs et peuvent organiser des grèves. Tout salarié a le droit d'adhérer librement à un syndicat." },
    { id:"db-5-037", t:5, lvl:"B1", q: "Peut-on être licencié sans raison en France ?", o: ["Oui, à tout moment", "Non, le licenciement doit avoir une cause réelle et sérieuse", "Oui, dans le privé", "Seulement les étrangers"], c: 1, e: "Non, en France, un licenciement doit avoir une cause réelle et sérieuse (motif économique, faute du salarié, inaptitude). Un licenciement sans cause ou abusif peut être contesté devant le conseil de prud'hommes. Le salarié licencié a droit à un préavis et souvent à des indemnités." },
    { id:"db-5-038", t:5, lvl:"B2", q: "Qu'est-ce que le conseil de prud'hommes ?", o: ["Un tribunal administratif", "Un tribunal spécialisé dans les conflits entre employeurs et salariés", "Un syndicat", "Une assurance"], c: 1, e: "Le conseil de prud'hommes est un tribunal spécialisé qui règle les conflits individuels entre employeurs et salariés (licenciement abusif, salaires impayés, harcèlement, etc.). Les juges sont des salariés et employeurs élus. La saisine est gratuite et peut se faire sans avocat." },
    { id:"db-5-039", t:5, lvl:"B1", q: "Qu'est-ce que la formation professionnelle ?", o: ["L'école primaire", "Des formations pour acquérir ou améliorer des compétences professionnelles", "L'université", "Le service militaire"], c: 1, e: "La formation professionnelle permet aux actifs (salariés, demandeurs d'emploi, indépendants) d'acquérir de nouvelles compétences ou de se reconvertir. Elle peut être financée par l'employeur, Pôle Emploi, ou le Compte Personnel de Formation (CPF). C'est un droit tout au long de la vie professionnelle." },
    { id:"db-5-040", t:5, lvl:"B2", q: "Qu'est-ce que le CPF (Compte Personnel de Formation) ?", o: ["Un compte bancaire", "Un compte en euros permettant de financer des formations tout au long de sa carrière", "Une carte bancaire", "Un diplôme"], c: 1, e: "Le CPF est un compte individuel qui accumule des droits à la formation (en euros) tout au long de la carrière professionnelle. Chaque année travaillée crédite le compte. Le salarié peut utiliser son CPF pour financer des formations qualifiantes, un bilan de compétences ou une validation des acquis, sans demander l'accord de son employeur." },

    // === AUTORITÉ PARENTALE ET SYSTÈME ÉDUCATIF (Questions 41-60) ===
    { id:"db-5-041", t:5, lvl:"B1", q: "À partir de quel âge l'instruction est-elle obligatoire en France ?", o: ["5 ans", "3 ans", "6 ans", "7 ans"], c: 1, e: "L'instruction est obligatoire dès 3 ans en France depuis 2019 (âge de l'école maternelle) jusqu'à 16 ans. Les parents ont l'obligation légale de scolariser leur enfant ou d'assurer une instruction à domicile déclarée. C'est un droit fondamental de l'enfant." },
    { id:"db-5-042", t:5, lvl:"B1", q: "Jusqu'à quel âge l'instruction est-elle obligatoire en France ?", o: ["14 ans", "16 ans", "18 ans", "21 ans"], c: 1, e: "L'instruction est obligatoire jusqu'à 16 ans en France. Après 16 ans, le jeune peut choisir de poursuivre ses études (lycée, apprentissage, formation professionnelle) ou d'entrer dans la vie active. La scolarisation n'est plus obligatoire mais l'État encourage la poursuite d'études." },
    { id:"db-5-043", t:5, lvl:"B1", q: "Quels sont les différents niveaux de l'enseignement scolaire en France ?", o: ["Uniquement le collège", "École maternelle, école primaire, collège, lycée", "Seulement l'université", "CP et CM2"], c: 1, e: "Le système éducatif français comprend : l'école maternelle (3-6 ans), l'école primaire ou élémentaire (6-11 ans), le collège (11-15 ans), et le lycée (15-18 ans). Après le lycée, l'enseignement supérieur (université, grandes écoles, BTS, IUT) n'est pas obligatoire mais ouvert à tous." },
    { id:"db-5-044", t:5, lvl:"B1", q: "Qui gère les écoles primaires en France ?", o: ["L'État", "Les communes (mairies)", "Les départements", "Les régions"], c: 1, e: "Les écoles maternelles et primaires sont gérées par les communes (mairies) qui assurent la construction, l'entretien des bâtiments, le personnel non enseignant (cantine, entretien). Les enseignants sont payés par l'État. C'est une compétence de proximité." },
    { id:"db-5-045", t:5, lvl:"B1", q: "Qui gère les collèges en France ?", o: ["Les communes", "Les départements", "Les régions", "L'État seul"], c: 1, e: "Les collèges sont gérés par les départements qui assurent leur construction, leur entretien, leur équipement et le personnel non enseignant. Les enseignants sont des fonctionnaires d'État. Cette répartition des compétences résulte des lois de décentralisation." },
    { id:"db-5-046", t:5, lvl:"B1", q: "Qui gère les lycées en France ?", o: ["Les communes", "Les départements", "Les régions", "Seulement l'État"], c: 2, e: "Les lycées sont gérés par les régions qui assurent leur construction, leur entretien, leur équipement, les transports scolaires et la restauration. Les enseignants sont des fonctionnaires d'État. Les régions jouent un rôle important dans l'orientation et la formation professionnelle des lycéens." },
    { id:"db-5-047", t:5, lvl:"B2", q: "L'école publique est-elle gratuite en France ?", o: ["Non, il faut payer", "Oui, de la maternelle au lycée l'enseignement public est gratuit", "Seulement pour les Français", "Seulement le primaire"], c: 1, e: "Oui, l'école publique est totalement gratuite en France de la maternelle au lycée : pas de frais de scolarité, fourniture des manuels scolaires (au collège et lycée). Les familles paient seulement les fournitures de base, la cantine (avec aides possibles) et les activités extrascolaires facultatives." },
    { id:"db-5-048", t:5, lvl:"B1", q: "Qu'est-ce que l'autorité parentale ?", o: ["Le droit de punir sévèrement", "L'ensemble des droits et devoirs des parents pour protéger, éduquer et élever leur enfant mineur", "Le droit de garder l'enfant à la maison", "Un pouvoir absolu"], c: 1, e: "L'autorité parentale est l'ensemble des droits et devoirs qu'ont les parents pour protéger la sécurité, la santé, la moralité et l'éducation de leur enfant mineur (moins de 18 ans). Elle implique des responsabilités, pas un pouvoir absolu. Les deux parents l'exercent conjointement, même séparés." },
    { id:"db-5-049", t:5, lvl:"B2", q: "Les parents peuvent-ils infliger des châtiments corporels (violences physiques) à leurs enfants ?", o: ["Oui, c'est leur droit", "Non, c'est strictement interdit par la loi depuis 2019", "Oui, si c'est léger", "Oui, pour l'éducation"], c: 1, e: "Non, depuis la loi de 2019, tout châtiment corporel (fessée, gifle, etc.) est interdit en France. Les violences éducatives ordinaires sont prohibées. Les parents doivent éduquer sans violence. Les violences sur enfant sont un délit pénal grave passible de prison." },
    { id:"db-5-050", t:5, lvl:"B1", q: "Les parents peuvent-ils refuser certains enseignements scolaires pour leur enfant ?", o: ["Oui, selon leurs croyances", "Non, tous les enseignements du programme sont obligatoires", "Oui, sauf les mathématiques", "Oui, s'ils écrivent une lettre"], c: 1, e: "Non, les parents ne peuvent pas refuser que leur enfant suive certains enseignements du programme scolaire (éducation physique, biologie, histoire, etc.). Tous les enseignements sont obligatoires. Contester les programmes pour des raisons religieuses ou idéologiques est interdit." },
    { id:"db-5-051", t:5, lvl:"B1", q: "Un enfant a-t-il le droit d'être protégé contre les violences ?", o: ["Non, les parents décident", "Oui, absolument, c'est un droit fondamental", "Seulement à l'école", "Seulement après 12 ans"], c: 1, e: "Oui, tout enfant a le droit fondamental d'être protégé contre toute forme de violence physique, psychologique ou sexuelle. Ce droit est garanti par la loi française et la Convention internationale des droits de l'enfant. Tout témoin de maltraitance a le devoir de signaler (119, police)." },
    { id:"db-5-052", t:5, lvl:"B2", q: "Qu'est-ce que le règlement intérieur d'une école ?", o: ["Un livre de cours", "Un document fixant les règles de vie et de fonctionnement de l'établissement", "Un emploi du temps", "Un contrat de travail"], c: 1, e: "Le règlement intérieur est un document qui fixe les règles de vie commune dans l'établissement scolaire : horaires, discipline, laïcité, tenue vestimentaire, usage du téléphone, sanctions, droits et devoirs. Élèves et parents doivent le respecter. Il est voté par le conseil d'administration de l'établissement." },
    { id:"db-5-053", t:5, lvl:"B1", q: "Les parents doivent-ils accompagner la scolarité de leur enfant ?", o: ["Non, c'est le rôle de l'école uniquement", "Oui, c'est une obligation : suivre la scolarité, rencontrer les professeurs, aider aux devoirs", "Non, après 10 ans", "Seulement s'ils en ont envie"], c: 1, e: "Oui, les parents ont l'obligation d'accompagner la scolarité de leur enfant : s'assurer de l'assiduité, suivre les résultats, rencontrer les enseignants, aider aux devoirs si possible, respecter le règlement intérieur. C'est un devoir parental essentiel pour la réussite de l'enfant." },
    { id:"db-5-054", t:5, lvl:"B1", q: "Que se passe-t-il si un enfant ne va pas à l'école de façon répétée sans raison valable ?", o: ["Rien", "Les parents risquent des sanctions (amende, voire prison) et un signalement social", "L'enfant est arrêté", "On déménage l'enfant"], c: 1, e: "Si un enfant est régulièrement absent sans justification (absentéisme scolaire), l'école signale la situation. Les parents risquent une amende pouvant aller jusqu'à 7 500 euros et 2 ans de prison. Un accompagnement social est mis en place pour aider la famille. C'est une négligence parentale grave." },
    { id:"db-5-055", t:5, lvl:"B2", q: "Qu'est-ce que l'enseignement supérieur en France ?", o: ["Le lycée", "Les études après le baccalauréat : université, grandes écoles, BTS, IUT", "Le collège", "L'école primaire"], c: 1, e: "L'enseignement supérieur regroupe toutes les formations après le baccalauréat : universités (licences, masters, doctorats), grandes écoles (ingénieur, commerce), BTS, IUT, classes préparatoires. L'université publique a des frais d'inscription très modestes (environ 170-600 euros/an selon le niveau)." },
    { id:"db-5-056", t:5, lvl:"B1", q: "L'université publique est-elle gratuite en France ?", o: ["Oui, totalement gratuite", "Quasi-gratuite : frais d'inscription très modestes (environ 170-600€/an)", "Très chère (20 000€/an)", "Réservée aux riches"], c: 1, e: "L'université publique en France est quasi-gratuite : les frais d'inscription sont très modestes (environ 170€/an en licence, 243€ en master, 380€ en doctorat). C'est l'une des universités les moins chères d'Europe. Des bourses existent pour les étudiants à faibles revenus." },
    { id:"db-5-057", t:5, lvl:"B2", q: "Qu'est-ce que les APL étudiantes ?", o: ["Un diplôme", "Une aide au logement pour les étudiants à faibles ressources", "Une bourse d'études", "Un prêt étudiant"], c: 1, e: "Les APL (Aide Personnalisée au Logement) étudiantes sont des aides financières versées par la CAF pour réduire le montant du loyer des étudiants. Leur montant dépend des ressources, du loyer et de la situation familiale. C'est une aide précieuse pour l'autonomie étudiante." },
    { id:"db-5-058", t:5, lvl:"B1", q: "Qu'est-ce qu'une bourse étudiante du CROUS ?", o: ["Un prêt", "Une aide financière sur critères sociaux pour les étudiants à faibles ressources", "Un salaire", "Une assurance"], c: 1, e: "Les bourses du CROUS (Centre Régional des Œuvres Universitaires et Scolaires) sont des aides financières attribuées sur critères sociaux (revenus familiaux, distance du domicile, nombre d'enfants à charge). Elles permettent aux étudiants de faibles milieux de poursuivre leurs études. Elles sont cumulables avec d'autres aides." },
    { id:"db-5-059", t:5, lvl:"B2", q: "Peut-on travailler tout en étudiant en France ?", o: ["Non, interdit", "Oui, les étudiants peuvent travailler avec certaines limites d'heures", "Seulement les vacances", "Seulement après le diplôme"], c: 1, e: "Oui, les étudiants peuvent travailler tout en poursuivant leurs études. Pour les étudiants étrangers extra-européens, le travail est limité à 964 heures par an (environ 20h/semaine). Les étudiants français et européens n'ont pas de limite mais doivent concilier travail et études." },
    { id:"db-5-060", t:5, lvl:"B1", q: "Qu'est-ce qu'un crédit d'impôt pour frais de garde d'enfants ?", o: ["Une dette", "Une réduction d'impôt pour les parents qui font garder leurs enfants de moins de 6 ans", "Une amende", "Un prêt bancaire"], c: 1, e: "Le crédit d'impôt pour frais de garde d'enfants permet aux parents qui travaillent de récupérer 50% des frais de garde de leurs enfants de moins de 6 ans (crèche, assistante maternelle, garde à domicile) sous forme de réduction d'impôt. Cela aide les familles à concilier vie professionnelle et familiale." },

// === QUESTIONS COMPLÉMENTAIRES - FAMILLE ET ÉTAT CIVIL (Questions 68-80) ===
    { id:"db-5-061", t:5, lvl:"B1", q: "Quel type de mariage est reconnu officiellement par l'État français ?", o: ["Le mariage religieux", "Le mariage civil célébré à la mairie", "Le mariage traditionnel", "Tous les types de mariage"], c: 1, e: "Seul le mariage civil, célébré à la mairie par un officier d'état civil, est reconnu par l'État français. Le mariage religieux est facultatif et doit obligatoirement avoir lieu après le mariage civil. Sans mariage civil, un couple n'a pas de droits légaux l'un envers l'autre." },
    { id:"db-5-062", t:5, lvl:"B1", q: "Auprès de quelle institution les parents peuvent-ils inscrire leur enfant à l'école publique ?", o: ["À la préfecture", "À la mairie de leur commune", "Au rectorat", "À l'école directement"], c: 1, e: "Les parents doivent d'abord inscrire leur enfant à la mairie de leur commune de résidence, qui leur indique l'école de secteur. Ensuite, ils finalisent l'inscription auprès du directeur de l'école. Cette double démarche est obligatoire pour l'école maternelle et élémentaire publique." },
    { id:"db-5-063", t:5, lvl:"B2", q: "En cas de divorce, qui exerce généralement l'autorité parentale sur les enfants ?", o: ["Uniquement le père", "Uniquement la mère", "Les deux parents conjointement", "Le juge uniquement"], c: 2, e: "En cas de divorce, l'autorité parentale continue généralement à être exercée conjointement par les deux parents. Le divorce ne met pas fin aux droits et devoirs des parents envers leurs enfants. Le juge fixe la résidence des enfants et les modalités du droit de visite." },
    { id:"db-5-064", t:5, lvl:"B1", q: "Quelle aide permet aux personnes à faibles revenus d'avoir accès à un avocat ?", o: ["L'aide au logement", "L'aide juridictionnelle", "Le RSA", "La mutuelle"], c: 1, e: "L'aide juridictionnelle permet aux personnes à faibles revenus de bénéficier d'un avocat gratuit (totalement ou partiellement) et de la prise en charge des frais de justice. Elle garantit l'accès à la justice pour tous, quel que soit le niveau de revenus." },
    { id:"db-5-065", t:5, lvl:"B1", q: "Où faut-il déclarer la naissance d'un enfant ?", o: ["À l'hôpital uniquement", "À la mairie du lieu de naissance", "À la préfecture", "À la CAF"], c: 1, e: "La naissance d'un enfant doit être déclarée à la mairie du lieu de naissance dans les 5 jours suivant l'accouchement. C'est généralement le père ou un proche qui effectue cette déclaration, muni du certificat médical de l'hôpital. L'acte de naissance est alors établi." },
    { id:"db-5-066", t:5, lvl:"B2", q: "Quelle est l'une des conditions pour pouvoir passer l'examen du permis de conduire ?", o: ["Avoir 21 ans", "Avoir au moins 17 ans (conduite accompagnée) ou 18 ans", "Avoir un emploi", "Être marié"], c: 1, e: "Pour passer le permis de conduire (permis B), il faut avoir au moins 18 ans (ou 17 ans pour la conduite accompagnée). Il faut aussi avoir obtenu le code de la route, suivi une formation pratique, et pour les jeunes Français, avoir effectué la JDC (Journée Défense et Citoyenneté)." },
    { id:"db-5-067", t:5, lvl:"B1", q: "Un contrat de location (bail) doit-il obligatoirement être écrit ?", o: ["Non, un accord oral suffit", "Oui, il doit être écrit et signé par les deux parties", "Seulement pour les grandes surfaces", "C'est facultatif"], c: 1, e: "Oui, le bail de location doit obligatoirement être établi par écrit et signé par le propriétaire et le locataire. Ce contrat précise le loyer, les charges, la durée, le dépôt de garantie et les obligations de chacun. Sans écrit, le locataire est moins protégé." },
    { id:"db-5-068", t:5, lvl:"B1", q: "Quel numéro d'urgence permet d'appeler la police en France ?", o: ["15", "17", "18", "112"], c: 1, e: "Le 17 est le numéro d'urgence de la police et de la gendarmerie en France. Il est gratuit et accessible 24h/24 pour signaler une agression, un vol, des violences, un accident ou toute situation nécessitant une intervention policière urgente." },
    { id:"db-5-069", t:5, lvl:"B2", q: "Qui peut demander un congé parental d'éducation ?", o: ["Uniquement la mère", "Uniquement le père", "Les deux parents, père ou mère", "Seulement les fonctionnaires"], c: 2, e: "Le congé parental d'éducation peut être demandé par le père ou la mère, sans distinction. Il permet de suspendre ou réduire son activité professionnelle pour s'occuper de son enfant jusqu'à ses 3 ans. C'est un droit ouvert aux deux parents, qui peuvent aussi le partager." },
    { id:"db-5-070", t:5, lvl:"B1", q: "À quel âge un enfant devient-il majeur en France ?", o: ["16 ans", "18 ans", "21 ans", "25 ans"], c: 1, e: "En France, la majorité légale est fixée à 18 ans. À cet âge, une personne devient pleinement responsable de ses actes, peut voter, signer des contrats, se marier sans autorisation parentale, et exercer l'ensemble de ses droits civiques." },
    { id:"db-5-071", t:5, lvl:"B1", q: "À quel âge commence l'instruction obligatoire des enfants en France ?", o: ["6 ans", "3 ans", "5 ans", "4 ans"], c: 1, e: "L'instruction est obligatoire en France dès l'âge de 3 ans (depuis 2019) et jusqu'à 16 ans. Cela signifie que tous les enfants doivent recevoir une instruction, à l'école ou à domicile. L'école maternelle fait désormais partie de la scolarité obligatoire." },
    { id:"db-5-072", t:5, lvl:"B2", q: "Des parents qui ne respectent pas l'obligation d'instruction de leur enfant risquent quelles sanctions ?", o: ["Rien", "Jusqu'à 7 500 euros d'amende et 2 ans de prison", "Juste un avertissement", "Le retrait du RSA"], c: 1, e: "Les parents qui ne respectent pas l'obligation d'instruction de leur enfant s'exposent à une amende pouvant aller jusqu'à 7 500 euros et à 2 ans de prison. L'absentéisme scolaire répété sans justification est considéré comme une négligence parentale grave." },
    { id:"db-5-073", t:5, lvl:"B1", q: "Quand ont lieu les vacances scolaires de Noël en France ?", o: ["En novembre", "Autour du 25 décembre, pendant environ 2 semaines", "En janvier uniquement", "Il n'y a pas de vacances"], c: 1, e: "Les vacances scolaires de Noël ont lieu autour du 25 décembre et durent environ 2 semaines (généralement de fin décembre à début janvier). Elles sont communes à toutes les zones scolaires de France, contrairement aux vacances d'hiver et de printemps qui sont échelonnées." },

    // === QUESTIONS COMPLÉMENTAIRES - SANTÉ (Questions 81-90) ===
    { id:"db-5-074", t:5, lvl:"B1", q: "À qui la contraception est-elle accessible en France ?", o: ["Uniquement aux femmes mariées", "À toutes les personnes, y compris les mineures", "Uniquement aux personnes de plus de 25 ans", "Uniquement sur ordonnance du médecin traitant"], c: 1, e: "La contraception est accessible à toutes les personnes en France, y compris aux mineures qui peuvent l'obtenir de façon anonyme et gratuite. Les centres de planification familiale offrent un accès gratuit à la contraception. C'est un droit fondamental de disposer de son corps." },
    { id:"db-5-075", t:5, lvl:"B2", q: "Qu'est-ce que le secret médical ?", o: ["Le droit du médecin de cacher ses erreurs", "L'obligation pour les soignants de ne pas divulguer les informations sur leurs patients", "Le droit de refuser un traitement", "Une option pour les patients riches"], c: 1, e: "Le secret médical est l'obligation absolue pour tous les professionnels de santé de ne pas divulguer les informations concernant leurs patients. C'est un droit fondamental du patient. Violer le secret médical est un délit puni d'un an de prison et 15 000 euros d'amende." },
    { id:"db-5-076", t:5, lvl:"B1", q: "L'inscription à l'Assurance maladie (Sécurité sociale) est-elle obligatoire ?", o: ["Non, c'est facultatif", "Oui, pour toute personne résidant en France de façon stable", "Seulement pour les salariés", "Seulement pour les Français"], c: 1, e: "Oui, l'affiliation à l'Assurance maladie est obligatoire pour toute personne résidant en France de façon stable et régulière. Cela permet d'être remboursé des frais de santé. Les personnes sans ressources peuvent bénéficier de la Complémentaire Santé Solidaire (CSS) gratuite." },
    { id:"db-5-077", t:5, lvl:"B1", q: "Dans quelles situations doit-on se rendre aux urgences de l'hôpital ?", o: ["Pour un simple rhume", "En cas d'urgence vitale ou de blessure grave nécessitant des soins immédiats", "Pour renouveler une ordonnance", "Pour un certificat médical"], c: 1, e: "Les urgences hospitalières sont réservées aux situations graves nécessitant des soins immédiats : accident grave, douleur thoracique, difficultés respiratoires, perte de connaissance, hémorragie importante. Pour les problèmes non urgents, il faut consulter son médecin traitant ou un médecin de garde." },
    { id:"db-5-078", t:5, lvl:"B2", q: "Quel est l'objectif des vaccinations obligatoires ?", o: ["Enrichir les laboratoires", "Protéger la santé individuelle et collective contre des maladies graves", "Contrôler la population", "Il n'y a pas d'objectif médical"], c: 1, e: "Les vaccins obligatoires protègent contre des maladies graves et potentiellement mortelles. Ils protègent non seulement la personne vaccinée mais aussi la collectivité (immunité de groupe), notamment les personnes fragiles qui ne peuvent pas être vaccinées. C'est un acte de solidarité et de santé publique." },
    { id:"db-5-079", t:5, lvl:"B1", q: "À quoi sert la carte Vitale ?", o: ["À voyager en Europe", "À prouver ses droits à l'Assurance maladie et être remboursé", "À voter", "À conduire"], c: 1, e: "La carte Vitale est une carte à puce qui atteste de vos droits à l'Assurance maladie. Elle permet le remboursement automatique et rapide des frais de santé. Elle contient vos informations administratives mais pas votre dossier médical. Elle est gratuite et personnelle." },
    { id:"db-5-080", t:5, lvl:"B2", q: "À quoi sert une mutuelle santé (complémentaire) ?", o: ["À remplacer la Sécurité sociale", "À rembourser les frais non couverts par la Sécurité sociale", "À payer les impôts", "À obtenir un logement"], c: 1, e: "La mutuelle (complémentaire santé) rembourse tout ou partie des frais de santé non couverts par la Sécurité sociale : ticket modérateur, dépassements d'honoraires, lunettes, prothèses dentaires. Elle n'est pas obligatoire mais fortement recommandée pour éviter des restes à charge importants." },
    { id:"db-5-081", t:5, lvl:"B1", q: "Quel est le rôle du médecin traitant ?", o: ["Uniquement prescrire des médicaments", "Coordonner le parcours de soins et orienter vers les spécialistes", "Remplacer l'hôpital", "Délivrer des arrêts de travail uniquement"], c: 1, e: "Le médecin traitant est le médecin référent qui vous connaît et suit votre santé. Il coordonne votre parcours de soins, vous oriente vers des spécialistes si nécessaire, et tient votre dossier médical. Passer par lui garantit un meilleur remboursement par la Sécurité sociale." },
    { id:"db-5-082", t:5, lvl:"B1", q: "En cas de problème de santé non urgent, à qui faut-il s'adresser en premier ?", o: ["Aux urgences de l'hôpital", "À son médecin traitant", "À la pharmacie", "À la mairie"], c: 1, e: "En cas de problème de santé non urgent, il faut d'abord consulter son médecin traitant. C'est lui qui vous connaît le mieux et peut vous orienter si nécessaire. Les urgences hospitalières sont réservées aux cas graves. Le soir et le week-end, on peut appeler le 15 pour conseil ou le médecin de garde." },

    // === QUESTIONS COMPLÉMENTAIRES - TRAVAIL ET EMPLOI (Questions 91-105) ===
    { id:"db-5-083", t:5, lvl:"B1", q: "Travailler sans être déclaré (travail au noir) est-il légal ?", o: ["Oui, si l'employeur est d'accord", "Non, c'est illégal et puni par la loi", "Oui, pour les petits travaux", "Seulement entre amis"], c: 1, e: "Non, le travail non déclaré (travail au noir) est illégal. L'employeur risque jusqu'à 3 ans de prison et 45 000 euros d'amende. Le salarié perd ses droits (chômage, retraite, accident du travail). C'est aussi une fraude aux cotisations sociales qui pénalise toute la collectivité." },
    { id:"db-5-084", t:5, lvl:"B2", q: "Quelles sont les affaires traitées par le conseil de prud'hommes ?", o: ["Les divorces", "Les litiges entre employeurs et salariés liés au contrat de travail", "Les infractions pénales", "Les conflits de voisinage"], c: 1, e: "Le conseil de prud'hommes traite les litiges individuels entre employeurs et salariés concernant le contrat de travail : licenciement abusif, salaires impayés, harcèlement au travail, non-respect du contrat. C'est une juridiction paritaire composée de représentants des employeurs et des salariés." },
    { id:"db-5-085", t:5, lvl:"B2", q: "Lorsqu'un employeur veut qu'un salarié travaille plus que la durée légale, que doit-il faire ?", o: ["Rien de spécial", "Payer des heures supplémentaires majorées et respecter les limites légales", "Demander au salarié de démissionner", "L'obliger sans compensation"], c: 1, e: "L'employeur doit payer les heures supplémentaires avec une majoration (25% pour les 8 premières, 50% au-delà) ou accorder un repos compensateur. Il doit respecter les durées maximales de travail (10h/jour, 48h/semaine). Le salarié peut refuser si les limites légales sont dépassées." },
    { id:"db-5-086", t:5, lvl:"B1", q: "Quelle est la mission principale de France Travail (ex-Pôle emploi) ?", o: ["Collecter les impôts", "Accompagner les demandeurs d'emploi et aider au retour à l'emploi", "Gérer les hôpitaux", "Délivrer les passeports"], c: 1, e: "France Travail (anciennement Pôle emploi) a pour mission d'accompagner les demandeurs d'emploi dans leur recherche de travail, de verser les allocations chômage, et d'aider les entreprises à recruter. L'inscription est obligatoire pour percevoir les allocations chômage." },
    { id:"db-5-087", t:5, lvl:"B2", q: "Dans une entreprise, que permet le droit syndical ?", o: ["De ne pas travailler", "De créer ou adhérer à un syndicat pour défendre les droits des salariés", "D'imposer ses décisions à l'employeur", "De licencier les collègues"], c: 1, e: "Le droit syndical permet aux salariés de créer ou d'adhérer librement à un syndicat pour défendre collectivement leurs intérêts professionnels. Les syndicats négocient avec l'employeur (salaires, conditions de travail), informent les salariés et peuvent organiser des grèves légales." },
    { id:"db-5-088", t:5, lvl:"B2", q: "Dans une entreprise, que permet le droit de grève ?", o: ["De détruire le matériel", "De cesser le travail collectivement pour défendre des revendications professionnelles", "D'occuper le bureau du patron", "De licencier les non-grévistes"], c: 1, e: "Le droit de grève, garanti par la Constitution, permet aux salariés de cesser collectivement le travail pour défendre des revendications professionnelles. La grève doit rester pacifique : pas de violence, pas d'occupation illégale, pas de blocage des non-grévistes. Le salaire n'est pas versé pendant la grève." },
    { id:"db-5-089", t:5, lvl:"B2", q: "Quelles sont les conditions pour percevoir les allocations chômage ?", o: ["Aucune condition", "Avoir travaillé suffisamment, être inscrit à France Travail, rechercher activement un emploi", "Être au chômage depuis 5 ans", "Être propriétaire"], c: 1, e: "Pour percevoir les allocations chômage, il faut : avoir travaillé au moins 6 mois dans les 24 derniers mois, être inscrit comme demandeur d'emploi à France Travail, rechercher activement un emploi, et avoir perdu involontairement son emploi (licenciement, fin de CDD). La démission n'ouvre généralement pas de droits." },
    { id:"db-5-090", t:5, lvl:"B1", q: "Une personne étrangère en situation régulière peut-elle créer son entreprise en France ?", o: ["Non, c'est réservé aux Français", "Oui, sous certaines conditions selon le titre de séjour", "Jamais", "Seulement après 10 ans"], c: 1, e: "Oui, une personne étrangère en situation régulière peut créer son entreprise en France si son titre de séjour l'autorise à exercer une activité professionnelle. Certains titres permettent directement la création d'entreprise, d'autres nécessitent une modification. C'est un droit ouvert." },

    // === QUESTIONS COMPLÉMENTAIRES - SCOLARITÉ (Questions 106-115) ===
    { id:"db-5-091", t:5, lvl:"B1", q: "Qu'est-ce que l'école maternelle ?", o: ["Une école payante", "L'école pour les enfants de 3 à 6 ans, première étape de la scolarité obligatoire", "Une garderie privée", "Une école réservée aux filles"], c: 1, e: "L'école maternelle accueille les enfants de 3 à 6 ans. Depuis 2019, elle fait partie de la scolarité obligatoire. Elle prépare les enfants à l'école élémentaire en développant le langage, la socialisation et les premiers apprentissages. Elle est gratuite dans le public." },
    { id:"db-5-092", t:5, lvl:"B1", q: "Comment s'appelle le diplôme passé par les élèves à la fin du collège ?", o: ["Le baccalauréat", "Le brevet des collèges (DNB)", "Le CAP", "La licence"], c: 1, e: "Le diplôme national du brevet (DNB), aussi appelé brevet des collèges, est passé par les élèves en fin de troisième (vers 14-15 ans). Il évalue les connaissances acquises au collège. C'est le premier diplôme de la scolarité, mais il n'est pas obligatoire pour continuer ses études." },
    { id:"db-5-093", t:5, lvl:"B2", q: "Les parents d'élèves ont-ils des droits de participation à l'école ?", o: ["Non, ils n'ont aucun droit", "Oui, ils peuvent participer aux conseils d'école et de classe", "Seulement pour les écoles privées", "Seulement s'ils sont enseignants"], c: 1, e: "Oui, les parents ont des droits de participation : élire leurs représentants, siéger au conseil d'école (primaire) ou conseil de classe (secondaire), accéder aux informations sur la scolarité de leur enfant, rencontrer les enseignants. Ils sont partenaires de l'éducation." },
    { id:"db-5-094", t:5, lvl:"B1", q: "Qui peut manger à la cantine scolaire ?", o: ["Uniquement les bons élèves", "Tous les élèves dont les parents le souhaitent", "Seulement les enfants de fonctionnaires", "Uniquement en primaire"], c: 1, e: "Tous les élèves dont les parents le souhaitent peuvent manger à la cantine, si l'établissement en dispose. Le prix du repas varie selon les revenus de la famille (quotient familial). Des aides existent pour les familles à faibles revenus. La cantine n'est pas obligatoire." },
    { id:"db-5-095", t:5, lvl:"B2", q: "À l'école, les parents peuvent-ils contester les enseignements pour des raisons religieuses ?", o: ["Oui, c'est leur droit", "Non, tous les enseignements sont obligatoires et ne peuvent être contestés", "Seulement pour l'éducation physique", "Seulement en primaire"], c: 1, e: "Non, les parents ne peuvent pas contester les enseignements pour des raisons religieuses. La Charte de la laïcité précise qu'aucun élève ne peut invoquer une conviction religieuse pour refuser les règles de l'école ou contester un enseignement. Tous les cours sont obligatoires." },
    { id:"db-5-096", t:5, lvl:"B1", q: "Quel motif d'absence est accepté par l'école ?", o: ["Faire les courses", "Maladie, rendez-vous médical, événement familial grave", "Fatigue", "Mauvais temps"], c: 1, e: "Les absences acceptées par l'école sont : maladie (avec justificatif), rendez-vous médical impossible à déplacer, événement familial grave (décès, mariage proche), convocation officielle. Les absences pour convenance personnelle (vacances, sorties) ne sont pas justifiées et peuvent être sanctionnées." },
    { id:"db-5-097", t:5, lvl:"B1", q: "Un enfant en situation de handicap a-t-il le droit d'aller à l'école ?", o: ["Non, il doit rester à la maison", "Oui, l'école doit l'accueillir et adapter sa scolarité", "Seulement dans des établissements spécialisés", "Seulement si le handicap est léger"], c: 1, e: "Oui, tout enfant en situation de handicap a le droit d'être scolarisé. L'école doit mettre en place des aménagements adaptés (AESH, matériel spécifique, temps supplémentaire). L'inclusion scolaire est un droit. Un projet personnalisé de scolarisation (PPS) organise l'accompagnement." },
    { id:"db-5-098", t:5, lvl:"B1", q: "Les enfants qui ne parlent pas français peuvent-ils aller à l'école ?", o: ["Non, ils doivent d'abord apprendre le français", "Oui, l'école les accueille et leur propose un soutien linguistique", "Seulement après un examen", "Non, c'est interdit"], c: 1, e: "Oui, tous les enfants, quelle que soit leur langue maternelle, ont droit à l'école en France. Les élèves allophones (ne parlant pas français) bénéficient d'un soutien linguistique adapté (UPE2A - unités pédagogiques pour élèves allophones) pour apprendre le français tout en suivant une scolarité normale." },
    { id:"db-5-099", t:5, lvl:"B1", q: "Un enfant inscrit à l'école doit-il y aller tous les jours ?", o: ["Non, c'est facultatif", "Oui, l'assiduité est obligatoire", "Seulement 3 jours par semaine", "Seulement pour les examens"], c: 1, e: "Oui, l'assiduité scolaire est obligatoire. Un enfant inscrit à l'école doit assister à tous les cours. Les absences doivent être justifiées. L'absentéisme répété peut entraîner des sanctions pour les parents et un signalement aux services sociaux." },
    { id:"db-5-100", t:5, lvl:"B1", q: "Pour qui l'école est-elle obligatoire en France ?", o: ["Uniquement pour les garçons", "Pour tous les enfants de 3 à 16 ans résidant en France", "Seulement pour les Français", "Uniquement jusqu'à 12 ans"], c: 1, e: "L'instruction est obligatoire pour tous les enfants de 3 à 16 ans résidant en France, quelle que soit leur nationalité. Cela concerne les enfants français et étrangers. L'instruction peut avoir lieu à l'école (publique ou privée) ou, sous certaines conditions, à domicile." },

    // === QUESTIONS COMPLÉMENTAIRES - COUVERTURE OFFICIELLE (Thème 5) ===
    { id:"db-5-101", t:5, lvl:"B1", q: "Qu'est-ce qu'un numéro d'urgence ?", o: ["Un numéro payant pour les abonnés", "Un numéro gratuit, disponible 24h/24, pour appeler les secours en cas de danger", "Un numéro réservé aux médecins", "Un numéro qui fonctionne uniquement en semaine"], c: 1, e: "Un numéro d'urgence est un numéro de téléphone gratuit, accessible 24h/24 et 7j/7, permettant d'appeler les secours en cas de danger. En France, les principaux sont : le 15 (SAMU, urgences médicales), le 17 (police/gendarmerie), le 18 (pompiers) et le 112 (numéro européen universel)." },
    { id:"db-5-102", t:5, lvl:"B1", q: "En France, tout le monde peut-il se faire soigner, même sans beaucoup d'argent ?", o: ["Non, les soins sont réservés aux personnes riches", "Oui, la Sécurité sociale et des dispositifs comme la complémentaire santé solidaire garantissent l'accès aux soins pour tous", "Seulement dans les hôpitaux publics", "Seulement les citoyens français"], c: 1, e: "Oui, la France garantit l'accès aux soins pour tous. La Sécurité sociale rembourse une partie des frais médicaux. Les personnes aux revenus modestes peuvent bénéficier de la complémentaire santé solidaire (ex-CMU). Les urgences hospitalières accueillent toute personne, quelle que soit sa situation." },
    { id:"db-5-103", t:5, lvl:"B1", q: "Comment s'appelle le diplôme obtenu à la fin du lycée ?", o: ["Le brevet des collèges", "Le baccalauréat", "Le CAP", "La licence"], c: 1, e: "Le baccalauréat (souvent appelé 'bac') est le diplôme obtenu à la fin du lycée, vers 17-18 ans. Il existe en trois voies : générale, technologique et professionnelle. Le baccalauréat ouvre l'accès à l'enseignement supérieur (université, BTS, classes préparatoires, IUT)." },
    { id:"db-5-104", t:5, lvl:"B1", q: "Dans quel établissement scolaire vont les élèves après l'école élémentaire (primaire) ?", o: ["Au lycée", "Au collège", "À l'université", "En école maternelle"], c: 1, e: "Après l'école élémentaire (6-11 ans), les élèves entrent au collège pour quatre ans (de la 6e à la 3e, soit de 11 à 15 ans). À la fin du collège, ils passent le brevet (DNB) puis poursuivent au lycée général, technologique ou professionnel." },
    { id:"db-5-105", t:5, lvl:"B1", q: "Quel est le rôle de l'école en France ?", o: ["Uniquement apprendre à lire et écrire", "Transmettre des connaissances, former des citoyens et favoriser l'égalité des chances", "Garder les enfants pendant que les parents travaillent", "Préparer uniquement au monde du travail"], c: 1, e: "L'école en France a pour mission de transmettre des connaissances et des compétences, de former des citoyens responsables en enseignant les valeurs de la République (liberté, égalité, fraternité, laïcité), et de favoriser l'égalité des chances en offrant à chaque enfant les mêmes possibilités de réussite." },
    { id:"db-5-106", t:5, lvl:"B2", q: "Quand un employeur embauche un salarié, auprès de quel organisme doit-il le déclarer ?", o: ["À la mairie", "À l'URSSAF, via la déclaration préalable à l'embauche (DPAE)", "Au tribunal", "À la CAF"], c: 1, e: "L'employeur doit déclarer tout nouveau salarié à l'URSSAF (Union de Recouvrement des cotisations de Sécurité Sociale et d'Allocations Familiales) via la DPAE (déclaration préalable à l'embauche). Cette déclaration est obligatoire avant le début du travail. Ne pas déclarer un salarié constitue du travail dissimulé, un délit sévèrement puni." },
];

/* === BASE DE DONNÉES MISES EN SITUATION === */
const DB_SITUATIONS = [
    // === T1 - PRINCIPES ET VALEURS (30 questions) ===
    { id:"sit-1-001", t:1, q: "Lucas est parent d'élève. Il demande à l'école publique de ne pas enseigner la théorie de l'évolution à son fils car cela contredit ses croyances religieuses. L'école doit-elle accepter ?", o: ["Oui, les parents ont le droit de choisir l'éducation de leurs enfants", "Non, tous les enseignements sont obligatoires et ne peuvent être contestés pour raisons religieuses", "Oui, mais uniquement avec un certificat religieux", "L'école doit proposer un cours alternatif"], c: 1, e: "Non, l'école ne peut pas accepter cette demande. La Charte de la laïcité à l'école (article 12) est claire : aucun élève ne peut invoquer une conviction religieuse ou politique pour contester à un enseignant le droit de traiter une question au programme." },
    { id:"sit-1-002", t:1, q: "Emma, 14 ans, arrive au collège public avec un voile couvrant ses cheveux. Le proviseur lui demande de le retirer. A-t-il le droit ?", o: ["Non, c'est une atteinte à sa liberté religieuse", "Oui, les signes religieux ostensibles sont interdits à l'école publique", "Seulement si les autres élèves se plaignent", "Non, car elle est mineure et ses parents décident"], c: 1, e: "Oui, le proviseur a le droit et même le devoir de demander à Emma de retirer son voile. La loi du 15 mars 2004 interdit le port de signes ou tenues manifestant ostensiblement une appartenance religieuse dans les écoles, collèges et lycées publics." },
    { id:"sit-1-003", t:1, q: "Thomas, professeur d'histoire dans un lycée public, souhaite porter une petite croix visible autour du cou pendant ses cours. En a-t-il le droit ?", o: ["Oui, tant que c'est discret et qu'il n'en parle pas aux élèves", "Non, les agents du service public doivent respecter une stricte neutralité religieuse", "Oui, car la croix fait partie du patrimoine français", "Seulement pendant les cours d'histoire des religions"], c: 1, e: "Non, Thomas ne peut pas porter de signe religieux visible, même discret, dans l'exercice de ses fonctions. En tant qu'agent du service public, il est soumis au principe de stricte neutralité." },
    { id:"sit-1-004", t:1, q: "Léa, 16 ans, refuse de participer au cours d'éducation physique (piscine) en invoquant sa pudeur religieuse. Le lycée doit-il accepter ?", o: ["Oui, la liberté religieuse permet cette exception", "Non, tous les enseignements sont obligatoires sans exception religieuse", "Oui, si ses parents signent une décharge", "Le lycée doit proposer une activité alternative"], c: 1, e: "Non, le lycée ne doit pas accepter. La Charte de la laïcité précise qu'aucun élève ne peut invoquer une conviction religieuse pour refuser de se conformer aux règles de l'établissement ou pour s'opposer à un enseignement." },
    { id:"sit-1-005", t:1, q: "Martin, parent d'élève, demande à rencontrer l'enseignante de son fils. Lors du rendez-vous, il refuse de lui serrer la main car c'est une femme. L'enseignante peut-elle refuser l'entretien ?", o: ["Non, ne pas serrer la main n'empêche pas le dialogue sur la scolarité", "Oui, c'est un manque de respect envers les femmes", "Elle doit demander l'avis du directeur", "Elle peut exiger des excuses écrites"], c: 0, e: "Non, l'enseignante ne devrait pas refuser l'entretien pour ce seul motif. Ne pas serrer la main, bien que cela puisse surprendre ou blesser, n'est pas une infraction et n'empêche pas le dialogue éducatif. L'intérêt de l'enfant doit primer." },
    { id:"sit-1-006", t:1, q: "Sophie, directrice d'école primaire publique, reçoit une demande de parents pour que la cantine serve uniquement de la viande halal. Doit-elle accepter ?", o: ["Oui, pour respecter la diversité religieuse des familles", "Non, la cantine publique n'a pas à imposer de règles alimentaires religieuses à tous", "Oui, si la majorité des parents le demande", "Elle doit organiser un vote des parents"], c: 1, e: "Non, Sophie ne doit pas accepter d'imposer un menu exclusivement halal à tous les élèves. La cantine scolaire publique est un service laïque qui ne peut pas appliquer de prescriptions religieuses à l'ensemble des usagers." },
    { id:"sit-1-007", t:1, q: "Marie se présente au guichet de la mairie pour renouveler sa carte d'identité. L'agent qui la reçoit porte un voile. Marie peut-elle exiger d'être reçue par quelqu'un d'autre ?", o: ["Oui, elle a le droit de choisir par qui elle est servie", "Non, mais l'agent ne devrait pas porter de signe religieux dans ses fonctions", "Oui, si elle invoque ses propres convictions", "Elle peut porter plainte pour prosélytisme"], c: 1, e: "Marie ne peut pas exiger de choisir l'agent qui la reçoit. Cependant, l'agent de mairie, en tant que fonctionnaire, ne devrait pas porter de signe religieux ostensible dans l'exercice de ses fonctions : c'est une obligation de neutralité." },
    { id:"sit-1-008", t:1, q: "Antoine travaille comme agent d'accueil dans un hôpital public. Un patient lui demande de prier avec lui avant son opération. Que doit faire Antoine ?", o: ["Accepter pour rassurer le patient stressé", "Refuser poliment car il doit rester neutre, mais proposer d'appeler un aumônier", "Accepter si personne ne les voit", "Demander l'autorisation à son supérieur"], c: 1, e: "Antoine doit refuser poliment de prier avec le patient. En tant qu'agent du service public hospitalier, il est tenu à la neutralité religieuse. Cependant, il peut orienter le patient vers l'aumônerie de l'hôpital." },
    { id:"sit-1-009", t:1, q: "Fatou, infirmière dans un hôpital public, est appelée pour soigner un patient masculin. Elle demande à être remplacée par un collègue homme car sa religion lui interdit de toucher un homme qui n'est pas de sa famille. L'hôpital doit-il accepter ?", o: ["Oui, par respect pour ses convictions religieuses", "Non, elle doit assurer les soins à tous les patients sans distinction", "Oui, si un collègue est disponible", "L'hôpital doit adapter les plannings"], c: 1, e: "Non, l'hôpital ne doit pas accepter cette demande. Fatou, en tant qu'agent du service public, ne peut pas invoquer ses convictions religieuses pour refuser de soigner un patient. Elle doit garantir la continuité et l'égalité du service public." },
    { id:"sit-1-010", t:1, q: "Pierre, usager de la bibliothèque municipale, voit un autre usager prier discrètement dans un coin. Doit-il le signaler au personnel ?", o: ["Oui, la prière est interdite dans les bâtiments publics", "Non, les usagers peuvent exprimer leurs convictions tant qu'ils ne perturbent pas les autres", "Oui, c'est du prosélytisme", "Il doit d'abord lui demander d'arrêter"], c: 1, e: "Non, Pierre n'a pas à signaler cette situation. Contrairement aux agents du service public, les usagers ne sont pas tenus à la neutralité religieuse. Une prière silencieuse et discrète ne gêne personne." },
    { id:"sit-1-011", t:1, q: "Julie et Marc sont mariés. Marc estime que les décisions importantes concernant leurs enfants lui reviennent en tant que père et chef de famille. A-t-il raison selon la loi française ?", o: ["Oui, le père est traditionnellement le chef de famille", "Non, les deux parents ont une autorité parentale égale", "Oui, mais seulement pour les garçons", "Cela dépend du contrat de mariage"], c: 1, e: "Non, Marc a tort. En France, depuis 1970, l'autorité parentale est exercée conjointement par les deux parents, à égalité. Il n'existe plus de « chef de famille » au sens juridique." },
    { id:"sit-1-012", t:1, q: "Nadia postule pour un emploi de commerciale. Lors de l'entretien, le recruteur lui demande si elle compte avoir des enfants bientôt. Cette question est-elle légale ?", o: ["Oui, l'employeur a le droit de s'organiser", "Non, cette question est discriminatoire et interdite", "Oui, pour un CDI seulement", "Seulement si c'est une petite entreprise"], c: 1, e: "Non, cette question est illégale. Le Code du travail interdit toute discrimination à l'embauche fondée sur la situation familiale ou la grossesse. Nadia peut refuser de répondre ou même mentir sans conséquence juridique." },
    { id:"sit-1-013", t:1, q: "Ahmed souhaite épouser deux femmes en France car sa religion l'autorise. Le maire peut-il célébrer ces deux mariages ?", o: ["Oui, la liberté religieuse le permet", "Non, la polygamie est strictement interdite en France", "Oui, si les deux femmes sont d'accord", "Seulement si le premier mariage est religieux"], c: 1, e: "Non, le maire ne peut pas célébrer un second mariage si Ahmed est déjà marié. La polygamie est strictement interdite en France. Le Code civil impose la monogamie. La bigamie est un délit pénal." },
    { id:"sit-1-014", t:1, q: "Claire travaille dans une entreprise privée. Son collègue masculin, au même poste et avec la même ancienneté, gagne 15% de plus qu'elle. Est-ce légal ?", o: ["Non, la loi impose un salaire égal pour un travail égal", "Oui, l'employeur est libre de fixer les salaires dans le privé", "Oui, si le collègue négocie mieux", "Cela dépend de la convention collective"], c: 0, e: "Non, cette différence de salaire est illégale. Le principe « à travail égal, salaire égal » est inscrit dans le Code du travail. Claire peut saisir les prud'hommes." },
    { id:"sit-1-015", t:1, q: "Michel souhaite interdire à sa fille majeure de 22 ans de sortir seule le soir et de choisir son futur mari. En a-t-il le droit ?", o: ["Oui, il reste son père et doit la protéger", "Non, à 18 ans elle est majeure et libre de ses choix", "Oui, selon les traditions familiales", "Seulement si elle vit chez lui"], c: 1, e: "Non, Michel n'a aucun droit d'imposer ces restrictions à sa fille. En France, la majorité est fixée à 18 ans. À partir de cet âge, chaque personne est juridiquement autonome et libre de ses choix de vie." },
    { id:"sit-1-016", t:1, q: "David publie sur les réseaux sociaux des messages appelant à la haine contre une communauté religieuse. Est-il protégé par la liberté d'expression ?", o: ["Oui, chacun peut exprimer ses opinions librement", "Non, l'appel à la haine est un délit qui dépasse la liberté d'expression", "Oui, sur les réseaux sociaux tout est permis", "Seulement s'il ne cite pas de noms"], c: 1, e: "Non, David n'est pas protégé. L'incitation à la haine est un délit pénal. David risque jusqu'à un an de prison et 45 000 euros d'amende. La liberté d'expression permet de critiquer des idées, pas d'appeler à la haine contre des personnes." },
    { id:"sit-1-017", t:1, q: "Amélie souhaite organiser une manifestation contre une décision du gouvernement. Doit-elle demander une autorisation préalable ?", o: ["Oui, toute manifestation doit être autorisée par le préfet", "Non, elle doit simplement déclarer la manifestation à l'avance", "Oui, avec l'accord du maire", "Non, aucune démarche n'est nécessaire"], c: 1, e: "Non, Amélie n'a pas besoin d'autorisation, mais elle doit effectuer une déclaration préalable en préfecture ou mairie, au moins 3 jours avant. Le droit de manifester est une liberté fondamentale." },
    { id:"sit-1-018", t:1, q: "Paul veut créer une association pour défendre les droits des locataires. Doit-il obtenir un agrément de l'État ?", o: ["Non, la création d'association est libre, une simple déclaration suffit", "Oui, toute association doit être approuvée par la préfecture", "Oui, pour les associations politiques", "Seulement si elle reçoit des dons"], c: 0, e: "Non, Paul n'a pas besoin d'agrément. La liberté d'association est garantie par la loi de 1901. Toute personne peut créer une association en effectuant une simple déclaration en préfecture." },
    { id:"sit-1-019", t:1, q: "Chloé est journaliste. La police lui demande de révéler ses sources pour une enquête sur des malversations dans une entreprise. Doit-elle obéir ?", o: ["Oui, aider la justice est un devoir citoyen", "Non, le secret des sources journalistiques est protégé par la loi", "Oui, si un juge l'ordonne", "Seulement pour les affaires criminelles"], c: 1, e: "Non, Chloé n'est pas obligée de révéler ses sources. La loi du 4 janvier 2010 protège le secret des sources des journalistes. Ce secret ne peut être levé que dans des cas très exceptionnels." },
    { id:"sit-1-020", t:1, q: "Youssef est contrôlé par la police dans la rue. Les policiers lui demandent de présenter une pièce d'identité. Doit-il obligatoirement en avoir une sur lui ?", o: ["Oui, c'est obligatoire de porter ses papiers en France", "Non, mais il doit pouvoir justifier son identité d'une manière ou d'une autre", "Oui, sous peine d'amende", "Seulement les étrangers doivent porter leurs papiers"], c: 1, e: "Non, il n'est pas obligatoire de porter une pièce d'identité sur soi en France. Cependant, lors d'un contrôle légal, Youssef doit pouvoir justifier son identité. Sans document, il peut être retenu maximum 4 heures pour vérification." },
    { id:"sit-1-021", t:1, q: "Ibrahim, propriétaire d'un appartement, refuse de louer à une famille parce qu'elle est d'origine africaine. Est-ce légal ?", o: ["Oui, un propriétaire choisit librement son locataire", "Non, c'est une discrimination interdite et punissable", "Oui, s'il ne donne pas la vraie raison", "Cela dépend du quartier"], c: 1, e: "Non, c'est totalement illégal. Refuser de louer en raison de l'origine est un délit puni jusqu'à 3 ans de prison et 45 000 euros d'amende. Un propriétaire peut choisir selon des critères objectifs (revenus), pas selon l'origine." },
    { id:"sit-1-022", t:1, q: "Samira entend des propos homophobes dans la rue visant un couple d'hommes. Peut-elle porter plainte alors qu'elle n'est pas directement victime ?", o: ["Oui, elle peut signaler ces propos ou témoigner pour les victimes", "Non, seules les victimes directes peuvent porter plainte", "Seulement si elle connaît les victimes", "Non, les propos dans la rue ne comptent pas"], c: 0, e: "Oui, Samira peut agir même si elle n'est pas la victime directe. Elle peut témoigner auprès de la police ou signaler les faits. Les injures homophobes sont un délit aggravé." },
    { id:"sit-1-023", t:1, q: "Lors d'un dîner, quelqu'un tient des propos antisémites devant Hugo. Celui-ci ne dit rien pour ne pas créer de conflit. A-t-il commis une infraction ?", o: ["Oui, ne pas réagir c'est être complice", "Non, mais il aurait pu signaler ces propos", "Oui, il doit obligatoirement intervenir", "Cela dépend du contexte familial"], c: 1, e: "Non, Hugo n'a commis aucune infraction. Il n'existe pas d'obligation légale de dénoncer des propos racistes tenus en privé. Cependant, il peut choisir de signaler ou d'exprimer son désaccord." },
    { id:"sit-1-024", t:1, q: "Aïcha, voilée, se voit refuser l'entrée d'un restaurant par le gérant qui invoque la laïcité. Ce refus est-il légal ?", o: ["Oui, le gérant peut imposer une neutralité religieuse dans son établissement", "Non, c'est une discrimination religieuse interdite", "Oui, si c'est écrit dans le règlement", "Cela dépend du type de restaurant"], c: 1, e: "Non, ce refus est illégal. La laïcité impose la neutralité aux agents publics, pas aux citoyens ni aux commerces privés. Refuser l'accès en raison du voile est une discrimination. Aïcha peut porter plainte." },
    { id:"sit-1-025", t:1, q: "Une entreprise publie une offre d'emploi demandant « un jeune dynamique de 25-35 ans ». Cette annonce est-elle légale ?", o: ["Oui, l'employeur peut cibler le profil qu'il recherche", "Non, c'est une discrimination fondée sur l'âge", "Oui, pour les postes commerciaux", "Seulement pour les CDD"], c: 1, e: "Non, cette annonce est illégale. Mentionner une tranche d'âge constitue une discrimination fondée sur l'âge, interdite par le Code du travail." },
    { id:"sit-1-026", t:1, q: "Claire découvre que son collègue masculin, au même poste et avec la même ancienneté, gagne 200 euros de plus qu'elle chaque mois. Que peut-elle faire ?", o: ["Rien, l'employeur est libre de fixer les salaires comme il veut", "Demander des explications à son employeur et saisir les prud'hommes si nécessaire", "Attendre la prochaine négociation annuelle", "Démissionner car c'est la seule solution"], c: 1, e: "Claire peut agir. Le principe « à travail égal, salaire égal » est inscrit dans le Code du travail. Un employeur ne peut pas payer différemment deux salariés au même poste en raison de leur sexe. Claire peut demander des explications ou saisir les prud'hommes." },
    { id:"sit-1-027", t:1, q: "Le gérant d'un hôtel refuse de donner une chambre à un couple en raison de leur origine étrangère. Ce refus est-il légal ?", o: ["Oui, un commerçant peut choisir ses clients", "Non, c'est une discrimination interdite et punie par la loi", "Oui, s'il affiche ses conditions à l'entrée", "Cela dépend du standing de l'hôtel"], c: 1, e: "Non, ce refus est totalement illégal. Refuser un service en raison de l'origine est une discrimination punie jusqu'à 3 ans de prison et 45 000 euros d'amende. Le couple peut porter plainte." },
    { id:"sit-1-028", t:1, q: "À la mairie, un agent refuse de traiter le dossier de Nadia car elle porte un voile couvrant ses cheveux. Ce refus est-il justifié ?", o: ["Oui, la laïcité s'applique dans les bâtiments publics", "Non, les usagers du service public peuvent porter des signes religieux", "Oui, si le règlement intérieur l'interdit", "Elle doit revenir sans son voile"], c: 1, e: "Non, ce refus est illégal. La laïcité impose la neutralité aux agents du service public, pas aux usagers. Nadia a le droit de porter un voile couvrant ses cheveux tant que son visage reste découvert. Refuser de la servir est une discrimination." },
    { id:"sit-1-029", t:1, q: "Des parents demandent au principal du collège public que leur fille soit placée dans une classe réservée aux filles. L'établissement doit-il accepter ?", o: ["Oui, pour respecter les convictions des familles", "Non, la mixité est un principe de l'école publique", "Oui, si d'autres parents le demandent aussi", "Cela dépend des effectifs du collège"], c: 1, e: "Non, le collège ne peut pas accepter. La mixité est un principe fondamental de l'école publique française depuis 1975. Les établissements publics ne peuvent pas créer de classes séparées selon le sexe." },
    { id:"sit-1-030", t:1, q: "Pierre est maire d'une commune. Son cousin dépose un dossier de permis de construire. Pierre décide de le faire passer en priorité, avant les autres dossiers en attente. Est-ce légal ?", o: ["Oui, le maire peut organiser le travail de ses services comme il le souhaite", "Non, c'est un manquement au principe d'égalité devant le service public", "Oui, si le dossier est complet", "Cela dépend de l'urgence du projet"], c: 1, e: "Non, c'est illégal. Le principe d'égalité impose que tous les usagers soient traités de la même manière. Un élu ne peut pas utiliser sa fonction pour avantager ses proches. C'est un délit de favoritisme puni jusqu'à 5 ans de prison." },
    // === T3 - DROITS ET DEVOIRS (30 questions) ===
    { id:"sit-3-001", t:3, q: "Nicolas vient d'emménager dans une nouvelle ville. Dans quel délai doit-il signaler son changement d'adresse à l'administration ?", o: ["Il n'y a aucune obligation de signaler un changement d'adresse", "Il doit mettre à jour sa carte d'identité et informer les services concernés dans un délai raisonnable", "Il a 48 heures pour le faire", "Seulement s'il change de département"], c: 1, e: "Nicolas doit informer les administrations de son changement d'adresse : impôts, Sécurité sociale, Pôle emploi si concerné, préfecture pour les étrangers. Le service en ligne « Je change d'adresse » permet de prévenir plusieurs administrations en une seule démarche." },
    { id:"sit-3-002", t:3, q: "Amina reçoit une convocation pour être jurée d'assises. Elle n'a pas envie d'y aller car cela perturbe son travail. Peut-elle refuser ?", o: ["Oui, la participation au jury est basée sur le volontariat", "Non, c'est une obligation civique, sauf motif légitime d'excuse", "Oui, si son employeur refuse de la libérer", "Elle peut envoyer quelqu'un à sa place"], c: 1, e: "Non, Amina ne peut pas refuser sans motif légitime. Être juré d'assises est un devoir civique obligatoire. Les seuls motifs d'excuse acceptés sont : avoir plus de 70 ans, maladie grave, ou obligations impérieuses. Refuser sans motif est passible d'une amende de 3 750 euros." },
    { id:"sit-3-003", t:3, q: "Théo, 18 ans, ne s'est jamais inscrit sur les listes électorales. Peut-il voter aux prochaines élections ?", o: ["Non, il doit d'abord s'inscrire volontairement en mairie", "Oui, depuis 2019 l'inscription est automatique à 18 ans", "Non, il a raté le délai", "Seulement pour les élections locales"], c: 1, e: "Oui, Théo peut voter. Depuis 2019, l'inscription sur les listes électorales est automatique pour les jeunes de 18 ans ayant effectué leur recensement citoyen à 16 ans." },
    { id:"sit-3-004", t:3, q: "Martine, retraitée, refuse de remplir le questionnaire du recensement de la population envoyé par l'INSEE. En a-t-elle le droit ?", o: ["Oui, c'est une enquête facultative", "Non, répondre au recensement est obligatoire", "Oui, après 65 ans on est exempté", "Elle peut répondre partiellement"], c: 1, e: "Non, Martine n'a pas le droit de refuser. Répondre au recensement est une obligation légale. Le refus est passible d'une amende de 38 euros. Les données sont confidentielles et essentielles pour planifier les services publics." },
    { id:"sit-3-005", t:3, q: "Éric trouve un portefeuille contenant 500 euros et des papiers d'identité dans la rue. Que doit-il faire légalement ?", o: ["Il peut garder l'argent s'il rapporte les papiers", "Il doit rapporter l'ensemble au commissariat ou à la mairie", "Il peut garder l'argent si personne ne réclame sous 24h", "Il doit chercher le propriétaire lui-même"], c: 1, e: "Éric doit rapporter l'intégralité du portefeuille au commissariat ou à la mairie. Garder un objet trouvé peut être considéré comme un vol. Si le propriétaire n'est pas retrouvé sous un an et un jour, Éric pourra en devenir propriétaire." },
    { id:"sit-3-006", t:3, q: "Carla travaille au noir en plus de son emploi déclaré pour arrondir ses fins de mois. Quelles conséquences risque-t-elle ?", o: ["Aucune, tant qu'elle paie ses impôts sur son emploi principal", "Des sanctions pénales et financières pour travail dissimulé", "Juste un avertissement la première fois", "Rien si elle gagne moins de 500 euros"], c: 1, e: "Carla risque des sanctions importantes. Le travail dissimulé est un délit passible de 3 ans de prison et 45 000 euros d'amende. Elle devra rembourser les cotisations non payées et n'est pas protégée en cas d'accident." },
    { id:"sit-3-007", t:3, q: "Mohamed gagne 2 500 euros par mois. Il trouve que ses impôts sont trop élevés et décide de ne pas payer. Quelles sont les conséquences ?", o: ["L'administration ne peut rien faire s'il conteste le montant", "Il s'expose à des pénalités, majorations et poursuites", "Il peut négocier une réduction", "Rien s'il prouve que c'est trop cher pour lui"], c: 1, e: "Mohamed s'expose à de graves conséquences : majorations de 10%, intérêts de retard, saisies sur salaire ou compte bancaire. En cas de fraude, jusqu'à 5 ans de prison. Payer ses impôts est un devoir constitutionnel." },
    { id:"sit-3-008", t:3, q: "Lucie est auto-entrepreneuse. Elle pense qu'elle n'a pas besoin de payer de cotisations sociales puisqu'elle n'est pas salariée. A-t-elle raison ?", o: ["Oui, seuls les salariés cotisent à la Sécurité sociale", "Non, tous les travailleurs, y compris indépendants, doivent cotiser", "Oui, la première année seulement", "Cela dépend de son chiffre d'affaires"], c: 1, e: "Non, Lucie a tort. Tous les travailleurs doivent payer des cotisations sociales. En tant qu'auto-entrepreneuse, elle paie des cotisations sur son chiffre d'affaires pour financer sa protection sociale." },
    { id:"sit-3-009", t:3, q: "Victor refuse de payer la redevance audiovisuelle car il ne regarde jamais les chaînes publiques. Est-ce un motif valable ?", o: ["Oui, on ne paie que pour ce qu'on utilise", "Non, elle est due dès qu'on possède un téléviseur, quel que soit l'usage", "Oui, s'il peut le prouver", "Il peut demander un remboursement partiel"], c: 1, e: "Non, ce n'est pas un motif valable. La contribution à l'audiovisuel public est due dès qu'on possède un téléviseur, quel que soit l'usage. Note : depuis 2022, cette contribution a été supprimée." },
    { id:"sit-3-010", t:3, q: "Sandra assiste à un accident de la route. Un blessé gît sur le sol. Elle préfère partir sans s'arrêter pour ne pas être impliquée. Est-ce légal ?", o: ["Oui, elle n'est pas obligée de s'impliquer", "Non, c'est un délit de non-assistance à personne en danger", "Oui, si d'autres personnes sont présentes", "Elle doit juste appeler les secours en partant"], c: 1, e: "Non, Sandra commet un délit grave. La non-assistance à personne en danger est punie de 5 ans de prison et 75 000 euros d'amende. Elle doit au minimum alerter les secours (15, 18, ou 112)." },
    { id:"sit-3-011", t:3, q: "Antoine est convoqué comme témoin dans un procès. Il ne veut pas y aller car il ne veut pas « se mêler des affaires des autres ». Peut-il refuser ?", o: ["Oui, témoigner est un choix personnel", "Non, répondre à une convocation de justice est obligatoire", "Oui, s'il n'a rien vu directement", "Il peut envoyer un témoignage écrit"], c: 1, e: "Non, Antoine ne peut pas refuser. La convocation à témoigner est obligatoire. Refuser de comparaître est passible d'une amende de 3 750 euros. C'est un devoir civique essentiel au fonctionnement de la justice." },
    { id:"sit-3-012", t:3, q: "Rachid est victime d'une agression. Il décide de « régler ça lui-même » en allant se venger de son agresseur. Est-ce légal ?", o: ["Oui, c'est de la légitime défense", "Non, seule la justice peut sanctionner les infractions", "Oui, si la police ne fait rien", "Cela dépend de la gravité de l'agression"], c: 1, e: "Non, c'est totalement illégal. En France, nul ne peut se faire justice soi-même. La légitime défense n'existe que pendant l'agression, pas après. Rachid doit porter plainte." },
    { id:"sit-3-013", t:3, q: "Karine est arrêtée par la police pour un contrôle d'identité. Elle refuse de donner son nom et demande un avocat immédiatement. Quels sont ses droits ?", o: ["Elle doit décliner son identité, mais a droit à un avocat seulement en cas de garde à vue", "Elle peut refuser de parler tant qu'un avocat n'est pas présent", "Elle a droit à un avocat immédiatement", "Elle peut refuser le contrôle sans conséquence"], c: 0, e: "Karine doit décliner son identité lors d'un contrôle. Le droit à un avocat n'existe qu'en cas de garde à vue, pas lors d'un simple contrôle. Refuser peut entraîner une vérification au poste (jusqu'à 4 heures)." },
    { id:"sit-3-014", t:3, q: "La voisine de Paul fait énormément de bruit tous les soirs jusqu'à 2h du matin. Que peut faire Paul légalement ?", o: ["Appeler la police, car le tapage nocturne est une infraction", "Rien, chacun est libre chez soi", "Seulement envoyer une lettre recommandée", "Porter plainte uniquement après 3 avertissements"], c: 0, e: "Paul peut appeler la police. Le tapage nocturne (entre 22h et 7h) est une infraction punie d'une amende de 68 à 450 euros. La liberté de chacun s'arrête là où commence celle des autres." },
    { id:"sit-3-015", t:3, q: "Sophie est embauchée en CDI. Son employeur lui demande de travailler 50 heures par semaine sans payer d'heures supplémentaires. Est-ce légal ?", o: ["Non, la durée légale est de 35 heures et les heures supplémentaires doivent être payées ou compensées", "Oui, l'employeur décide des horaires", "Oui, pour les cadres", "Cela dépend de la convention collective"], c: 0, e: "Non, c'est illégal. La durée légale est de 35 heures. Les heures supplémentaires doivent être majorées (25% puis 50%) ou compensées en repos. Sophie peut saisir l'inspection du travail." },
    { id:"sit-3-016", t:3, q: "Marc, salarié, apprend que son collègue au même poste gagne plus que lui. Il demande des explications à son employeur, qui refuse de répondre. Est-ce normal ?", o: ["Oui, les salaires sont confidentiels", "Non, l'employeur doit pouvoir justifier les différences de salaire", "Oui, c'est un choix de l'entreprise", "Marc n'a pas le droit de poser cette question"], c: 1, e: "Non, l'employeur devrait justifier les écarts. Le principe « à travail égal, salaire égal » est dans le Code du travail. Toute différence doit être justifiée par des critères objectifs." },
    { id:"sit-3-017", t:3, q: "Fatima est enceinte et son employeur lui propose de « rompre d'un commun accord » son contrat. Que doit-elle savoir ?", o: ["C'est une bonne opportunité à saisir", "Elle est protégée contre le licenciement et doit être vigilante", "Elle doit accepter si l'offre est généreuse", "C'est illégal de lui proposer cela"], c: 1, e: "Fatima doit être très vigilante. Une salariée enceinte bénéficie d'une protection renforcée contre le licenciement. Elle devrait consulter l'inspection du travail ou un syndicat avant de signer quoi que ce soit." },
    { id:"sit-3-018", t:3, q: "Julien est licencié pour faute grave. Son employeur lui demande de partir immédiatement sans préavis ni indemnités. Est-ce normal ?", o: ["Oui, la faute grave prive le salarié de préavis et d'indemnités de licenciement", "Non, tout licenciement donne droit à des indemnités", "Seulement si c'est écrit dans le contrat", "Il garde le droit au préavis"], c: 0, e: "Oui, c'est légal. En cas de faute grave, le salarié est privé de préavis et d'indemnités de licenciement. Il conserve cependant ses droits au chômage. Julien peut contester la qualification aux prud'hommes." },
    { id:"sit-3-019", t:3, q: "Nadia travaille depuis 3 mois en CDD. Elle tombe malade et son employeur veut rompre son contrat. En a-t-il le droit ?", o: ["Oui, la maladie est un motif de rupture de CDD", "Non, la maladie ne permet pas de rompre un CDD avant son terme", "Oui, après 1 mois de maladie", "Cela dépend de la durée du CDD"], c: 1, e: "Non, l'employeur ne peut pas rompre le CDD pour maladie. Un CDD ne peut être rompu avant terme que pour : accord mutuel, faute grave, force majeure, ou embauche en CDI ailleurs." },
    { id:"sit-3-020", t:3, q: "Thomas refuse de faire vacciner son enfant contre les maladies obligatoires pour l'entrée en collectivité. L'école peut-elle refuser l'inscription ?", o: ["Non, c'est le choix des parents", "Oui, certaines vaccinations sont obligatoires pour l'entrée en collectivité", "Seulement pour les crèches", "L'école doit accepter avec une décharge"], c: 1, e: "Oui, l'école peut refuser. Depuis 2018, 11 vaccins sont obligatoires pour les enfants. Cette obligation protège l'enfant vacciné et ceux qui ne peuvent pas l'être (immunité collective)." },
    { id:"sit-3-021", t:3, q: "Christine est médecin. Un patient lui demande de lui prescrire un médicament qu'elle juge inutile et potentiellement dangereux. Doit-elle accepter ?", o: ["Oui, le patient a le droit de choisir son traitement", "Non, le médecin a le devoir de refuser une prescription qu'il juge inappropriée", "Oui, si le patient signe une décharge", "Elle doit demander un second avis"], c: 1, e: "Non, Christine doit refuser. Un médecin a le devoir déontologique de ne prescrire que des traitements qu'il juge nécessaires et adaptés. Le patient ne peut pas exiger un traitement contraire à l'avis médical." },
    { id:"sit-3-022", t:3, q: "Ahmed est affilié à la Sécurité sociale mais ne va jamais chez le médecin. Il demande à être remboursé de ses cotisations « inutilisées ». Est-ce possible ?", o: ["Non, la Sécurité sociale fonctionne sur le principe de solidarité, pas d'épargne individuelle", "Oui, il peut récupérer ce qu'il n'a pas consommé", "Oui, sous forme de crédit santé", "Partiellement, après 5 ans sans soins"], c: 0, e: "Non, ce n'est pas possible. La Sécurité sociale fonctionne sur la solidarité : chacun cotise selon ses moyens et reçoit selon ses besoins. Ceux en bonne santé financent les soins des malades." },
    { id:"sit-3-023", t:3, q: "Pendant une canicule, la mairie demande aux habitants de prendre des nouvelles de leurs voisins âgés isolés. Patrick trouve que ce n'est pas son rôle. A-t-il raison ?", o: ["Oui, c'est le rôle des services sociaux, pas des particuliers", "Non, la solidarité entre voisins fait partie du civisme républicain", "Oui, il n'est pas formé pour ça", "Seulement s'il connaît ses voisins"], c: 1, e: "Patrick a tort. La solidarité entre voisins est une valeur civique fondamentale, expression de la fraternité républicaine. Pendant les canicules, un simple appel peut sauver des vies." },
    { id:"sit-3-024", t:3, q: "Léo jette ses déchets par la fenêtre de sa voiture sur l'autoroute. Que risque-t-il ?", o: ["Rien, ce n'est pas interdit", "Une amende pour dépôt sauvage de déchets", "Juste un rappel à l'ordre", "Une amende seulement si quelqu'un le voit"], c: 1, e: "Léo risque une amende de 135 euros (jusqu'à 750 euros). Jeter des déchets sur la voie publique est interdit, pollue l'environnement et peut causer des accidents." },
    { id:"sit-3-025", t:3, q: "Maria laisse son chien faire ses besoins sur le trottoir sans ramasser. Une voisine lui fait remarquer. Maria répond que ce n'est pas grave. A-t-elle raison ?", o: ["Non, ne pas ramasser les déjections de son animal est une infraction", "Oui, ce n'est qu'un détail sans importance", "Cela dépend de la commune", "Seulement dans les parcs c'est obligatoire"], c: 0, e: "Non, Maria a tort. Ne pas ramasser les déjections est une infraction passible d'une amende de 68 à 450 euros. Le civisme, c'est penser à la collectivité dans les petits gestes du quotidien." },
    { id:"sit-3-026", t:3, q: "Julie a de faibles revenus et doit se défendre au tribunal dans un litige avec son ancien propriétaire. Elle n'a pas les moyens de payer un avocat. Existe-t-il une solution ?", o: ["Non, les avocats sont toujours payants", "Oui, elle peut demander l'aide juridictionnelle pour avoir un avocat gratuit", "Elle doit se défendre seule", "Seulement si elle trouve un avocat bénévole"], c: 1, e: "Oui, Julie peut bénéficier de l'aide juridictionnelle. Ce dispositif permet aux personnes aux revenus modestes d'obtenir la prise en charge des frais de justice. L'accès à la justice ne doit pas dépendre des moyens financiers." },
    { id:"sit-3-027", t:3, q: "Nicolas, employé dans une entreprise privée, est mécontent de ses conditions de travail. Il veut faire grève avec ses collègues. Doit-il demander l'autorisation à son employeur ?", o: ["Oui, la grève doit être autorisée par l'employeur", "Non, le droit de grève est un droit constitutionnel qui ne nécessite pas d'autorisation", "Oui, avec un préavis de 5 jours", "Seulement si le syndicat l'approuve"], c: 1, e: "Non, Nicolas n'a pas besoin d'autorisation. Le droit de grève est constitutionnel. Dans le secteur privé, les salariés peuvent faire grève sans préavis. Dans le secteur public, un préavis de 5 jours est obligatoire." },
    { id:"sit-3-028", t:3, q: "Antoine apprend que sa compagne est enceinte. Il se demande s'il aura le droit de s'absenter de son travail à la naissance de l'enfant. Que dit la loi ?", o: ["Cela dépend de la bonne volonté de l'employeur", "Il a droit à un congé paternité obligatoirement accordé par l'employeur", "Seulement s'il est marié", "Il doit poser des congés payés"], c: 1, e: "Antoine a droit au congé paternité de 25 jours (32 pour naissances multiples). L'employeur ne peut pas refuser. Ce droit reconnaît le rôle des pères et favorise l'égalité entre les parents." },
    { id:"sit-3-029", t:3, q: "Marie entend régulièrement des cris d'enfant et des bruits de coups provenant de l'appartement de ses voisins. Elle hésite à intervenir car elle ne veut pas se mêler de la vie des autres. Que doit-elle faire ?", o: ["Ne rien faire, c'est une affaire privée entre voisins", "Signaler la situation aux autorités car la protection des enfants est l'affaire de tous", "Attendre d'avoir des preuves concrètes", "En parler d'abord aux voisins concernés"], c: 1, e: "Marie doit signaler cette situation. Elle peut appeler le 119 (enfance en danger), contacter les services sociaux ou la police. Un simple doute suffit pour signaler. Protéger les enfants est un devoir civique." },
    { id:"sit-3-030", t:3, q: "Lors d'un entretien d'embauche, le recruteur demande à Sophie de préciser sa religion sur un formulaire. Sophie est mal à l'aise. Doit-elle répondre ?", o: ["Oui, l'employeur a le droit de connaître le profil complet des candidats", "Non, cette question est interdite et Sophie peut refuser d'y répondre", "Oui, si c'est pour organiser les jours de congé", "Elle doit répondre sincèrement"], c: 1, e: "Non, Sophie n'est pas obligée de répondre. Les questions sur la religion sont interdites lors d'un recrutement. Sophie peut refuser de répondre ou mentir sans conséquence. C'est une discrimination si l'employeur insiste." },
    { id:"sit-3-031", t:3, q: "Pierre est sans logement depuis plusieurs mois malgré ses recherches. Il a entendu parler d'un « droit au logement ». Existe-t-il un recours légal pour obtenir un logement ?", o: ["Non, l'État n'est pas obligé de fournir un logement", "Oui, le droit au logement opposable (DALO) permet de saisir une commission", "Seulement pour les familles avec enfants", "Il doit attendre son tour en HLM"], c: 1, e: "Oui, Pierre peut faire valoir le DALO. Depuis 2007, les personnes sans logement peuvent saisir une commission. Si aucun logement n'est proposé, l'État peut être condamné à le reloger." }
];